WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[12267] = { title = "Neltharion's Flame", description = "With the cult's ranks thinned and some of their power stripped, it's time to strike at the source of the corruption.\n\nRothin the Decaying is resurrecting black dragons as magmawyrms in the back of the cave. Go to the summoning chamber and cleanse the remaining bones in the only way that will ensure that they will never be toyed with again... with flame.\n\nBurning the bones will surely gain Rothin's attention, see to it that he is destroyed as well.\n\nThe magic in this vial should see the task done.", objectives = "" }
WordHunterWoW_QuestEN[12268] = { title = "Pieces Parts", description = "Ack! This thing's a mess!\n\nGoblin engineering leaves a great deal to be desired, believe you me. Just look at this! It's a wonder it ever worked to begin with.\n\nGive me a hand, will ya? To get this even close to operable specifications I'll need to replace a few cogs, sprockets, and springs. You should have no trouble finding them down around the sawmill.", objectives = "" }
WordHunterWoW_QuestEN[12269] = { title = "Not In Our Mine", description = "That blasted necropolis blindsided us! In the wake of its destruction Wintergarde Mine was lost. Worse yet, Kel'Thuzad's acolytes have raised the slain miners as Scourge and are using them to supply their siegesmiths with materials from our mine!\n\nThe supply line must be halted and our lost brothers must be put to rest.\n\nTravel to Wintergarde Mine, northeast of here in the Carrion Fields, and destroy the risen miners. Return to me with their miner cards so that I may put their passing in our registry.", objectives = "" }
WordHunterWoW_QuestEN[12270] = { title = "Shred the Alliance", description = "Read my lips, {class} - I need those shredders! Just as important - I need to keep them out of the hands of the Alliance!\n\nThey've been refurbishing the shredders and using them against our brothers in Venture Bay. Now we're going to give them a taste of their own medicine!\n\nYou see a shredder out there, grab it! You see one of the Alliance scum on one, kill 'em and then grab it! Once you have one, drive it back here to me and we'll get to work on it.\n\nDismissed!", objectives = "" }
WordHunterWoW_QuestEN[12271] = { title = "The Rod of Compulsion", description = "A rod drops from Alphonse's dead hand. There are pulsing magical runes along its length.\n\nCould this be how he was getting his confessions?\n\nBetter let the high executor have a look at it.", objectives = "" }
WordHunterWoW_QuestEN[12272] = { title = "The Bleeding Ore", description = "Hours before the Naxxramas invasion, one of the miners stumbled upon a dark ore that was oozing a viscous fluid. In the chaos that occurred during the evacuation of the mine, we lost the samples taken from the alien node. Now the Scourge prospects the ore for use in their machines of death.\n\nYou must get back to Wintergarde Mine, due northeast of here in the Carrion Fields, and recover the strange ore. It is imperative to our mission's success!", objectives = "" }
WordHunterWoW_QuestEN[12273] = { title = "The Denouncement", description = "It's time for us to utterly demoralize the Onslaught forces!\n\nI want you to take the rod and use it on four of their leaders: Commander Jordan upstairs at the barracks, Lead Cannoneer Zierhut down the southeast ramp overlooking the beach, Blacksmith Goodman at the smithy, and Stable Master Mercer at the stables.\n\nPlace them under the rod's compulsion, concentrate on making them denounce the Onslaught, and then kill them!", objectives = "" }
WordHunterWoW_QuestEN[12274] = { title = "A Fall From Grace", description = "We need more information from the high abbot, and now that we have the visage of one of the raven priests, I think we can get you close to talk with him.\n\nUnfortunately, we need to separate him from his bodyguards or you'll never get any information out of him.\n\n<The agent leans on her shovel and thinks a moment.>\n\nI think I've got it! While in disguise, go to the top of the abbey and ring the bell. That should bring the abbot's bodyguards running and you can then head down to speak with him.", objectives = "" }
WordHunterWoW_QuestEN[12275] = { title = "The Demo-gnome", description = "Quarterflash recently requisitioned my group for a specialist that he could send on a reconnaissance mission to the Wintergarde Mine. To that end, I sent him Slinkin, my demolitionist. I foolishly thought that he could close off that pit of damnation after his mission for Quarterflash was complete, securing another victory for us against the Scourge.\n\nAn entire day has now passed and Slinkin has not returned. I want answers! Speak with Siege Engineer Quarterflash and track down my missing agent!", objectives = "" }
WordHunterWoW_QuestEN[12276] = { title = "The Search for Slinkin", description = "While I have not heard from Slinkin or know what fate has befallen him, perhaps I can assist in finding him.\n\n<Quarterflash holds up a tiny mechanical toy.>\n\nThis is not a toy, newfound compatriot. It is, in fact, my latest mechanical creation. The machine was created with the sole purpose of finding that which has been lost. These are unfortunate circumstances, but the machine is your best chance at finding Slinkin.\n\nWhen you are ready to begin your search, place the bot on the ground next to me.", objectives = "" }
WordHunterWoW_QuestEN[12277] = { title = "Leave Nothing to Chance", description = "If there is good in your heart and your conscience is clear, read on.\n\nIn this mine, near the foreman's scaffold, rests a hefty cargo of dynamite. Go there and pick up several bundles of the explosive and make your way towards the entrance of the mine. Once there, set the dynamite and blow up the entrance. Remember to do this for the upper and lower entry points of Wintergarde Mine.\n\nYou must leave nothing to chance. The evil that exists here must never be allowed out. Light guide you.", objectives = "" }
WordHunterWoW_QuestEN[12278] = { title = "Brew of the Month Club", description = "Membership has its privileges.  Being part of the \"Brew of the Month\" club means knowing where to get the latest and greatest brew.\n\nBring your \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.", objectives = "" }
WordHunterWoW_QuestEN[12279] = { title = "A Bear of an Appetite", description = "Thank goodness you're back, Limpy! I worried that Griselda and I were going to be all alone.\n\nI'm cooking up some food here for us, but Griselda'll have none of it.\n\nShe's fond of the fish that live off the coast of the Eastwind Shore, to the east. Can't stand them myself, but she's always been a picky eater. Six good-sized fish ought to keep her happy for a while.\n\nNow, run... err... limp along, Joe. Wouldn't want to keep the girl waiting, would ya?", objectives = "" }
WordHunterWoW_QuestEN[12280] = { title = "Making Repairs", description = "Twenty shredders by noon tomorrow!\n\nWho makes these schedules, anyway? No one who ever put one of these garbage cans back together, that's who....\n\nIf I'm going to hit my quota, I'll need a hand. Help me out and I'll share my commission with you - fair enough?\n\nI need cogs, sprockets and springs. They're littered across the ground down by the shredders.", objectives = "" }
WordHunterWoW_QuestEN[12281] = { title = "Understanding the Scourge War Machine", description = "We must take solace in the fact that Slinkin's death, while tragic, was for the greater good. His discovery coupled with your heroics in the mine and the samples you returned brings us one step closer to understanding the Scourge war machine.\n\nTake this package to High Commander Halford Wyrmbane. It holds a sample of the strange ore and my analysis.", objectives = "" }
WordHunterWoW_QuestEN[12282] = { title = "Imprints on the Past", description = "The memories of the past haunt this land, {name}. I hear the cries of the fallen echo across Northrend - calling to me.\n\nArthas left a terrible imprint on everything he touched. Only wither and decay remains in his wake. It is important, then, for us to study the past so that we may better know our enemy. Perhaps untold truths shall surface that could help in our campaign.\n\nFirst, you must recover my scrying orb from the town hall, {name}. Exit this tower and turn left down the path to reach the town square.", objectives = "" }
WordHunterWoW_QuestEN[12283] = { title = "The Truth Will Out", description = "We have to figure out what's going on here. We need the general's diary!\n\nI'm pretty sure that you'll find it on her nightstand upstairs at her house. It's the one next to church, across from the stables and the lumbermill.\n\nOnce you acquire the diary, take it to the high executor back at Venomspite.\n\nYou'll have to do this the old-fashioned way; the power of the mirror is low and there's only enough left for me.\n\n<The agent smirks.>", objectives = "" }
WordHunterWoW_QuestEN[12284] = { title = "Keep 'Em on Their Heels", description = "We've suffered heavy casualties here, {race}.\n\nThe only good news is that we've given as much as we've taken. I've requested more troops, but the bulk of our forces are bogged down in Venture Bay. It looks like we're on our own for now.\n\nNo matter how bad it gets, we MUST stand our ground! The precious resources of this region are essential to the Horde's long-term success in Northrend.\n\nWe've got to keep the Alliance on their heels until help arrives. Get out there and give 'em something to think about.", objectives = "" }
WordHunterWoW_QuestEN[12285] = { title = "Do Unto Others", description = "Their attack is imminent, {class}. I need you to get in there and sever the head of the Scarlet Onslaught, literally!\n\nIt's not going to be easy... Abbendis is sure to be surrounded by a great many of her men.\n\nBring back her head and I'll see to it that you're properly rewarded for saving Venomspite.\n\nFail and don't even bother to return!", objectives = "" }
WordHunterWoW_QuestEN[12286] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[12287] = { title = "Orik Trueheart and the Forgotten Shore", description = "I have gazed upon the orb and seen the path that you must walk, {name}.\n\nMany years ago an atrocity was committed upon the shores of Dragonblight. The act itself remains shrouded in darkness, but I am certain that your destiny lies south, amidst the ruins of the Forgotten Shore.\n\nTake the road southeast through the ravaged town square. Follow the trail until you arrive at Dawn's Reach. You will meet an old friend of mine there known as Orik Trueheart. He will be expecting you.", objectives = "" }
WordHunterWoW_QuestEN[12288] = { title = "Overwhelmed!", description = "You there, {class}! Help me!\n\nWe're losing valuable lives! There are simply too many wounded for me to tend to alone. If we can't get our soldiers healed we could be run out of Grizzly Hills altogether!\n\nTake this tourniquet and use it on the wounded down on the battlefield.\n\nHurry, {name}! They're dyyying!!", objectives = "" }
WordHunterWoW_QuestEN[12289] = { title = "Kick 'Em While They're Down", description = "It is a dark day for the Alliance. Many good men lay dead or dying here. Our only consolation is that they fought well and brought down many of the enemy with them.\n\nWith the bulk of our forces committed to Venture Bay we stand alone to weather this storm. The resources in this region are vital to the Alliance and may well make the difference in our struggle against the Horde. We must not fail!\n\nGo, {name}. Strike at them while they lick their wounds. Avenge your fallen brothers and keep our hopes alive!", objectives = "" }
WordHunterWoW_QuestEN[12290] = { title = "The Murkweed Elixir", description = "The spirits of the damned haunt the coast. In life they were brave and noble soldiers of the Alliance, but in death they are cursed - bound to this world until the end of days. We must discover the source of their anguish if we are to free them!\n\nTo the southeast, on the Eldritch Heights, you will find a rare herb known as murkweed. It is murkweed that I will use to concoct an elixir that will allow you temporary entry into the world of the forgotten. Go now and gather the weed.", objectives = "" }
WordHunterWoW_QuestEN[12291] = { title = "The Forgotten Tale", description = "The toxins in the murkweed elixir will render you unconscious. So powerful is the effect of the murkweed that even your spirit will be fooled, allowing you to temporarily enter the world of the dead.\n\nOnce a spirit, you must speak to the ghostly denizens of the Forgotten Shore. Seek out the cause of their anguish and return to me.\n\nRemember, {name}, these spirits were once Alliance soldiers. Treat them with respect, honor, and dignity.\n\nNow, with elixir in hand, venture south to the Forgotten Shore.", objectives = "" }
WordHunterWoW_QuestEN[12292] = { title = "Local Support", description = "We've reached a deadlock with the Horde in Grizzly Hills.  Our forces are just about evenly matched and all signs so far have pointed to a stalemate.\n\nUntil this morning, that is.  The local trappers have requested our help.  Apparently the Horde took something that belongs to them... a relic of some sort.\n\nWe get this back for them and they'll give us the edge we need.  Head to the Evergreen Trading Post, west of Conquest Hold and look for a cedar chest.", objectives = "" }
WordHunterWoW_QuestEN[12293] = { title = "Close the Deal", description = "We have what the trappers want.  Now it's up to us to sign them up with our side.\n\nTake the chest to a trapper named Ivan at the Aspen Grove Post, just north of here.\n\nIf all goes well, we'll have local woodsmen serving as scouts for the king's army in no time.", objectives = "" }
WordHunterWoW_QuestEN[12294] = { title = "A Tentative Pact", description = "Very well, {name}.  Your people kept their end of the bargain.\n\nTell Dumont that we'll honor the deal.", objectives = "" }
WordHunterWoW_QuestEN[12295] = { title = "An Exercise in Diplomacy", description = "We'd been trying to negotiate with the trappers for weeks, but we'd gotten nowhere until you found that blasted chest of theirs.\n\nThis should be good news to our envoy in Silverbrook.  We sent Ducal there about a week ago and his last letter indicated he'd been making little progress.\n\nGo to Silverbrook and aid him in his diplomatic efforts.  Take the roads heading northwest of here and you should find it after crossing a couple of bridges. ", objectives = "" }
WordHunterWoW_QuestEN[12296] = { title = "Life or Death", description = "Oh, the carnage....\n\nI've been through many battles, {class}, and this one was more brutal than any I've seen. Our fight with the Horde has become more intense than ever. It's them or us here in Northrend - life or death.\n\nIf we are to survive here another day we'll need to mend our wounded. There are too many for me to rescue alone.\n\nI've prepared special bandages that will enable you to assist me. Take one and tend to those who have not yet succumbed to their wounds.", objectives = "" }
WordHunterWoW_QuestEN[12297] = { title = "Of Traitors and Treason", description = "The list I hold must be delivered to High Commander Halford Wyrmbane. He commands the 7th Legion, stationed at Wintergarde Keep on the eastern borders of the Great Dragonblight.\n\nIf any of the traitors on this list are stationed at Wintergarde... it could be catastrophic.\n\nHurry, {name}. Show the document to Greer Orehammer here at Westguard Keep and explain the nature of your mission. He'll put you on his fastest gryphon to Wintergarde!", objectives = "" }
WordHunterWoW_QuestEN[12298] = { title = "High Commander Halford Wyrmbane", description = "<Greer hands the missive back to you.>\n\nSkysong will take you to Wintergarde, {name}. I guarantee you that it will be the fastest flight you've ever taken. Go now!\n", objectives = "" }
WordHunterWoW_QuestEN[12299] = { title = "Northern Hospitality", description = "It's good to meet you.  Let us celebrate our pact by partaking in some good old fashioned Horde-killing.\n\nYou'll find marauders from Conquest Hold just outside our town, west of here.  Why don't you head out there and hunt them like the filthy animals they are?\n\nLet's see if our new allies can back all their talk with some action.", objectives = "" }
WordHunterWoW_QuestEN[12300] = { title = "Test of Mettle", description = "Alright, friend.  You've done us a favor or two, but that's not the true test of a person's courage.\n\nAround these parts, you're not a real hunter unless you wear your prey's skin.\n\n<Sergei unsheathes his skinning knife and hands it to you.>\n\nThe leader of those motherless orcs attacking our town is called Bonesnap; you'll find him at a camp further northwest.\n\nThat's right.  You're going to skin the monster.", objectives = "" }
WordHunterWoW_QuestEN[12301] = { title = "The Truth Shall Set Us Free", description = "Zelig gave this crystal ball to me years ago with specific instruction on its use. For five years, whenever I would feel anger, anxiety, or sorrow over the events that transpired here, I was to focus my thoughts upon the orb.\n\nI now understand why Zelig gave this crystal to me.\n\nTake my crystalline orb to the Forgotten Shore. Find the ruins of my old base on the upper reaches of the beach and place the orb in the center of town. Let the forgotten see the world through my heart and soul.", objectives = "" }
WordHunterWoW_QuestEN[12302] = { title = "Words of Warning", description = "Thanks for helping me, {name}.  My name's Sasha.  Listen, I have to get the hell out of here.\n\nThe people that sent you here... my people... they've changed.  They're not good people anymore... and they want to turn you into one of... one of them.\n\nThis... 'test' they sent you on is just the beginning.\n\nHead to the northwestern end of Silverbrook.  You'll find something of interest to you.\n\nGood luck... and trust no one.", objectives = "" }
WordHunterWoW_QuestEN[12303] = { title = "Funding the War Effort", description = "<The quartermaster lowers his voice and whispers to you.>\n\n{class}, I need your help; our coffers are empty. The Kor'kron Vanguard at the Wrath Gate has taken all of our coin for the fight there.\n\nBut, I've heard whispers that there's treasure to be had amongst the wrecks on the Forgotten Shore to the southeast.\n\nWe have to do something soon, or we won't be able to continue the fight against the Scarlet Onslaught. War isn't cheap, you know!", objectives = "" }
WordHunterWoW_QuestEN[12304] = { title = "Beachfront Property", description = "It's time for Venomspite to expand!\n\nWe'll take care of the Onslaught in due time, but I want you to spearhead our efforts on the Forgotten Shore. The property value has outstanding potential and just look at that view!\n\nUnfortunately, there's an infestation of human ghosts, shipwrecked crews and the like who haven't quite realized that they're dead.\n\nClear the beach and the waters off the shore, and maybe you and I will talk about building a cozy, new mausoleum down there soon.", objectives = "" }
WordHunterWoW_QuestEN[12305] = { title = "Parting Thoughts", description = "You have honored me and honored the memory of hundreds of Alliance veterans, {name}. Zelig was wise in sending you here. Please return to him and give him my thanks. He will be happy to hear of the events that transpired at the Forgotten Shore.\n\nI do not have the gift of foresight like Zelig, but I am certain that great things await you, friend.\n\nFarewell. \n", objectives = "" }
WordHunterWoW_QuestEN[12306] = { title = "Brew of the Month Club", description = "There is strength in numbers, {name}.  Being part of the \"Brew of the Month\" club means knowing you and your brethren will always have access to the best brew.\n\nBring your \"Brew of the Month\" club membership form to Ray'ma in Orgrimmar.", objectives = "" }
WordHunterWoW_QuestEN[12307] = { title = "Wolfsbane Root", description = "Have you heard of the wolfsbane plant?  It is a horrible weed... it destroys our farmable crops.\n\nWe spent all of last week cutting them down, but the roots are beginning to sprout again.\n\nIt might not seem like an urgent matter, but a resurgence of the plant could be a real... disaster.  Do you think you could help us by uprooting them where you find them near the village?", objectives = "" }
WordHunterWoW_QuestEN[12308] = { title = "Escape from Silverbrook", description = "You... you're not one of them?  Quick!  Let me out!\n\nWe have to get to Amberpine Lodge immediately!  Once Lieutenant Dumont finds out who these people really are, this town will be reduced to rubble!", objectives = "" }
WordHunterWoW_QuestEN[12309] = { title = "Find Durkon!", description = "After the Scourge breached the south wall, I ordered Cavalier Durkon to investigate the town crypt. Moments ago I was handed his report.\n\nThe undead that plague us are coming from two sources: the ruins of Wintergarde, now a breeding ground for Scourge, and our very own town crypt! Amidst the chaos and confusion the Scourge managed to get a necrolord inside the crypt.\n\nIn his message, Durkon requested assistance. You will find him and help him, {name}. The crypt is on the western border of the town square.", objectives = "" }
WordHunterWoW_QuestEN[12310] = { title = "A Swift Response", description = "Our response must be immediate.  Decisive.  We must teach these savages not to cross us.\n\nOur scouts have located what's left of the Silverbrook trappers... you know, the ones you didn't get to douse in flames.  Apparently they're blockading the road to the southeast... perhaps they're trying to box us in.\n\nHead to the Forest's Edge post and take care of them.  Their leader's reported to be a man named Vladek... make sure he's dealt with.", objectives = "" }
WordHunterWoW_QuestEN[12311] = { title = "The Noble's Crypt", description = "Held within the cold stone walls of this crypt are the remains of the nobles and dignitaries that died in Northrend. At its very core now sits a necrolord who raises the corpses as servants of the Scourge.\n\nYou must make your way to the bottom of the Wintergarde Crypt and kill Necrolord Amarion. Only then will the assault from within cease!\n\nAnd {name}, be on the lookout for any information that might be laying about inside the room where Amarion resides. \n", objectives = "" }
WordHunterWoW_QuestEN[12312] = { title = "Secrets of the Scourge", description = "Scrawled across the flesh-bound chapters of this tome are strange symbols and shapes that seem to have been scraped into the pages with a blade. You have no idea what is written, but you are certain that whatever it is, it must be important.\n\nDeliver the tome to Cavalier Durkon standing guard topside at Wintergarde Crypt.", objectives = "" }
WordHunterWoW_QuestEN[12314] = { title = "Down With Captain Zorna!", description = "The Horde's forces are poised to break through our lines and complete their conquest of Venture Bay if we do not act. The Horde's forces in the port are commanded by Captain Zorna, near the ship on the far side of the bay.\n\nIf you can defeat her, the Horde's offensive will falter and we can seize the chance to capture the port. Beware, {name}, for Zorna is a fierce fighter. It may take several people to defeat her, or if you have access to a repaired shredder, you might try using it to your advantage.", objectives = "" }
WordHunterWoW_QuestEN[12315] = { title = "Crush Captain Brightwater!", description = "With every advance, our men are met by fresh Alliance reinforcements. It's almost as though their commander anticipates my every move!\n\nThe time has come for good Captain Brightwater to meet his end. He commands his troops from aboard an Alliance destroyer at the far end of the bay.\n\nThis will be no easy fight, {name}. Take along a couple of trusted friends, or if you have a key to one of those repaired shredders, use it to disembowel Brightwater! Either way, he must fall!", objectives = "" }
WordHunterWoW_QuestEN[12316] = { title = "Keep Them at Bay!", description = "We cannot permit the Horde to control Venture Bay. The port is essential to our operations in Grizzly Hills and beyond.\n\nCaptain Stoutmantle has taken the rest of the Westfall Brigade east in search of a passage through the mountains, so we'll have no reinforcements.\n\nGo into the field, {name}, and kill the Conquest Hold berserkers the Horde has sent against us. Cut them down until none remain standing. The Alliance must have this port!", objectives = "" }
WordHunterWoW_QuestEN[12317] = { title = "Keep Them at Bay", description = "This wretched Westfall Brigade is proving a tougher opponent than we'd thought. Though few in number, they fight well and bravely, but we cannot afford to wait them out.\n\nConqueror Krenna's orders were to capture the port quickly. You must break the stalemate, {name}. Find the enemy's marines and slaughter them until the resistance ceases. Only then will we be able to claim ownership of the port.\n\nGo quickly. We don't want to keep Conqueror Krenna waiting.", objectives = "" }
WordHunterWoW_QuestEN[12318] = { title = "Save Brewfest!", description = "{name}, our spies have discovered a fiendish plot! The Dark Iron dwarves want our beloved Brewfest destroyed!\n\nCoren Direbrew, head of a renegade family of brewers, has marshaled the dwarves of Blackrock Depths. Their vile mole machines attack us constantly.\n\nOur spy is in the Grim Guzzler, a tavern in the bowels of Blackrock Depths. He'll know more of Direbrew's plot.\n\nFind our spy. Save Brewfest!", objectives = "" }
WordHunterWoW_QuestEN[12319] = { title = "Mystery of the Tome", description = "What can it be, {name}? That was certainly no ordinary curse that the blasted lich put on you!\n\n<Durkon flips through the grisly pages of the tome.>\n\nI don't even know if I'm looking at it the right way. We must find out what information is held within this tome!\n\n<Durkon hands the book back to you.>\n\nThe High Commander will know what to do. Take the flesh-bound tome to him and tell him exactly what happened here.", objectives = "" }
WordHunterWoW_QuestEN[12320] = { title = "Understanding the Language of Death", description = "Take the book and follow the path leading up to the barracks. Once inside the barracks take the staircase down to the prison. At the prison you will find Inquisitor Hallard and our mayor, Godfrey. I believe Godfrey might be the missing piece of this puzzle and Hallard the man to put it all together.\n\nGo now!", objectives = "" }
WordHunterWoW_QuestEN[12321] = { title = "A Righteous Sermon", description = "Godfrey Goodard, once a righteous man and mayor of Wintergarde, is now an agent of the Scourge. His transformation from man to undying ghoul has taken place slowly, over time. He hears the call of the Lich King now and lives only to serve his master.\n\nBut as with all Scourge, Godfrey knows the language of death and with proper motivation, will tell us what we need to know about the tome.\n\nOnce you hear what you need to hear, return to the High Commander at the front lines. I'll clean up here as needed.", objectives = "" }
WordHunterWoW_QuestEN[12323] = { title = "Smoke 'Em Out", description = "There are still pockets of cowardly Venture Company men holed up in some of the buildings at the center of Venture Bay. I need every man I can spare out there fighting against the Horde, but we can't allow those Venture Company stragglers to camp out in those buildings, either.\n\nMaybe we can \"convince\" them to make for their ship. Take this smoke bomb and use it to smoke out the stragglers from their places in the bunkhouse, sawmill, or stables. Don't get too close, though; they probably bite.", objectives = "" }
WordHunterWoW_QuestEN[12324] = { title = "Smoke 'Em Out", description = "Not only is this port infested with sniveling Alliance cowards, but to make matters worse, there are still Venture Company employees holed up in some of the buildings. They're not worth the time it takes to kill and I can't spare the warriors anyway.\n\nMaybe we can \"convince\" them to make for their ship. Take this smoke bomb and use it to smoke out the stragglers from their places in the bunkhouse, sawmill, or stables. Don't get too close, though; there's no telling what diseases they're carrying.", objectives = "" }
WordHunterWoW_QuestEN[12325] = { title = "Into Hostile Territory", description = "You have done much to advance our efforts against the Scourge, {name}. In fact, the morale of all those who have come into contact with you soars! Such is your influence over the soldiers and citizenry of Wintergarde, ally.\n\nAnd because of you we are now prepared to go on the offensive! You are to report to Duke August Foehammer, across the Carrion Fields at Thorson's Post, east of here. Gryphon Commander Urik at the gryphon station has prepared a special gryphon to drop you behind enemy lines. Go now!", objectives = "" }
WordHunterWoW_QuestEN[12326] = { title = "Steamtank Surprise", description = "This is a seek and destroy mission. You'll be driving a tank into the Carrion Fields to dismantle Scourge plague wagons. With the tank comes a crew of three 7th Legion soldiers. All must survive if this mission is to succeed!\n\nYou'll need to get in close to a plague wagon to unleash your engineer. Let them do their deed and move on to the next one. When the field is clear of plague wagons, head to the mausoleum in front of the ruined keep and drop off the rest of your crew. Meet with Ambo Cash inside.", objectives = "" }
WordHunterWoW_QuestEN[12327] = { title = "Out of Body Experience", description = "Ah, you seek a vision of the past.  You're a wise {race}.\n\nEvery time someone drops by for a reading, they seem to always ask about the future.  When you get to be my age, you learn that scrying the past, more often than not, is more useful.\n\nDrink this potion and peer into my crystal ball.  Let us see what knowledge we can obtain.", objectives = "" }
WordHunterWoW_QuestEN[12328] = { title = "Ruuna's Request", description = "I will not charge you gold for my services, for I can foresee that your actions are necessary and much hinges on what you learn today.\n\nI will, however, ask you to collect a reagent for me.  Obtain gossamer dust from the fern feeder moths northeast of here.  Do this and I will prepare a potion that will take you to the time and place where the events took place that you need to witness.", objectives = "" }
WordHunterWoW_QuestEN[12329] = { title = "Fate and Coincidence", description = "There are two types of people in this world, {name}.  Those who believe in coincidence and those who don't.\n\nOn the day I lost my eyesight I was given the gift of clairvoyance.  I suppose you can guess what sort of person I am.\n\nEarlier today, a young woman named Sasha was granted the same vision you were.  You will want to talk to her.\n\nYou'll find her directly east of here at the White Pine Trading Post, on the way to Solstice Village.", objectives = "" }
WordHunterWoW_QuestEN[12330] = { title = "Anatoly Will Talk", description = "My sister is here somewhere, and I can't seem to get this monster to talk.\n\nHe doesn't seem to care about his own well-being, but I've an idea.  I knew Anatoly's wife, Tatjana, from before the wolfcult arrived -- she was a horse-handler.\n\nTake this tranquillizer dart.  Bring her back alive, we're going to need her if we're to have any leverage with Anatoly.\n\nI will help you find the person behind all this once we save my sister.", objectives = "" }
