WordHunterWoW_QuestEN[12748] = { title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty orc in there that I think you'll take great pleasure in executing.", objectives = "" }
WordHunterWoW_QuestEN[12749] = { title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty troll in there that I think you'll take great pleasure in executing.", objectives = "" }
WordHunterWoW_QuestEN[12750] = { title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty Forsaken in there that I think you'll take great pleasure in executing.", objectives = "" }
WordHunterWoW_QuestEN[12751] = { title = "A Sort Of Homecoming", description = "Return to Thassarian at the Scarlet Tavern and let him know that Koltira's cry for vengeance has been answered. The Chapel of the Crimson Flame will be a pile of ashes in a matter of hours.\n\nYou're one cold-blooded monster, {name}. I salute you, brother.", objectives = "" }
WordHunterWoW_QuestEN[12752] = { title = "Desperate Research", description = "{name}, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.\n\nBe swift, {name}.  Each moment passed is another innocent life lost.", objectives = "" }
WordHunterWoW_QuestEN[12753] = { title = "A Desperate Alliance", description = "Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", objectives = "" }
WordHunterWoW_QuestEN[12754] = { title = "Ambush At The Overlook", description = "While you were out burning churches and murdering vermin, I've been busy formulating a plan.\n\nThe Scarlet courier is scheduled to pass by the Scarlet Overlook within the hour. The roads by the overlook are wide open and swarming with Crusaders. Use this makeshift cover to hide at the overlook and wait for the Scarlet Courier to pass. When he's close enough, strike with all your fury! Cut him down and take his belongings - including his clothes!\n\nThe overlook is 200 paces east of here.", objectives = "" }
WordHunterWoW_QuestEN[12755] = { title = "A Meeting With Fate", description = "This message must reach Abbendis. We do not want to draw their suspicion. They must continue under the assumption that everything is going as they planned.\n\nYou will don the Scarlet courier's clothes and with the help of some dark magic, take on the form of the courier.\n\nAbbendis is at King's Harbor, southeast of the Scarlet Overlook. Drop off the message and get as much information out of her as you can. She will tell us what we need to know about the \"Crimson Dawn.\"", objectives = "" }
WordHunterWoW_QuestEN[12756] = { title = "The Scarlet Onslaught Emerges", description = "Listen well, courier. The Scarlet lands are lost. New Avalon and Havenshire are overrun by Scourge. The specter of death looms overhead and threatens to overtake us at any moment.\n\nReturn to Galvar with this message:\n\n\"Turn your armies around and prepare your ships for travel to the frozen wastes. When next we meet it will be in Northrend.\"\n\nGive this to Galvar.\n\n<Abbendis hands you a journal.>\n\nIt will explain everything.\n\nThe Scarlet Crusade is no more. Long live the Scarlet Onslaught!", objectives = "" }
WordHunterWoW_QuestEN[12757] = { title = "Scarlet Armies Approach...", description = "We must prepare for the encroaching armies, {name}. You will take what you have discovered to Highlord Mograine at once! I will open a portal directly to Acherus. Step inside and it will transport you.\n\nGive Highlord Mograine Abbendis' journal as well. Perhaps he'll find it useful.\n", objectives = "" }
WordHunterWoW_QuestEN[12758] = { title = "A Hero's Headgear", description = "Rejek hears tales of giant metal men on faraway Stormwright's Shelf. Far to northwest, outside basin's lip, you will find it.\n\nImagine Rejek using heads of giant metal men as helmet. Make Rejek unstoppable! Make Rejek mighty!\n\nYou get for Rejek, but metal head might not come off metal body easy. Maybe steal bombs from little green men and their friends at Swindlegrin's Dig near Suntouched Pillar? Use bombs to get head off metal body, then bring to Rejek.", objectives = "" }
WordHunterWoW_QuestEN[12759] = { title = "Tools of War", description = "Zepik tell me that you maybe the best gorloc hunter he met... other than Zepik. Still big battle to southwest - you go help.\n\nZepik keeps some of biggest, baddest traps in his stash at Kartak's Hold... told Vekgar to use them for battle, so you use them too. Go pick out any traps you want and kill lots of big-tongues.\n\nLots and lots!", objectives = "" }
WordHunterWoW_QuestEN[12760] = { title = "Secret Strength of the Frenzyheart", description = "Battle still going at Kartak hold... I think it time for you to learn big secret of Frenzyheart.\n\nWe have berries we keep from other lands we came from... they not so special on their own, but mix them with drunk drinks and they make Frenzyheart super strong. You a Frenzyheart now... it time you get to be strong too.\n\nI give some drink, then you be super strong and you go smash all the spark big-tongues.", objectives = "" }
WordHunterWoW_QuestEN[12761] = { title = "Mastery of the Crystals", description = "Sparktouched are still being attacked by puppy-men... we think they maybe not stop if we not make them stop. We have secret weapon though... we sent it out to Soo-met so he can use to protect all Oracles.\n\nSecret weapon is from Great Ones themselves... extra shiny crystals found inside sacred Great One temples. Be very careful... no break them.\n\nCrystals are in chest near shrine at Sparktouched Haven, in far southwest. You go use crystals to help Soo-met beat the puppy-men.", objectives = "" }
WordHunterWoW_QuestEN[12762] = { title = "Power of the Great Ones", description = "We need to do something to stop puppy-men attacking Sparktouched Haven. Jaloot brought me very special crystal that he found in River's Heart... we seen only one like it before.\n\nThe crystal not have power now, but the opened up lifeblood pillar should have energy to recharge it if you just bring it close. Once the crystal is charged, go to Sparktouched Haven in far southwest and let the crystal's energy make you big and strong.\n\nThen it time to kick some puppy-men butt.", objectives = "" }
WordHunterWoW_QuestEN[12763] = { title = "Shifting Priorities", description = "As pressing as our needs are here, there's news from the lands to the north that cannot be ignored.\n\nI've just received a message from the Argent Crusade. It seems that scourge forces are gathering there and are threatening to overrun Zul'Drak.\n\nNeedless to say, {name}, if that were to happen our struggle here would be meaningless. You must go there and aid the Crusaders in beating back the Lich King's armies.\n\nSpeak to Makki when you are ready to travel.", objectives = "" }
WordHunterWoW_QuestEN[12766] = { title = "Speak with your Ambassador", description = "<The dragon in elf form takes your letter of introduction, perusing it for a moment and then stashing it away within his sleeve.>\n\nEverything seems to be in order. However, if you don't mind, I would ask that you speak with your ambassador here at the temple.\n\nShe has something of great import for you that needs taking care of before we send you up to the queen.\n\n<He pats at the letter under his sleeve.>\n\nI'll keep this safe for you until your return.", objectives = "" }
WordHunterWoW_QuestEN[12767] = { title = "Speak with your Ambassador", description = "<The dragon in elf form takes your letter of introduction, perusing it for a moment and then stashing it away within his sleeve.>\n\nEverything seems to be in order. However, if you don't mind, I would ask that you speak with your ambassador here at the temple.\n\nHe has something of great import for you that needs taking care of before we send you up to the queen.\n\n<He pats at the letter under his sleeve.>\n\nI'll keep this safe for you until your return.", objectives = "" }
WordHunterWoW_QuestEN[12768] = { title = "The Steward of Wyrmrest Temple", description = "You've proved that you're to be trusted and more.\n\nYou should return to Wyrmrest Temple and speak with the steward, Tariolstrasz, once more, {name}.", objectives = "" }
WordHunterWoW_QuestEN[12769] = { title = "The Steward of Wyrmrest Temple", description = "You've proved that you're to be trusted and more.\n\nYou should return to Wyrmrest Temple and speak with the steward, Tariolstrasz, once more, {name}.", objectives = "" }
WordHunterWoW_QuestEN[12770] = { title = "Reallocating Resources", description = "Listen up, {class}!\n\nYour days here are numbered. As much as we need capable {class}s in our ranks, there's trouble up north that makes our problems look like a mid-summer Stormwind parade.\n\nTurns out the Scourge are concentrating their efforts - making a big push to take over Zul'Drak. If that happens, we may as well pack it in.\n\nYou're free to finish any business here, but then it's off to Light's Breach with you. Speak to Samuel if you need transportation.\n\nDismissed.", objectives = "" }
WordHunterWoW_QuestEN[12771] = { title = "Ironforge", description = "Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.\n\nTake this, {name}.  Guard it close, and secure its passage to Ironforge.  Magni Bronzebeard is eager to take the fight to Northrend, and this will bring him closer to his goal.", objectives = "" }
WordHunterWoW_QuestEN[12772] = { title = "A Desperate Alliance", description = "Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", objectives = "" }
WordHunterWoW_QuestEN[12773] = { title = "Darnassus", description = "Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.\n\nTake this, {name}.  Guard it close, and secure its passage to Darnassus.  Deliver it to Tyrande Whisperwind -- her priests will find it a vital source of power in their fight against the unholy forces from the North.", objectives = "" }
WordHunterWoW_QuestEN[12774] = { title = "Stormwind", description = "Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.\n\nTake this, {name}.  Guard it close, and secure its passage to Stormwind.  The King of Stormwind has recently returned; I'm sure he will welcome this tool.", objectives = "" }
WordHunterWoW_QuestEN[12775] = { title = "A Desperate Alliance", description = "Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", objectives = "" }
WordHunterWoW_QuestEN[12776] = { title = "The Exodar", description = "Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.\n\nTake this, {name}.  Guard it close, and secure its passage to the Exodar.  Deliver it to Prophet Velen in the Vault of Lights so that he may use its powers against the unholy forces from the North.", objectives = "" }
WordHunterWoW_QuestEN[12777] = { title = "A Desperate Alliance", description = "Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", objectives = "" }
WordHunterWoW_QuestEN[12778] = { title = "The Scarlet Apocalypse", description = "The trap has been sprung, death knight. The armies of Hearthglen and Tirisfal have arrived, just in time to see their enclave in flames! If they turn back now, they fight us with their backs turned.\n\n<Mograine shakes his head.>\n\nNo, they have only one option, which has only one outcome: APOCALYPSE!\n\nAs we speak, they prepare to make one final stand.\n\nThe Lich King awaits your return, champion. He stands watch below us, at Death's Breach.", objectives = "" }
WordHunterWoW_QuestEN[12779] = { title = "An End To All Things...", description = "You have slaughtered legions beyond number and still your dark heart craves more. Your hunger knows no end, {name}.\n\n<The Lich King pauses.>\n\nThere must come an end to all things, death knight. The Scarlet armies make their final stand against us. For them, there is no escape... no choice. And for this reason they will fight with a ferocity that you have yet to witness.\n\nUse this horn to call forth one of my wyrms. Climb upon its back and command it into battle. With it you will end the Scarlet Crusade.", objectives = "" }
WordHunterWoW_QuestEN[12781] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Siouxsie the Banshee in Ebon Hold.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!\n", objectives = "" }
WordHunterWoW_QuestEN[12782] = { title = "Desperate Research", description = "{name}, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.\n\nBe swift, {name}.  Each moment passed is another innocent life lost.", objectives = "" }
WordHunterWoW_QuestEN[12783] = { title = "Desperate Research", description = "{name}, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.\n\nBe swift, {name}.  Each moment passed is another innocent life lost.", objectives = "" }
WordHunterWoW_QuestEN[12784] = { title = "Desperate Research", description = "{name}, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.\n\nBe swift, {name}.  Each moment passed is another innocent life lost.", objectives = "" }
WordHunterWoW_QuestEN[12785] = { title = "Orgrimmar", description = "We have a breakthrough!  Our zombie specimens have given us new insight into the nature of the Scourge's plague.  They have born rotten, delicious fruit...\n\nTake this box to Orgrimmar.  Inside is a head that is infected with the zombie plague, and something else we have devised -- an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.\n\nBring the box to my assistant, Apothecary Karlov.  He attends Warchief Thrall in Orgrimmar.", objectives = "" }
WordHunterWoW_QuestEN[12786] = { title = "Thunder Bluff", description = "We have a breakthrough!  Our zombie specimens have given new insight into the nature of the Scourge's plague.  They have born rotten, delicious fruit...\n\nTake this box to Thunder Bluff.  Inside is a head that is infected with the zombie plague, and something else we have devised -- an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.\n\nBring the box to my assistant, Apothecary Chaney.  He attends Magatha Grimtotem in Thunder Bluff.", objectives = "" }
WordHunterWoW_QuestEN[12787] = { title = "The Undercity", description = "The zombie plague was a blessing in disguise.  In our search for a cure, we have learned so much of the Scourge and their contagion.  Our research has given us weapons against them.  Weapons, and tools...\n\nTake this -- it is a zombie's head and has been partially cured of its plague by injecting it with a compound derived from our recent discoveries.  Deliver the head to Master Apothecary Faranell; I have a list of experiments I would like him to perform on it.", objectives = "" }
WordHunterWoW_QuestEN[12788] = { title = "Silvermoon", description = "We have a breakthrough!  Our zombie specimens have given new insight into the nature of the Scourge's plague.  They have born rotten, delicious fruit...\n\nTake this box to Silvermoon City.  Inside is a head that is infected with the zombie plague, and something else... an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.\n\nBring the box to my assistant, Apothecary Tepesh.  She attends Lor'themar Theron in Silvermoon City.", objectives = "" }
WordHunterWoW_QuestEN[12789] = { title = "Into the Breach!", description = "Ready yourself, {class}. I'm dispatching you to Light's Breach, northeast of here.\n\nI've received word that the Scourge are making a push to take over Zul'Drak.\n\n<Valus stares you dead in the eyes.>\n\nThis will not come to pass.\n\nSee to it that you assist in the destruction of the Scourge there. The light demands it.\n\nDismissed.", objectives = "" }
WordHunterWoW_QuestEN[12790] = { title = "Learning to Leave and Return: the Magical Way", description = "Just in case you don't already know, you can use the crystal on the platform behind me to teleport to the Violet Stand in Crystalsong Forest beneath Dalaran.\n\nCorrespondingly, you can use the crystal at the stand below to return to the chamber above me.\n\nI would like for you to do this now.", objectives = "" }
WordHunterWoW_QuestEN[12791] = { title = "The Magical Kingdom of Dalaran", description = "Hello, {name}. You may or may not be aware that we Kirin Tor moved our city here to Northrend.\n\nNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.\n\nWe believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there.\n\nWhen you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.", objectives = "" }
WordHunterWoW_QuestEN[12792] = { title = "First Things First", description = "Listen up, {race}!\n\nThis entire region is full of crises. Everywhere you look you'll find those who could use your assistance.\n\n<Kunz looks you squarely in the eye.>\n\nNo one needs your help right now more than Riannah. The scourge have forced their way between us, leaving her and those she commands isolated.\n\nLight's Breach, where her forces are holding out, lies just southwest of here.", objectives = "" }
WordHunterWoW_QuestEN[12793] = { title = "Smoke on the Horizon", description = "You hear that, {race}?\n\nThe clamor of battle far to the west reaches us here, even over the din of our own struggle.\n\nThe Scourge are threatening to break through the lines of those calling themselves the Argent Crusade. Preventing this is as urgent as anything in the region.\n\nTravel to Light's Breach and join in their struggle. Speak to Maaka and he will provide you safe passage.", objectives = "" }
WordHunterWoW_QuestEN[12794] = { title = "The Magical Kingdom of Dalaran", description = "Hello, {name}. You may or may not be aware that we Kirin Tor moved our city here to Northrend.\n\nNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.\n\nWe believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there.\n\nWhen you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.", objectives = "" }
WordHunterWoW_QuestEN[12795] = { title = "Taking a Stand", description = "A few moments ago I spotted a signal flare over the treeline to the east.\n\nThat can only mean that things are not going smoothly for the Crusaders at Argent Stand.\n\nI cannot leave our post here, {race}, but you can. When time permits, make your way up to Commander Falstaav and see if there's anything you can do to lighten their burden.", objectives = "" }
WordHunterWoW_QuestEN[12796] = { title = "The Magical Kingdom of Dalaran", description = "Hello, {name}. You may or may not be aware that we Kirin Tor moved our city here to Northrend.\n\nNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.\n\nWe believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there.\n\nWhen you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.", objectives = "" }
WordHunterWoW_QuestEN[12797] = { title = "Back Through the Waygate", description = "You speak the truth, {race}.  I can sense the very essence of Sholazar Basin begin to fray by the blight of undeath even as we speak.\n\nI've bound my being into the rune, {race}.  Deliver it to she who sent you here -- for only her power can grant me passage to her lands.", objectives = "" }
WordHunterWoW_QuestEN[12799] = { title = "Siphoning the Spirits", description = "You should be happy he's coming, they said. You'll enjoy his company, they said....\n\nWell it's not as if I had a choice in the matter. Finklestein is the Crusade's best alchemist. I suppose I should be honored that he's chosen my post to set up shop. But ever since he's arrived, I've been relegated to collecting various alchemical ingredients.\n\nSay, {race}, how about you give me a hand? Just south of here are some pools that are haunted by spirits of ancient trolls. Collect their ectoplasm for me.", objectives = "" }
WordHunterWoW_QuestEN[12800] = { title = "The Lich King's Command", description = "The Scarlet Enclave is no more. What remains of the Crusade will be dealt with in Northrend.\n\nWe now turn all of our efforts to Light's Hope Chapel. No longer will this affront to your master be allowed to exist!\n\nI have issued my final command. Scourge Commander Thalanor awaits your arrival at the edge of Browman Mill. Go northwest, through the cave, into the Noxious Glade and take the path leading out of the glade to the mill.\n\nDo not fail me, {name}.", objectives = "" }
WordHunterWoW_QuestEN[12801] = { title = "The Light of Dawn", description = "The Argent Dawn stands defiantly against us at Light's Hope Chapel. They dare oppose the Scourge and for that reason alone they must be destroyed!\n\nThe mighty armies of the Lich King stand at the ready as the final battle for the Plaguelands approaches. Today we ascend into the immortal realm of Scourge heroes!\n\nWhen you are ready for battle, report to Highlord Darion Mograine. It is the highlord who will issue the final march orders and command our armies at Light's Hope Chapel.", objectives = "" }
WordHunterWoW_QuestEN[12802] = { title = "My Heart is in Your Hands", description = "<Drakuru's voice fills your mind.>\n\nHey, mon! Dis eye of da prophets be great! I been usin' it to watch ya and I see ya got da heart now! Not bad....\n\nNow ya just gotta bring it to my brazier at Drak'atal Passage, a short walk east of ya.\n\nYa must drink my elixir at da pedestal to summon me there. This time, ya need ta mix in some desperate mojo from the defenders there for it ta be workin'.", objectives = "" }
WordHunterWoW_QuestEN[12803] = { title = "Force of Nature", description = "I'm not sure about what I saw while flying to the northeast, but to me it looked like a gigantic woman kicking some Scourge butt.\n\nI'd heard the professor talk about a certain \"lifewarden\"  appointed by the titans to look over Sholazar.  I might not be a titan historian, but it sounds like she fits the bill.\n\nI also know that if the Scourge cross the border between the Lost Lands and the rest of Sholazar, our expedition's as good as dead.  What do you say you go look for her and lend a hand?", objectives = "" }
WordHunterWoW_QuestEN[12804] = { title = "A Steak Fit for a Hunter", description = "Sometimes, there's nothing worse than a camp full of hunters. They're all so busy taking down prey animals that the only meat I get is tough and stringy. That's hardly the kind of thing you want to come home to after a long day on the hunt.\n\nLucky for us, though, there is a source of tender, succulent meat nearby. To the south of the river and the camp live longneck grazers. They're a perfect source of meat for our hungry hunters. Bring me back the best cuts of meat and we'll properly toast our comrades.", objectives = "" }
WordHunterWoW_QuestEN[12805] = { title = "Salvaging Life's Strength", description = "The Lifeblood Pillar was toppled over with great force, sending the very earth into an upheaval.\n\nThe elementals that wander the sundered shard carry with them the very life essence that gave the pillar its strength.  I cannot allow this energy to be wasted, for only four pillars remain.\n\nHead to the sundered shard, to the southeast, and seek the lifeblood elementals.\n\nUse this gem on their remains to recover their rampant energy.  We'll need the energy to heal the land when all this is over.", objectives = "" }
WordHunterWoW_QuestEN[12806] = { title = "To the Rise with all Due Haste!", description = "Some would say that our most critical mission lies not with the Lich King, but with the utter destruction of the Scarlet Onslaught. I would say that is foolish, but who am I to judge?\n\nDeath's Rise is far to the southwest, overlooking the sea along the cliff wall. There you will find Lord-Commander Arete personally overseeing the Onslaught's destruction himself.\n\n<The baron clears his throat.>\n\nDo see to it that you report to him with all due haste. He asked for you personally.", objectives = "" }
WordHunterWoW_QuestEN[12807] = { title = "The Story Thus Far...", description = "We have much to do, but first I believe a short refresher is in order.\n\nWe death knights have a colorful past with our Scarlet friends who idiotically rest comfortably in the harbor below us to the northwest.\n\nWhen you are ready for an earful, speak with me again and I shall provide enlightenment.", objectives = "" }
WordHunterWoW_QuestEN[12808] = { title = "A Desperate Alliance", description = "Good {name}, the Lich King plagues us --  both Horde and Alliance -- with disease and invasion.  Only by joining our strengths can the two great cultures of Azeroth survive against his assault.\n\nIn Shattrath, in the Terrace of Light, that alliance has been struck.  To aid our struggle against the Lich King, go to the new Alliance camp in the Terrace of Light and speak with Bishop Lazaril.\n\nLight speed, {name}.", objectives = "" }
WordHunterWoW_QuestEN[12809] = { title = "Ironforge", description = "Our prayers have been answered!  Using the concentration of Light from the Naaru of Shattrath, and the shared benedictions from the faithful, we have created holy artifacts of profound power.  These artifacts will be our weapon against the Lich King's machinations.\n\nTake this, {name}.  Guard it close, and secure its passage to Ironforge.  High Tinker Mekkatorque in Tinkertown will be eager to make use of the artifact's power.", objectives = "" }
WordHunterWoW_QuestEN[12810] = { title = "Blood in the Water", description = "The forces at Onslaught Harbor are heavily reinforced by gryphon riders. You need a mount that will enable you to put them down. But first, we need the components for the ritual that is going to make it all happen.\n\nA great deal of blood is necessary for the ritual to be undertaken.\n\n<The lord-commander points down and to the northwest.>\n\nThere is a readily available supply down there in the harbor... sharks. Do not return to me until you've filled this bladder with their blood.", objectives = "" }
WordHunterWoW_QuestEN[12811] = { title = "Desperate Research", description = "{name}, the Lich King plagues us with invasion.  To beat him back to his frozen throne, the Horde and Alliance must stand resolute together.  In Shattrath, in the Terrace of Light, that alliance has been struck.\n\nTo aid our struggle against the Lich King, go to the new apothecary camp in the Terrace of Light and speak with Grand Apothecary Putress.  He leads desperate research to end the zombie plague.  His cure is our salvation.\n\nBe swift, {name}.  Each moment passed is another innocent life lost.", objectives = "" }
WordHunterWoW_QuestEN[12812] = { title = "Orgrimmar", description = "We have a breakthrough!  Our zombie specimens have given new insight into the nature of the Scourge's plague.  They have born rotten, delicious fruit...\n\nTake this box to Orgrimmar.  Inside is a head that is infected with the zombie plague, and something else we have devised -- an anti-plague.  The two plagues battle within the zombie brain, and that brain is the key to a cure, I am certain of it.\n\nBring the box to my assistant, Apothecary Karlov.  He attends Thrall in Orgrimmar.", objectives = "" }
WordHunterWoW_QuestEN[12813] = { title = "From Their Corpses, Rise!", description = "How kind... how generous our lord-commander is. Where he is flowers and sunshine, I am filled only with hatred.\n\nIt is not enough to end their miserable lives... I want them humiliated... debased!\n\nWhat could be more unspeakable than to be turned into that which you hate? To dedicate your existence to eradicating a thing, and then in the end to become it?\n\nHow sad.\n\nTake this tincture northwest to Onslaught Harbor. Apply it to their still corpses and watch what happens, but avoid the cathedral.", objectives = "" }
WordHunterWoW_QuestEN[12814] = { title = "You'll Need a Gryphon", description = "What could be more fitting than to take one of their own gryphons to use against them? Go to Onslaught Harbor and take the reins to one of their gryphons from the dead clutches of its rider.\n\nReturn with the gryphon, delivering it to Uzo Deathcaller. He will see to its proper transformation and provide you with further instructions.", objectives = "" }
WordHunterWoW_QuestEN[12815] = { title = "No Fly Zone", description = "Now that you got your bone gryphon, I wantcha to take it back down there everyday and make a no fly zone over Onslaught Harbor.\n\nI gotta admit, mon, I don't really care if you use the bone gryphon to kill them gryphon riders or not. But I'm guessin' that if you do, you'll find it much easier to get to 'em.\n\nBesides, it's got lots of neat tricks you can use.", objectives = "" }
WordHunterWoW_QuestEN[12816] = { title = "Investigate the Scourge of Silvermoon", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Silvermoon from these accursed invaders? \n \nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "" }
WordHunterWoW_QuestEN[12817] = { title = "Investigate the Scourge of Exodar", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend the Exodar from these accursed invaders? \n \nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "" }
WordHunterWoW_QuestEN[12818] = { title = "Clean Up", description = "To the point... Ricket's asked me to put together some stronger land mines, but I'm running low on parts.\n\nJust west of town, you'll find the remains of our last rocket sled... Ricket got a little excited when she was fueling it, but I probably should have thought to not put the nozzle right over the exhaust. Live and learn, eh?\n\nThere should be a good stock of spare parts scattered around the destroyed sled... why don't you go ahead and chase off those scavengers and nab me some of that wreckage?", objectives = "" }
WordHunterWoW_QuestEN[12819] = { title = "Just Around the Corner", description = "Blast it! Where are my tools? I had them here just a moment ago.\n\nOh! I probably forgot them when I was setting up that minefield in the west. That's mildly inconvenient. I'd be quite appreciative if you could go get them for me. You'll need to watch your step though... you should be able to use the same path that I did to get out.\n\nOh, and don't try to fly in... I had the presence of mind to set up turrets to shoot down anything that might fly, and they aren't very discerning in who they target.", objectives = "" }
WordHunterWoW_QuestEN[12820] = { title = "A Delicate Touch", description = "I've been waiting an eternity for these mines! Well, a few days at least. What took him so long?\n\nHere's the low down, compadre... there's this nasty bunch of magnataur--you know, big, hairy, and extremely ugly--and they seem pretty keen on taking K3 for themselves.\n\nNot going to happen.\n\nWe've got some defenses set up in their path, northeast of here. Sadly, our laser turrets have pretty limited power supplies... that's where these mines come in! Get over there and blow them up good!", objectives = "" }
WordHunterWoW_QuestEN[12821] = { title = "Cell Block Tango", description = "The sapper squad is ready. That means it's time for fun!\n\nThere's only one thing holding us up from our full-scale assault on Garm! I sent a runner to set a teleporter up behind him--successfully I might add--and he returned to get the power cell it needs to function. It isn't working yet... which means the power cell didn't get there.\n\nI need you to look just on the other side of Garm's Bane for the power cell. When you find it, bring it farther east to Garm's Rise and activate the teleporter.", objectives = "" }
WordHunterWoW_QuestEN[12822] = { title = "Know No Fear", description = "Now that we have the teleporter open, my plan is quite complex... it has several facets and will take impeccable coordination. And there are supplies to be gathered! And troops to recruit! Likely, weeks of hard labor as well!\n\nHahah, I had you going there for a moment, didn't I? You've got this, kid. Hop through the teleporter and take the fight to them! Our sappers will back you up... they won't have anywhere to run.", objectives = "" }
WordHunterWoW_QuestEN[12823] = { title = "A Flawless Plan", description = "Hey there! Joining us for the assault I assume?\n\nI've got a special task for you... we're going to bring the whole cave down on their heads! Towards the back of their cave, you should find Frostgut's Altar.  Sneak up and plant this hardpacked explosive bundle somewhere close to it.\n\nOnce the charge is placed, stick around just long enough to make sure Frostgut bites it, then get out quickly! There's no knowing how long the cave will last once that thing goes off!", objectives = "" }
WordHunterWoW_QuestEN[12824] = { title = "Demolitionist Extraordinaire", description = "You've got some swift feet on you sonny! Thanks for lending a hand with those explosives... I've been waiting to give that invention a good test run for a while!\n\nGo ahead and tell Ricket we should be covered on the magnataur front now... my sappers will clean up any of the remaining baddies.\n\nThanks again!", objectives = "" }
WordHunterWoW_QuestEN[12826] = { title = "Slightly Unstable", description = "Looking good!\n\nNo, not you - my new mines. You're just a little full of yourself, aren't you? I, on the other hand, am absolutely brilliant! My intellect cannot be matched.\n\nWhat were we talking about? Oh yes, my new mines! New and improved... ready for whatever devious use Ricket has concocted.\n\nBe a good lad and go hand them off to Ricket, will you? She's right over there... it should be quite the epic journey, I'm sure. Be careful though, she's a little loopy.", objectives = "" }
WordHunterWoW_QuestEN[12827] = { title = "Reclaimed Rations", description = "Hey hey! You're a new face! Care to lend Ricket a hand?\n\nWe have a somewhat unexpected problem - food shortage. I know, I know... we should have seen that coming, but you don't get it. We tend to have somewhat of a quick turn-around here with our sapper squad and all, so usually we don't have to worry about long term eats. Good old K3's gotten popular though.\n\nConvenient solution? There are gnoll camps to the west and some gnolls scattered, scavenging as gnolls do. Care to go nab some of their rations?", objectives = "" }
WordHunterWoW_QuestEN[12828] = { title = "Ample Inspiration", description = "Wow! That stuff is nasty. Not to account for gnoll taste or anything, but I figured whatever they had would at least be... edible?\n\nLet's get more creative.\n\nTore's got an explosive dispenser north of town... not far from the big cavern entrance, can't miss it. I'm sure she intends them for mining purposes of some sort, but I've got a better idea.\n\nGrab one of those things and rush it to one of the nearby mammoths... most of them are to the west. Collect the meat, bring it back.", objectives = "" }
WordHunterWoW_QuestEN[12829] = { title = "Moving In", description = "Hiya! The name's Tore. I  head up the mining operation here at K3... or I will shortly anyway!\n\nThis here cave is full of creepy-crawlies. I think we could do with a few less spiders before we move in - what'd you think?", objectives = "" }
WordHunterWoW_QuestEN[12830] = { title = "Ore Repossession", description = "We're moving in!\n\nThere were some snobolds here when we arrived... their mining operation seems to have met some unfortunate happenings though. Doesn't much matter - we were taking over soon anyway.\n\nI sent some of our miners in there to get me some ore samples that I can use to calibrate our machines for processing, but they haven't come back.\n\nMind going in there and nabbing some samples for me in their stead? The snobolds probably have some on them, though I'd expect most of them are dead by now.", objectives = "" }
WordHunterWoW_QuestEN[12831] = { title = "Only Partly Forgotten", description = "Oi... it's like there's a propeller in my stomach.\n\nI think I can walk, but I got something nasty in my system when I got bit by something in the back of the cave. It was bigger than the other spiders... and brightly colored.\n\nRicket can probably make me an antidote, but she'd need the venom sac from whatever bit me. Would you mind finding it for me? I don't think Tore's coming.\n\nI'll just pretend I'm dead here and hopefully they'll leave me alone.", objectives = "" }
WordHunterWoW_QuestEN[12832] = { title = "Bitter Departure", description = "Oi - thank you! I thought for sure I'd just be a spider snack. Perhaps I'm speaking a bit soon though - let's get the heck out of here!\n\nLet me know as soon as you're ready to go... make it quick.", objectives = "" }
WordHunterWoW_QuestEN[12833] = { title = "Overstock", description = "Hey there again! You didn't run off like all the other adventurers did? Well, you're just a peach, aren't ya? I was beginning to think I smelled funny or something!\n\nWe could still use a bit of a hand around here, and you have just the right experience.  Remember those magnataur? Well apparently the cave didn't completely collapse... there are still quite a few left. So much for Gino taking care of them, eh?\n\nFortunately, Jeer made way more than enough mines. You've got this!", objectives = "" }
WordHunterWoW_QuestEN[12836] = { title = "Expression of Gratitude", description = "I know just the job for an eager newcomer! We've got a gnoll problem. You might even call it a gnoll infestation! Pesky things. They keep creeping up more and more, and now they're on our doorstep, stealing our parts! Inconceivable.\n\nIt all begins and ends with their uppity leader, Gnarlhide. I want you to see to that \"ends\" part. Go pay him a visit at his camp all the way to the west, in Snowblind Hills.\n\nAnd when I say \"pay him a visit,\" that's a euphemism for \"kill him painfully.\" Kay? Kay!", objectives = "" }
WordHunterWoW_QuestEN[12838] = { title = "Intelligence Gathering", description = "I need to know what the Scarlet Onslaught is planning today. You will be my instrument in this task.\n\nFly to Onslaught Harbor and rifle through their baggage trunks for documents. The trunks will be locked, so you'll have to take the keys from the Scarlet Onslaught members by whatever means.", objectives = "" }
WordHunterWoW_QuestEN[12839] = { title = "The Grand (Admiral's) Plan", description = "At first this note looks like any of the other intel that you've been looking for. However, a quick perusal of its contents disabuses you of this notion.\n\nThe letter conveys that Grand Admiral Westwind is present somewhere on the island, but that he is keeping himself secluded for now. He speaks of a glorious day that is coming soon in which the Scarlet Onslaught will wash over first the Lich King and then the rest of world to finally bring order to Azeroth.\n\nThe lord-commander will want to see this!", objectives = "" }
WordHunterWoW_QuestEN[12840] = { title = "In Strict Confidence", description = "If anyone knows where the admiral is, then surely it must be his captains on the ships in Onslaught Harbor.\n\n<The lord-commander rubs his hands together.>\n\nWelsington and Hartford are their names if memory serves. Go beat the information out of them and then end their miserable lives.\n\nI want to know where the grand admiral is hidden!", objectives = "" }
WordHunterWoW_QuestEN[12841] = { title = "The Crone's Bargain", description = "Yes, it must be the little green prisoner you're after...  We might be able to help each other.\n\nYou're not going to get the goblin out of here by force. Not alive, anyway.\n\nAmong my people I am known as a Yrkvinn, a practitioner of illusions. As you can see, the Hyldnir have made me their prisoner.\n\nIf I had my runes, I could make you go unnoticed among them. Further inside, patrolling the mines, you'll find an overseer named Syra. She has my runes. Retrieve them and we'll talk some more.", objectives = "" }
WordHunterWoW_QuestEN[12842] = { title = "Runeforging: Preparation For Battle", description = "The mark of war is etched indelibly upon your soul, death knight. You have learned the dark art of runeforging and with it you will engrave runes of power upon your weaponry.\n\nPreparations for battle must be made. Return to one of the runeforges, here in the Heart of Acherus, and use the power of runeforging to emblazon your weapon with a rune of power!\n\nReturn to me when your blade glows with dark energy!", objectives = "" }
WordHunterWoW_QuestEN[12843] = { title = "They Took Our Men!", description = "You have to help us!  We were in the middle of an expedition into the mountains to set up a transmission tower when we were attacked.\n\nThey looked like vrykul, except their skin was blue and layered with frost... and they were all female!  They took all the men in the expedition and let us women go.  Please, {name}!  We think they're being held in Sifreldar, the village overlooking K3.", objectives = "" }
WordHunterWoW_QuestEN[12844] = { title = "Equipment Recovery", description = "Please, {name}.  When the Hyldnir took our men, they also took all our equipment.  Of course, it's more important that we get our boys back, but if you run into any of our equipment, I'd really appreciate it if you brought it back to us.\n\nYou'll find their village just above us, to the north.", objectives = "" }
WordHunterWoW_QuestEN[12846] = { title = "Leave No Goblin Behind", description = "All of our boys are back... thanks to you, {name}!  Well... all but one.\n\nMy brother Zeev is still up there according to the others.  Apparently they have some sort of mine where they make their prisoners work.  Go in there and see if you can find out anything.", objectives = "" }
WordHunterWoW_QuestEN[12847] = { title = "Second Chances", description = "I'd heard they have an archbishop in their cathedral, but I had no idea that they'd resurrected and promoted Landgren! The Crimson Cathedral is heavily guarded with only one entrance, so you'll need help.\n\nWe still need to know where the grand admiral is, but this time we're not taking any chances!\n\nTake this device. It can be used to summon a gate for me to step through once you've killed the archbishop.\n\nI'll have my answers directly from his compelled soul! We will find Grand Admiral Westwind!", objectives = "" }
WordHunterWoW_QuestEN[12848] = { title = "The Endless Hunger", description = "The endless hunger will soon take hold of you, {class}. When it does, you will feel pain immeasurable. There is only one remedy for the suffering: the hunger must be sated.\n\nI give you the key to your salvation.\n\nChained to the Heart of Acherus are those deemed unworthy of the dark brotherhood. Use the key to free an unworthy initiate. Allow them to equip their gear and battle you for their freedom. Kill and the pain will cease. Fail and suffer for eternity.\n\nLive or die - the choice is yours to make.", objectives = "" }
WordHunterWoW_QuestEN[12849] = { title = "The Power Of Blood, Frost And Unholy", description = "", objectives = "" }
WordHunterWoW_QuestEN[12850] = { title = "Report To Scourge Commander Thalanor", description = "Scourge Commander Thalanor awaits your arrival at the overhang located directly southeast of our current position. Report to Thalanor and requisition a Scourge gryphon to deliver you to Death's Breach.\n\nPrince Valanar will be waiting for you down below.\n\nSuffer well, brother! ", objectives = "" }
WordHunterWoW_QuestEN[12851] = { title = "Bearly Hanging On", description = "The test awaits, woman!\n\nDo you have the heart of a warrior queen? Or that of a sniveling seamstress?\n\nOne taste of war and you'll know the answer.\n\nYou might lie to your mother, your sisters, and even yourself, but the battlefield always exposes one's true nature.\n\nWhen you've made your preparations, mount Icefang and ride into battle. From her back, you must rain down a shower of death upon our enemy.", objectives = "" }
WordHunterWoW_QuestEN[12852] = { title = "The Admiral Revealed", description = "When High General Abbendis was confronted at New Hearthglen, the grand admiral protected himself within an impenetrable sphere of magic before making his escape.\n\nI am particularly adept at nullifying magic.\n\nTake this to use against him inside The Hidden Hollow when he puts the sphere up. I wish that I could be there to see the look on his face when you do it.\n\nDeal with him.", objectives = "" }
WordHunterWoW_QuestEN[12853] = { title = "Luxurious Getaway!", description = "Hey there, pal!\n\nDo you like excitement and explosions?! Who doesn't? I know just the place for you. Down at luxurious K3, they're always making innovative inventions and finding all-new ways to make things blow up! Sounds thrilling, doesn't it? If you want to be part of the fun, head on down today and speak to Jeer Sparksocket!\n\nMandatory disclaimer: manual labor may be required to partake in previously indicated \"excitement.\"", objectives = "" }
WordHunterWoW_QuestEN[12854] = { title = "On Brann's Trail", description = "After the discovery of Brann's journal in Grizzly Hills, we've only had one other communication from Brann. A mysterious note found its way to Explorers' League headquarters in Ironforge, with no indication of where it came from. All it said was that we're to meet Brann at his camp and help him with his search.\n\nFrom what I can tell, the camp should be located northeast of here, across the Bor's Breath River and at the foot of some ruins from the Path of the Titans.", objectives = "" }
WordHunterWoW_QuestEN[12855] = { title = "Sniffing Out the Perpetrator", description = "The tone of Brann's note suggests he meant to bury something with the note, maybe a pack of some kind. You're sure this was all you found?\n\nOkay, I'm going to have you take one of these frosthounds with you. The frostborn use them for tracking. Bring it to the destroyed camp and let it get Brann's scent.\n\nIt should at least lead you to the location of those missing possessions, and if we're lucky, Brann himself. ", objectives = "" }
WordHunterWoW_QuestEN[12856] = { title = "Cold Hearted", description = "To be slain honorably on the field of battle brings us all glory. To be frozen in a block of ice and endlessly taunted does not....\n\nYou are to fly to the frost giant city of Dun Niffelem, just east of the Valley of Ancient Winters, and liberate our captive proto-drakes. With them, you will be able to free our sisters from their frozen bonds and carry them safely home.\n\nBeware the giants' clubs, sister, lest you find yourself numbered among the captives.", objectives = "" }
WordHunterWoW_QuestEN[12857] = { title = "WANTED: Ragemane's Flipper", description = "Posted by Chief Rageclaw:\n\nChief Rageclaw trusty lion seal, Ragemane, bite hand that feed him. Rageclaw say Ragemane no more good because of bad Drakuru trolls. Chief Rageclaw very sad to ask that Ragemane be killeded and Ragemane flipper be returned to chief as proof.\n\nYou find Ragemane to southeast, at Rageclaw Lake.\n\nChief Rageclaw sorry for bad writing. First time use one of these things; plus, Chief Rageclaw is wolvar, not person.\n", objectives = "" }
WordHunterWoW_QuestEN[12858] = { title = "Pieces to the Puzzle", description = "Thank the Light that someone got my message. Now that I'm safe from the iron dwarves, I need to ask your help with something. I've got a lead on Norgannon's keystone, which guards access to Ulduar's archives, but the Titans divided it into two pieces and secreted them away.\n\nOne of the pieces, the keystone's shell, is held within the Inventor's Library on the northern coast, south of Ulduar itself. The first thing you'll need to do is retrieve the fragments of an access disk from the library's guardians.", objectives = "" }
WordHunterWoW_QuestEN[12859] = { title = "This Just In: Fire Still Hot!", description = "Trolls attack Rageclaw Den and kick Rageclaw out! It get worse. Trolls now burning village! This very bad. Chief make top Rageclaw shaman, Moky, do study on fire. Results very surprising! Fire still hot and can burn things.\n\nWill you help Rageclaw and put fire out? Moky has special Rageclaw fire extinguisher for you. Use special fire extinguisher to put out fire at Rageclaw Den to southeast. Sometimes take many sprays to douse fire, but extinguisher always have water! Rageclaw magic strong!", objectives = "" }
WordHunterWoW_QuestEN[12860] = { title = "Data Mining", description = "That disk you assembled... it's blank! That crafty Mimir must've hidden the information somewhere else. Look around the Inventor's Library; do you see any databanks there?\n\nThat might be what you need to do with the disk. Try using it near some of those databanks. Perhaps it's set to retrieve and store information from them. After you've tried your hand at that, contact me again and let me know what you've found. Meanwhile, I'll be trying to track down the other half of the archive key.", objectives = "" }
WordHunterWoW_QuestEN[12861] = { title = "Trolls Is Gone Crazy!", description = "Drakuru... You know who this troll is? I think bad troll are controlled by the Drakuru troll. They call themself Drakuru trolls - that how I know. Now you see why I am chief of Rageclaw. Smartest of all wolvar!\n\nBut that not why I talk to you now. Bad troll come and kick Rageclaw out of den. Rageclaw that no run away held as prisoner in village. You go to Rageclaw Den, southeast, and free captured Rageclaw. Kill troll for lock opener. You maybe kill many troll for many lock opener.", objectives = "" }
WordHunterWoW_QuestEN[12862] = { title = "When All Else Fails", description = "So...  so I don't think we're going to be getting a good foothold in those mountains.\n\nTrust me, I'm not one to give up easily... but between freezing engines, nasty vrykul women, territorial dragon want-to-bes and the half a dozen other nasties settled in the area, this just ain't happening.\n\nDon't let that dissuade you though! Just because we can't get a foothold doesn't mean we won't get you there... one-way trips are pretty simple when you get down to it.\n\n<Ricket nods at some nearby rockets.>", objectives = "" }
WordHunterWoW_QuestEN[12863] = { title = "Offering Thanks", description = "Ah! Thanks for coming up here, lad.\n\nJudging by your wide eyes and shivering hands, I'd venture a guess that you're somewhat new. Sounds like it would be good for you to meet our gracious hosts then!\n\nWe've got some extra medical supplies... to be honest, we weren't expecting to have such a comfortable setup. Go ahead and give this crate to Glorthal over there, and lend them a hand if you would too. We don't want them to think we're ungrateful for how welcoming they've been.", objectives = "" }
WordHunterWoW_QuestEN[12864] = { title = "Missing Scouts", description = "There is something that I could use a hand with now that I have you.\n\nWe have a few scouts that are extremely late in returning. The peaks are harsh... but these boys know what they're doing.\n\nHead to the east... along the Bor's Breath valley and near Bor's Fall... they should be out that direction. If you find any sign of one of them, bring me back news immediately. We have a few enemies in the area - if any of them are getting a bit uppity, the more warning the better.", objectives = "" }
WordHunterWoW_QuestEN[12865] = { title = "Loyal Companions", description = "Fresh blood! Good to meet ya! I've got some work if you've got some time.\n\nOff to the east are the Foot Steppes... pretty hard land, but there's quite a group of rhino that graze there. Our birds have a taste for that rhino meat, but it's always a bit dangerous for them to go hunting with all of the proto-drakes that nest around there.\n\nIf you're keen, head over that way and get some rhino meat, bring it back to the peaks above here, and then use it to feed some of the eagles that nest there.", objectives = "" }
WordHunterWoW_QuestEN[12866] = { title = "Stemming the Aggressors", description = "Damn harpies. We've beat that bunch into submission more times than I can remember... and they stay quiet for a time after each bout. This time, I'd thought that maybe it sunk in.\n\nApparently not.\n\nTheir memory may be a bit short, but if their numbers are thinned enough, they'll keep to themselves. Head into the valleys in the north and east and clear out a fair chunk of them for me, will ya?", objectives = "" }
WordHunterWoW_QuestEN[12867] = { title = "Baby Stealers", description = "A few weeks ago, if you looked up, you'd see dozens of those beautiful eagles soaring the skies. Now, only a few if any. They've taken to staying with their nests nearly all the time now because the harpies have been stealing their eggs.\n\nThe harpies have grown a taste for eagle flesh, it seems... the sick wretches are caring for the eggs long enough to feast on the hatchlings. Go into the valleys to the north or the east and find the eggs... bring them back here, and I'll take them back to the nests.", objectives = "" }
WordHunterWoW_QuestEN[12868] = { title = "Sirana Iceshriek", description = "This Sirana Iceshriek sounds like the one that's spurring the harpies to be more aggressive. If we kill her, I suspect their attacks won't last long afterwards.\n\nOne of our stormriders claims to have spotted her circling the peak directly northwest of here.  Go find the wench and put her down. Let's see this done.", objectives = "" }
WordHunterWoW_QuestEN[12869] = { title = "Pushed Too Far", description = "You were there with Loken, weren't you? The iron dwarves captured Veranus, the brood mother of the proto-drakes. The drakes don't seem even a little bit happy about the situation... they've gotten very aggressive.\n\nThey've pushed into stormcrest territory and the eagles have taken to an all out fight with them. It's time to return the favor. We're riding to the Foot Steppes and slaughtering them there.\n\nKing Stormheart left this hammer to me - make good use and see to it that I get it back.", objectives = "" }
WordHunterWoW_QuestEN[12870] = { title = "Ancient Relics", description = "Why hello thar!\n\nBefore you be headin' off to do your grand questin' and adventure, might I beg a wee favor of ya, lad?\n\nThese mountains be packed full'a precious relics and baubles... this place be a dream come true for tha league. I'd be much obliged if ya could bring any such treasures you stumble upon back ta me. You can even share in me ale for tha trouble! Trust me lad, that's a rich deal!", objectives = "" }
WordHunterWoW_QuestEN[12871] = { title = "Aid from the Explorers' League", description = "Interesting. I don't see any locking mechanisms on the shell. That suggests to me that it may take more than just finding the other piece to combine the keystone.\n\nTake the shell back to the expedition leader, Lagnus, at Frosthold. Once he gets over his awe, he should be able to glean what the core looks like based on the shell, and maybe they can get the Frost Dwarves to help find it.\n\nI'm going to see if I can find out how to combine the two pieces. We'll catch up once we've both made some progress.", objectives = "" }
WordHunterWoW_QuestEN[12872] = { title = "Norgannon's Shell", description = "Charging inventor's disk.\n\nDisk charging completed.\n\nPreparing emergency protocol gamma.\n\nEmergency protocol loaded. Please use the charged disk to activate the guardian of Norgannon's shell, Archivist Mechaton. The archivist will release the shell once your identity has been verified.\n\nPlease have a pleasant millennium.", objectives = "" }
WordHunterWoW_QuestEN[12873] = { title = "The Frostborn King", description = "Definitely... I can see exactly what the core must look like. If any of the frostborn have seen it, they'll be sure to recognize the description.\n\nThere's no time to waste, let's get straight to business. Go talk to King Stormheart and request his aid... he's sure to know someone who can help us find the core. And be nice about it will you - he's very respected around here.", objectives = "" }
WordHunterWoW_QuestEN[12874] = { title = "Fervor of the Frostborn", description = "I be more than willing ta lend my shelter and home ta travelers in need, but I'm nae too keen ta force my people inte yer affairs.\n\nI'll tell ye what... my people are warriors, straight and true. On the day a frostborn becomes a man, he has ta prove himself in battle. He has ta show us that he'll not let size hold'm back.\n\nShow me yer as strong and fierce as one of my men, and I'll have them lend ye an ear or a blade. Speak ta Fjorlin over by the cliff to the south there and he'll put ye ta the test.", objectives = "" }
WordHunterWoW_QuestEN[12875] = { title = "An Experienced Guide", description = "I don't know where this core is hiding, but ye knew that. I said I'd help though, and that I shall.\n\nThere's a hermit by the name of Drom Frostgrip who lives in a cave north of here... down in tha valley. We've strayed away from the titans a bit ourselves being that there are so few about, but Drom's loyal to the old ways... he keeps an eye on their most precious places and speaks te the keeper Creteus often.\n\nYer sure to find him in the back of his cave... tell'm I sent ye and he'll help ye.", objectives = "" }
WordHunterWoW_QuestEN[12876] = { title = "Unwelcome Guests", description = "Our scouts have spotted iron dwarves in the valley north of here. I overheard King Stormheart sending you to visit Drom and I'm admittedly a bit worried about'm.\n\nIf you find any iron dwarves when you head down there, put'm down hard and fast for me, eh? I dun think they know exactly where we are or how to get here just yet, and I'd prefer to keep it that way.", objectives = "" }
WordHunterWoW_QuestEN[12877] = { title = "The Lonesome Watcher", description = "I never found the core... but I've often spoken to the keeper Creteus, and his omissions give him away. You'll find Creteus over the mountains to the east, in the Foot Steppes, keeping watch on the Engine of the Makers. The core might well be in there, but you'll need to win Creteus's favor.\n\nThe iron dwarves were here looking for something... it might well be the core. They took my ring. Find their leader, get the ring back, and show it to Creteus so that he knows I sent you.", objectives = "" }
WordHunterWoW_QuestEN[12878] = { title = "The Hidden Relic", description = "During your absence, I was privileged enough to parley with the dwarf Brann Bronzebeard. This dwarf indicated his purpose for seeking the keystone, and I am satisfied that it is for satisfactory intent... I believe this dwarf may be the entity for which the keystone was created.\n\nNorgannon's Core is located in the Frigid Tomb to the southeast. Its guardians are ancient beings of ice, and they will not welcome your presence. Best these guardians and retrieve the keystone with my blessing, {race}.", objectives = "" }
WordHunterWoW_QuestEN[12879] = { title = "Fury of the Frostborn King", description = "<As you retrieve the core from the chest, you hear the thumping of heavy footsteps rushing towards you from the corridor. There is the faint sound of battle in the distance.>", objectives = "" }
WordHunterWoW_QuestEN[12880] = { title = "The Master Explorer", description = "Combining the keystone will require Norgannon's Binding - a device located in the Engine of the Makers, the large pit beside us. Brann should be down there with the other half of the keystone now. I have instructed him on the use of the device. He awaits your presence.\n\nI will do what I can to keep the iron dwarves occupied, but I do not have confidence that I will hold them for long. King Stormheart is returning to the defense of Frosthold with some of his men shortly. Please hurry, {race}.", objectives = "" }
WordHunterWoW_QuestEN[12882] = { title = "Ancient Relics", description = "Welcome to the peaks.\n\nI have a simple request before you head off on whatever grand jaunt you have planned. There are relics and treasures of ancient Ulduar scattered through these mountains. Most are likely in possession of the various sentient races.\n\nReturn any that you find to me, and I will reward you in kind. Perhaps I'll even let you partake on my many potent ales.", objectives = "" }
WordHunterWoW_QuestEN[12883] = { title = "Orders From Drakuru", description = "Minions be hearin' da call of your masta! Da Lich King be givin' Drakuru full control of da armies of da Scourge in Zul'Drak. We be commanded ta kill everyting.\n\nEVERYTING MUST DIE!\n\nWe be processin' all da corpses in da Dead Fields and sendin' em up ta Prince Navarius' crew in  Zeramas for Scourgin'! Notin' goes ta waste on Drakuru's watch!\n\nSoon we be drinkin' da blood of da prophets ta become stronger dan eva before! Zul'Drak and Gundrak gonna fall to da Scourge!", objectives = "" }
WordHunterWoW_QuestEN[12884] = { title = "The Ebon Watch", description = "West of here, across the ruined roads and structures, is the death knight encampment of Ebon Watch.\n\n<Crusader Lord Lantinga rolls up Drakuru's orders.>\n\nTake these orders and deliver them to Stefan Vadu. He is the death knight in command at Ebon Watch. Let him know that the Argent Crusade will deal with Prince Navarius. They'll have to handle Drakuru.\n\nBe careful, {name}. The way to Ebon Watch is teeming with Scourge.", objectives = "" }
WordHunterWoW_QuestEN[12885] = { title = "The Exiles of Ulduar", description = "The Storm Peaks are an intriguing place, but there's far more here than titan ruins. The peoples who live here face a dire threat in Loken and his minions.\n\nHe sent his favorite servants, the iron dwarves, on a brutal campaign against all the creatures of stone. He expelled the earthen from Ulduar, forcing them to take shelter at Bouldercrag's Refuge, on the face of a mountain west of the Inventor's Library. Bouldercrag and his brethren are beset by the iron dwarves there. Find and help them, {name}.", objectives = "" }
WordHunterWoW_QuestEN[12886] = { title = "The Drakkensryd", description = "This is it.  You've passed all the tests of the Hyldsmeet... all but one.  You've risen among our sisters' best and fiercest.\n\nThe final test is at hand.  The Drakkensryd - the true test of a Hyldnir's worth and warrior spirit.  It'll be you, your riding drake, a chained harpoon and a score of your sisters vying for dominance.\n\nShow no quarter.  None will be expected.", objectives = "" }
WordHunterWoW_QuestEN[12887] = { title = "It's All Fun and Games", description = "The Knights of the Ebon Blade want to take the Scourge base known as The Shadow Vault to the northwest. I have a contact in their group who has asked for help.\n\nThe first step is to blind the Lich King. He's using a device known as The Ocular to watch the area, which floats above the vault's spires.\n\nOur dwarves have created something for you to use against it. After the 'eye' has been destroyed, find Baron Sliver on the vault grounds. He's pretending to still be under the Lich King's will.", objectives = "" }
WordHunterWoW_QuestEN[12888] = { title = "SCRAP-E", description = "This card allows the user to access the control panel of the scrapbot designated SCRAP-E, in order to perform maintenance and reprogram the bot's directives.\n\nSCRAP-E appears to be assigned to the interior of the building at The Inventor's Library. The card displays a list of the bot's broken components and failing systems. With the proper parts, the bot can be restored to working condition.", objectives = "" }
WordHunterWoW_QuestEN[12889] = { title = "The Prototype Console", description = "Designation SCRAP-E.\n\nDirective: Maintain consoles and databases of Inventor's Library in Keeper Mimir's absences.\n\nTime since last maintenance cycle: 489 days.\n\nStatus of schematic data: unknown.\n\nCurrent tasks: Repair prototype console.", objectives = "" }
WordHunterWoW_QuestEN[12891] = { title = "I Have an Idea, But First...", description = "When I was in the - ahem - employ of the Lich King, we would often use a device known as a sovereign rod to keep some of the more intelligent Scourge in line.\n\nI require that you assist me in the construction of a new one.\n\nLuckily for you, all of the necessary components are at hand: a cultist rod, an abomination hook, a geist rope, and a handful of Scourge essences.\n\nThis should not be difficult, {class}.", objectives = "" }
WordHunterWoW_QuestEN[12892] = { title = "It's All Fun and Games", description = "The Knights of the Ebon Blade want to take the Scourge base known as The Shadow Vault to the northwest. I have a contact in their group who has asked for help.\n\nThe first step is to blind the Lich King. He's using a device known as The Ocular to watch the area, which floats above the vault's spires.\n\nOur goblins have created something for you to use against it. After the 'eye' has been destroyed, find Baron Sliver on the vault grounds. He's pretending to still be under the Lich King's will.", objectives = "" }
WordHunterWoW_QuestEN[12893] = { title = "Free Your Mind", description = "Vile, Lady Nightswood, and The Leaper would make excellent weapons in the fight against the Lich King if they can be broken from his will. That is what the Sovereign Rod is for.\n\nYou'll find them on the ledges to the east and west of the vault, as well as on the mid-tier of the vault above us. The rod is to be used upon the corpses of the three.\n\nFly now. We will have them as our own!", objectives = "" }
WordHunterWoW_QuestEN[12894] = { title = "Crusader Forward Camp", description = "Crusader Dargath, Crusader MacKellar, Engineer Reed and the twins, Gerk and Burr, were sent to the Dead Fields to establish a battle front days ago. As of my last correspondence with them, they had successfully established a camp on the border of the Dead Fields, northwest of here.\n\nIn light of this newfound information about Drakuru and Prince Navarius I think it would be prudent to send someone to the Crusader Forward Camp post-haste.\n\nPack up your belongings, {name}. You must leave at once!", objectives = "" }
WordHunterWoW_QuestEN[12895] = { title = "The Missing Bronzebeard", description = "Before we left, I received the file Scout Vor'takh compiled on this Brann Bronzebeard. There can be no doubt that Brann was headed for the Storm Peaks from his journal entries and findings in Grizzly Hills. Before we crashed, I caught sight of a campsite south of here, across the Foot Steppes, and overlooking the frozen Bor's Breath River.\n\nIf Brann isn't there, search the camp and its environs for any clues as to where that blasted dwarf might've gone. Bring back anything you find.", objectives = "" }
WordHunterWoW_QuestEN[12896] = { title = "If He Cannot Be Turned", description = "Death knights, such as General Lightsbane, are held on too tight of a leash to be able to be turned from the Lich King's will except under the most extraordinary circumstances.\n\nThe general keeps himself within the vault overseeing the creation of new weapons. Disturb one of his weapon racks at the northern forge and I assure you, he will come. I'll send Vile, Lady Nightswood, and The Leaper in to help you.\n\nIf we are to finally own The Shadow Vault, General Lightsbane must fall!", objectives = "" }
WordHunterWoW_QuestEN[12897] = { title = "If He Cannot Be Turned", description = "Death knights, such as General Lightsbane, are held on too tight of a leash to be able to be turned from the Lich King's will except under the most extraordinary circumstances.\n\nThe general keeps himself within the vault overseeing the creation of new weapons. Disturb one of his weapon racks at the northern forge and I assure you, he will come. I'll send Vile, Lady Nightswood, and The Leaper in to help you.\n\nIf we are to finally own The Shadow Vault, General Lightsbane must fall!", objectives = "" }
WordHunterWoW_QuestEN[12898] = { title = "The Shadow Vault", description = "It sounds like you did extremely well. And you secured three very important allies for the Knights of the Ebon Blade in the process.\n\n<Thassarian gazes out over the horizon.>\n\nYou should head back. By now, Baron Sliver and the other death knights will be fighting tooth and nail to hold The Shadow Vault against the might of the Scourge.\n\nI'm sure they'll need your help.", objectives = "" }
WordHunterWoW_QuestEN[12899] = { title = "The Shadow Vault", description = "It sounds like you did extremely well. And you secured three very important allies for the Knights of the Ebon Blade in the process.\n\n<Koltira gazes down at the map on the floor.>\n\nYou should head back. By now, Baron Sliver and the other death knights will be fighting tooth and nail to hold The Shadow Vault against the might of the Scourge.\n\nI'm sure they'll need your help.", objectives = "" }
WordHunterWoW_QuestEN[12900] = { title = "Making a Harness", description = "So you want to ride?  Well, if you've made it this far someone must think you've got a shot at the Hyldsmeet.\n\nFirst things first; we'll have to make you a harness.\n\nIn the cliffs to the south, you'll find scattered groups of yeti.  Their hides are tough and just the right thickness.  Bring me some and we'll get you started on the path of the bear-rider.", objectives = "" }
WordHunterWoW_QuestEN[12901] = { title = "Making Something Out Of Nothing", description = "Prince Navarius must be stopped. We can't let the Scourge continue to use this area as a zombie factory. If we can get the tank operational we might stand a chance. What I need right now are spare parts.\n\nNorthwest of here is an area called Thrym's End. The Scourge armies are using the area as a base of sorts. Spread out across the base is the wreckage from their arrival. Bits and pieces of Scourge scrap metal litter the landscape. Get that stuff to me and I'll try and put it to good use.", objectives = "" }
WordHunterWoW_QuestEN[12902] = { title = "In Search Of Answers", description = "These poor creatures are the only survivors.\n\nAccording to their chief, the Drakkari trolls and Rageclaw wolvar have been allies for thousands of years. They've been living here, alongside the trolls, for generations, completely unaware of the ever changing world around them. To the Rageclaw, a troll is a troll, so the troll attack upon their den took them by surprise.\n\nWe need some answers, {name}. Scour their village - southeast of here - for clues as to who or what is in charge of these attacks.", objectives = "" }
WordHunterWoW_QuestEN[12903] = { title = "That's What Friends Are For...", description = "We were attacked by Prince Navarius and at least a dozen Scourge. I told Dargath and the twins to stay inside the tank, but they wouldn't listen. Dargath looked me in the eyes and said, \"If somebody doesn't get out of this tank, they'll kill us all.\" He then made Reed cut the engine and charged. Most heroic thing I've ever seen.\n\nI heard the Prince barking orders to the monsters. Sounded like he was taking them to Thrym's End, northwest of here. We have to rescue our friends. Will you go look for them?", objectives = "" }
WordHunterWoW_QuestEN[12904] = { title = "Light Won't Grant Me Vengeance", description = "They... They killed my brother.\n\n<Gerk fights back tears.>\n\nSlaughtered him like he was some sort of animal. Now they got him laid out on one of their tables on the other side of the camp, ready for their grisly experiments. Dargath's dead too. The paladin made a heroic stand at the ruins to the northeast, but the leader of the Vargul, Algar, was too strong.\n\nI'm all that's left and I'll be dead soon too. I... I'm turning.\n\nIf the Light won't grant me vengeance, maybe you will, {class}. Kill them all.", objectives = "" }
WordHunterWoW_QuestEN[12905] = { title = "Mildred the Cruel", description = "Our deal is made then, {name}.  You help me get out of these chains and I'll help you find your little green friend.\n\nThe Hyldnir who runs this mine is known as Mildred the Cruel -- and with good reason.\n\nTell her you've been sent to lend a hand with the mines.  Do whatever she asks until she trusts you with the keys to my shackles.", objectives = "" }
WordHunterWoW_QuestEN[12906] = { title = "Discipline", description = "Let's start you off with something straightforward.  The male vrykul that work the mines for us do so against their will... purely out of fear of our blades.\n\nOnce in a while, one of them will lose their motivation.  Find any uncooperative vrykul and put them in their place.\n\nTake this disciplining rod.  You'll want to inflict pain, not death.  Well, most of the time anyway.", objectives = "" }
WordHunterWoW_QuestEN[12907] = { title = "Examples to be Made", description = "For every action there is an opposite reaction, sister.  In the case of us applying pressure on the males, this has meant newly spread rumors of insurrection.\n\nThe bearded pig behind this rabble-rousing is called Garhal.  Put an end to him... and make sure the other males see his demise.  They must learn that insubordination will not be tolerated.", objectives = "" }
WordHunterWoW_QuestEN[12908] = { title = "A Certain Prisoner", description = "You are without mercy.  You will do well around these parts.\n\nI have another task to ask of you.  There is a female vrykul prisoner that's become more of a liability than I had anticipated.\n\nShe had the gall to claim the right to take part in the Hyldsmeet, our sacred competition of strength and fighting prowess.\n\nHere's the key to her shackles.  Make it as painless as possible.  She's a female after all, even if not one of us.", objectives = "" }
WordHunterWoW_QuestEN[12909] = { title = "The Nose Knows", description = "In order to track down Brann, we're going to need a creature with a keen sense of smell and a good tracking ability. There weren't any hounds on the zeppelin, but I think I have a substitute.\n\nAfter the crash, I sent Khaliisi down the east face of the mountain to start hunting for food. Her cat, Frostbite, excels at tracking prey in the snow. Tell her that she'll have to part with her companion for a while, at least. She can hunt on her own, but we have no other way of catching up to Brann Bronzebeard.", objectives = "" }
WordHunterWoW_QuestEN[12910] = { title = "Sniffing Out the Perpetrator", description = "Boktar can have his way this time, but I'll expect him to make it up to me. Don't look at me like that. Boktar may be in command, but no one tells a hunter what to do.\n\n'Put that beast away,' he says. 'Make it stop growling.'\n\nAll of a sudden he changes his mind when it suits him. Next time he complains, Frostbite'll just nip him a bit. Don't worry, she'll do an admirable job tracking your prey. After she locates her target, you're on your own to deal with iron dwarves, or Brann, or whatever you find.", objectives = "" }
WordHunterWoW_QuestEN[12912] = { title = "A Great Storm Approaches", description = "You are not like the others, little one. You do not reek of the ancient death. Perhaps you can be trusted.\n\nI am Gymer, king of the storm giants. I was lured here by my brother, Thiassi, now an undead servant of the Lich King. By the time I realized that his cry for help was a trap, it was too late. I am now a prisoner of the Scourge and I fear that soon I will suffer the same fate as many of the other storm giants.\n\nFind a way to release me from this cage and I will aid you to the best of my ability.", objectives = "" }
WordHunterWoW_QuestEN[12913] = { title = "Speak Orcish, Man!", description = "<Brann begins gesticulating wildly and rambling in his native language.>\n\nRuk MogOth red a mogoth ta eft Thros-garE Haldir.\n\nKha gor ruk khaz ta ke ruk hrim eft thros-am-kha ruk kost-um havar go kost.\n\nA modoss hine ruk bergum eft thros-am-kha ga eft Haldir ke loch Thon we lo gefrunon ta mitta.\n\n Gar Ruk dagUm loch angor-magi ta har ruk!\n\n<After a few moments, you realize the conversation is going nowhere. Perhaps the shaman, Moteha Windborn, at the Grom'arsh Crash-Site will know what to do.>", objectives = "" }
WordHunterWoW_QuestEN[12914] = { title = "Gymer's Salvation", description = "Now you say that he's locked up in a 100 foot tall cage, eh?\n\nIf my calculations are correct, we should be able to at least weaken the hinges on the cage, giving the giant enough leeway to break out.\n\nIf this is going to work I'm going to need some plasticizers and stabilizers.\n\nBanshee essence should do nicely for the plasticizer. You can get that from the banshees in the Dead Fields, northeast of us. The stabilizer can be found on the earthragers to the southwest, near Ebon Watch.\n\nGet a move on!", objectives = "" }
WordHunterWoW_QuestEN[12915] = { title = "Mending Fences", description = "If I hope to wrest control of the Temple of the Makers from my brother, I must make amends with my old allies.\n\nPerhaps by eliminating a common enemy, we may at least take a step towards renewing my friendship with the frost giants.\n\nFjorn has besieged Dun Niffelem with giants of iron. You must defeat him at Fjorn's Anvil, far to the east of here, and weaken his forces sufficiently for the Sons of Hodir to emerge victorious.\n\nTake this charm, {name}. Use it to summon my earthen to your aid.", objectives = "" }
WordHunterWoW_QuestEN[12916] = { title = "Our Only Hope", description = "What I'm about to give you is called seaforium. It is a highly volatile explosive with some unique properties. Due to its malleable nature, you will be able to fill in the hinges and cracks of the cage for maximum damage.\n\nReturn to your friend and use the jumbo seaforium charge to set him free.\n\nLet's hope he honors the bargain. He's our only hope.", objectives = "" }
WordHunterWoW_QuestEN[12917] = { title = "Speaking with the Wind's Voice", description = "I suppose we shouldn't have expected to find Brann so easily, not with our luck. If we can make sense of what Brann is saying, you can persuade him to give up his location.\n\nThe power of the wind is strong in these mountains, and it may prove a great boon to us. A knowledgeable shaman can hear the sound of all the world's tongues on the wind.\n\nTo the northwest, on the Snowdrift Plains, you will find beings made of wind, the stormriders. Capture their voices and bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[12919] = { title = "The Storm King's Vengeance", description = "My people have been decimated by the Lich King. The Scourge now use the corpses of storm giants to create mindless flesh giants, or worse, stitched together aberrations like Thrym.\n\nI will stop at nothing to see them all driven from this world. We will work together to destroy the Scourge that threaten Zul'Drak.\n\nWe will kill them all: Navarius, Algar and Thrym!\n\nWhen you are ready, let me know and we will begin our destructive journey.", objectives = "" }
WordHunterWoW_QuestEN[12920] = { title = "Catching up with Brann", description = "What are you waiting for? The language barrier has been broken, thanks to Moteha. Contact Brann Bronzebeard and find out anything you can about where he's hiding and what he's chasing after.\n\nMaybe we can still salvage something from this disaster.", objectives = "" }
WordHunterWoW_QuestEN[12921] = { title = "A Change of Scenery", description = "Excellent.  There's an exit in the eastern end of the mine that leads to Brunnhildar Village.  Follow it and I'll meet you there.\n\nWe must not be seen together so no one suspects you of aiding me.  I'll use my magic to disguise my appearance.  Do not worry, {race} -- we'll find your friend in no time.", objectives = "" }
WordHunterWoW_QuestEN[12922] = { title = "The Refiner's Fire", description = "Beneath its porous exterior, this hunk of metal gleams with a mysterious quality.\n\nYou feel it would only be prudent to burn off the slag at Fjorn's Anvil.\n\nAs you ponder where in this frozen waste you might find something hot enough for the job, a fire revenant crosses your path...\n", objectives = "" }
WordHunterWoW_QuestEN[12924] = { title = "Forging an Alliance", description = "<Thorim, for the first time since your meeting him, smiles.>\n\nThis is all beginning to have the smell of fate's hand, {race}.\n\nYour discovery is what remains of my armor, long ago cast off in a fit of grief and left to the elements. Only the sons of Hodir are capable of its reforging, for they are its original creators.\n\nPerhaps you've done enough to soften their hatred of me. Seek out their king, Jokkum, if he still breathes.\n\nFind your way into his good graces and plead for his assistance.", objectives = "" }
WordHunterWoW_QuestEN[12925] = { title = "Aberrations", description = "The Lich King sent emissaries to us on three different occasions.  All three were promptly dismembered.\n\nOur sisters in Valkyrion were not as dedicated to our traditions and accepted the Scourge's advances.  Now instead of capturing their drakes from the wild, they raise them from the blight and filth that the Scourge wallow in.\n\nTake the frost oil that the Valkyrion Hyldnir carry on them and use it to freeze any blighted eggs you find.  Rumors speak of a fetid pool of blight where the eggs are kept.", objectives = "" }
WordHunterWoW_QuestEN[12926] = { title = "Pieces of the Puzzle", description = "We've seen the iron dwarves and their constructs making war on the creatures of stone that Brann calls the earthen, along with their giant allies. Contact him and aid him in any way you can, and remember that anything we can learn from his search may aid us in fighting against the iron dwarves and their master.", objectives = "" }
WordHunterWoW_QuestEN[12927] = { title = "Data Mining", description = "That disk you assembled... it's blank! Keeper Mimir, the tinker who built this library, must've hidden the information elsewhere. Look around the Inventor's Library; do you see any databanks there?\n\nThat might be the disk's purpose. Try using it near some of those databanks. Perhaps it's set to retrieve and store information from them. After you've tried your hand at that, contact me again and let me know what you've found. Meanwhile, I'll be trying to track down the other half of the archive key.", objectives = "" }
WordHunterWoW_QuestEN[12928] = { title = "Norgannon's Shell", description = "Charging inventor's disk.\n\nDisk charging completed.\n\nPreparing emergency protocol gamma.\n\nEmergency protocol loaded. Please use the charged disk to activate the guardian of Norgannon's shell, Archivist Mechaton. The archivist will release the shell once your identity has been verified.\n\nPlease have a pleasant millennium.", objectives = "" }
WordHunterWoW_QuestEN[12929] = { title = "The Earthen of Ulduar", description = "The earthen who once inhabited, built, and maintained Ulduar were ousted from their home when Loken took over the city. Since then, his iron dwarf followers have relentlessly attacked the exiles.\n\nThey have taken refuge in an old titan building, which they now call Bouldercrag's Refuge, on the face of a mountain west of the Inventor's Library. Bouldercrag and his brethren fight to keep the irons from overrunning their haven, but they cannot hold their ground long. Find and help them, {name}.", objectives = "" }
WordHunterWoW_QuestEN[12930] = { title = "Rare Earth", description = "It seems so long ago that these hammers pounded and hewed stone instead of iron. Our expulsion from Ulduar saw the weakest of us dead and the strongest of our craftsmen reborn as warriors.\n\nAs the irons beat us back, even the strongest find themselves failing.\n\nWe can do little for the wounded, save when we have a stock of enchanted earth. We used to mine it from the deposits on the sheer cliff face to the northwest, but the constant battle has prevented us from replenishing our stock. Would you help?", objectives = "" }
WordHunterWoW_QuestEN[12931] = { title = "Fighting Back", description = "The refuge's defenders have done their best to blunt the iron dwarves' attacks, but we keep losing ground inch by inch. My men are hardy, but not tireless. Without reinforcements, it's only a matter of time until we will be overrun.\n\nWould you lend your skills to the refuge's defense? It would greatly improve the morale of the defenders and give them -- and me -- hope of mounting a counterattack.\n\nKill any of the stormforged or their creations you encounter outside the refuge.", objectives = "" }
WordHunterWoW_QuestEN[12932] = { title = "The Amphitheater of Anguish: Yggdras!", description = "I'll tell you what, buddy, this place is a far cry from the rolling plains of Nagrand. These trolls are dirtier than ogres; but hey, I go where the gold's at! So welcome to Zul'Drak, pal.\n\nYou're new to this racket, so let me set you straight. I'm the fight promoter and this feisty troll next to me is Wodin, my bodyguard. You're the entertainment. When you wanna fight, let me know and I'll set up the match.\n\nIf you're ready and got a group of friends with you, we can start! What do you say?\n", objectives = "" }
WordHunterWoW_QuestEN[12933] = { title = "The Amphitheater of Anguish: Magnataur!", description = "This next match is a doozy, buddy! Apparently some magnataur from the Dragonblight wants a piece of the action. You ever fought one of those before? All I can tell you is to aim high!\n\nWe'll get this party started when you give me the word.", objectives = "" }
WordHunterWoW_QuestEN[12934] = { title = "The Amphitheater of Anguish: From Beyond!", description = "I'm not gonna lie to you, pal. You might be overmatched here. This next one is a being from the elemental planes! I don't even know what's gonna show up in that arena!\n\nIf you think you're up to it, get in there and give 'em hell!", objectives = "" }
WordHunterWoW_QuestEN[12935] = { title = "The Amphitheater of Anguish: Tuskarrmageddon!", description = "This next one's fightin' from a dark place, kid. The kind of dark that can only happen when you've been on the flip-side. He's hungry and willing to do whatever it takes to win. Watch yourself! I've heard he wrestles yetis for exercise!\n\nWe'll start when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[12936] = { title = "The Amphitheater of Anguish: Korrak the Bloodrager!", description = "You're not gonna believe this, pal. Your next fight is against Korrak the Bloodrager! Looks like the Drakkari trolls are pulling a power play! And let me tell you, buddy, he's been sippin' the animal god juice. He's good and ready to pound you into the ground.\n\nAre you ready?", objectives = "" }
WordHunterWoW_QuestEN[12937] = { title = "Relief for the Fallen", description = "The refuge's defenders fight bravely, but they cannot keep up with the iron onslaught.\n\nWith the earth you collected, I can make bandages to help heal the wounds of some of the fallen. The more defenders we can patch up, the longer we'll last out there.\n\nTake these poultices and use them to heal the wounds of the fallen defenders outside the refuge. Get as many back into the battle as possible, {name}. Every casualty is one too many.", objectives = "" }
WordHunterWoW_QuestEN[12938] = { title = "The Duke", description = "We need you focused, {name}. We're barely holding The Shadow Vault as it is. As you can see, we've greatly angered the Lich King.\n\n<The baron chuckles.>\n\nI need you to speak with Duke Lankral. He's in charge here now. You'll find him inside the vault building proper.\n\nWere I you, I would not keep him waiting.", objectives = "" }
WordHunterWoW_QuestEN[12939] = { title = "Honor Challenge", description = "The first step we're going to take is at a place in Jotunheim called the Savage Ledge. It's just over the mountains to the west.\n\nOn the ledge the vrykul warriors are always sparring, being instructed in the finer arts of battle by their thane's men.\n\nI want you to take this flag and issue a challenge to a number of them. Let's demoralize them with the 'mere' skills of a {race}, shall we?\n\n<The duke grins, his rotting teeth flashing in the dim light of the vault.>", objectives = "" }
WordHunterWoW_QuestEN[12940] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[12941] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[12942] = { title = "Off With Their Black Wings", description = "Traitors.  We Hyldnir have little love for them.\n\nThe dwellers of Valkyrion have gone unpunished for far too long.  While we remained loyal to Thorim, they became the Lich King's lapdogs!\n\nThey call the ones who receive his gift val'kyr.  They fly on feathered wings, like the harpies they are.\n\nYou will find Valkyrion far to the northwest, beyond the Temple of Storms.  Slay these winged she-wolves, sister.  Slay them and I will reward you with one of my most prized possessions.", objectives = "" }
WordHunterWoW_QuestEN[12943] = { title = "Shadow Vault Decree", description = "Thane Ufrang the Mighty sits within his hall overlooking the Savage Ledge. I've studied him. The thane is a patient vrykul, with a head for strategy and warfare. He's also shown a penchant for biding his time and not wanting to overplay his hand in the ongoing battle.\n\nI need him dead!\n\nI've written a decree. Stand before the thane and read it aloud.\n\n<The duke arches his eyebrow in amusement.>\n\nIt should... unnerve him at the least.", objectives = "" }
WordHunterWoW_QuestEN[12944] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[12945] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[12946] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[12947] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[12948] = { title = "The Champion of Anguish", description = "This is the end, my friend! Your last opponent is going to be your greatest challenge. He's a vrykul champion from the steppes of Icecrown and he's out for blood! Defeat him and you'll be crowned the champion of the Amphitheater of Anguish! This fight is going to make us both rich!\n\nLet me know when you're ready and we'll start.", objectives = "" }
WordHunterWoW_QuestEN[12949] = { title = "Get the Key", description = "{class}, the key to my shackles is hanging around the neck of Instructor Hroegar outside.\n\nPerhaps you could retrieve it by separating his head from his shoulders?", objectives = "" }
WordHunterWoW_QuestEN[12950] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[12951] = { title = "Let the Baron Know", description = "The most important thing that you can do right now is to return to The Shadow Vault and let Baron Sliver know that I've failed.\n\nYou see, I wasn't the only one captured by these vrykul devils. My entire contingent of death knights was also taken.\n\nI should have seen the trap before it was sprung, but there's no use crying over spilled milk now is there?\n\nGo on before you get captured, too! I'll see you back at the vault.", objectives = "" }
WordHunterWoW_QuestEN[12953] = { title = "Valkyrion Must Burn", description = "The crate is filled with incendiary harpoons.  You recall seeing harpoon guns and dry stacks of hay outside.\n\nPerhaps Iva will appreciate the extra effort and reward you appropriately.", objectives = "" }
WordHunterWoW_QuestEN[12954] = { title = "The Amphitheater of Anguish: Yggdras!", description = "I was wondering when you'd show up, {name}! Having a past champion of the Ring of Blood here will be a huge draw! We're gonna be rich, buddy! RICH!\n\nAnyway, this dump is Zul'Drak. All the ice trolls seem to use it as a toilet. I dunno, the whole place is off its rocker if you ask me! Who cares, though, right? We're here to make some gold!\n\nYou know the drill, {name}. When you're ready let me know and we'll get this show on the road!\n", objectives = "" }
WordHunterWoW_QuestEN[12955] = { title = "Eliminate the Competition", description = "Mrrfrmrfrrmrrr...\n\n<The Leaper clears his throat.>\n\nSorry about that. It can sometimes be hard to understand what I'm saying. You know how it is.\n\nI wanted to make sure that if you find yourself at the Savage Ledge, over the mountains to the west, that you make sure to eliminate the competition there.\n\nSpecifically, I'd like you to challenge to duels and humiliate Sigrid Iceborn, Efrem the Faithful, Onu'zun, and Tinky Wickwhistle in front of the vrykul.", objectives = "" }
WordHunterWoW_QuestEN[12956] = { title = "A Spark of Hope", description = "Clearly, this is more than an ordinary hunk of metal.\n\nUnlike any ore you're familiar with, it is hard but not brittle, far lighter than it looks, and glows even when cool.\n\nLooking closer, you can make out one of Thorim's runes shining beneath the surface....", objectives = "" }
WordHunterWoW_QuestEN[12957] = { title = "Slaves of the Stormforged", description = "To the southwest, on the western side of the Snowdrift Plains, the iron dwarves have dug a mine into the hillside. There, they use captive mechagnomes, servants of Keeper Mimir, to mine ore.\n\nI don't know where these mechagnomes came from, nor what they would do with their freedom, but perhaps we can win their help.\n\nGo to the Frozen Mine, {name}, and set these creatures free from their bondage. Ask if they would fight alongside us against iron dwarf tyranny.", objectives = "" }
WordHunterWoW_QuestEN[12958] = { title = "Shipment: Blood Jade Amulet", description = "A wealthy shipping concern has requested a collection of Blood Jade Amulets to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.\n", objectives = "" }
WordHunterWoW_QuestEN[12959] = { title = "Shipment: Glowing Ivory Figurine", description = "A wealthy shipping concern has requested a collection of Glowing Ivory Figurines to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.\n", objectives = "" }
WordHunterWoW_QuestEN[12960] = { title = "Shipment: Wicked Sun Brooch", description = "A wealthy shipping concern has requested a collection of Wicked Sun Brooches to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.\n", objectives = "" }
WordHunterWoW_QuestEN[12961] = { title = "Shipment: Intricate Bone Figurine", description = "A wealthy shipping concern has requested a collection of Intricate Bone Figurines to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.\n", objectives = "" }
WordHunterWoW_QuestEN[12962] = { title = "Shipment: Bright Armor Relic", description = "A wealthy shipping concern has requested a collection of Bright Armor Relics to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.\n", objectives = "" }
WordHunterWoW_QuestEN[12963] = { title = "Shipment: Shifting Sun Curio ", description = "A wealthy shipping concern has requested a collection of Shifting Sun Curios to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.\n", objectives = "" }
WordHunterWoW_QuestEN[12964] = { title = "The Dark Ore", description = "At the Frozen Mine in the western part of the Snowdrift Plains, the stormforged iron dwarves have constructed a mine manned by slaves.\n\nIt's well behind the lines, so we haven't been able to find out much about what's going on there, but my scouts have reported seeing them remove cartloads of dark, sickly looking ore.", objectives = "" }
WordHunterWoW_QuestEN[12965] = { title = "The Gifts of Loken", description = "The one who commands the stormforged iron dwarves is called Runeseer Valduran. Although I have never seen them, it is said that his master, Keeper Loken, who took over Ulduar, has given Valduran powerful titan artifacts.\n\nIt could explain the strength and ferocity my men see in the stormforged warriors.\n\nValduran's base, Nidavelir, lies to the southwest, across the Snowdrift Plains. Go there, {name}, and neutralize his power. Destroy these gifts of Loken's and help us to sap the strength of his followers.", objectives = "" }
WordHunterWoW_QuestEN[12966] = { title = "You Can't Miss Him", description = "<Jokkum listens patiently to your request, then ponders it carefully before responding.>\n\nSo it is you we have to thank for Fjorn's demise?\n\nWhile it's true that you have aided us in our time of need, there is still much that must be done to repair our relations with Thorim.\n\nFor now, I shall allow Njormeld to reforge the armor we gifted to the Stormlord so many ages ago. Consider it payment for your assistance against Fjorn.\n\nNjormeld was sent to recover Fjorn's anvil. You should find him there.", objectives = "" }
WordHunterWoW_QuestEN[12967] = { title = "Battling the Elements", description = "Snorri was once the pride of our nation. A mighty warrior, many an enemy fell to his club.\n\nWe honor him, though he's no longer what he once was. Age has taken its toll, dulling his senses and sapping his strength. Still, he remains as proud as ever, never missing an opportunity to join a battle.\n\nSpeaking of battle, we're cooling Fjorn's anvil so it can be taken home. The remaining fire revenants are putting up some resistance. Help Snorri relive his glory days, {race}. Guide him against this enemy.", objectives = "" }
WordHunterWoW_QuestEN[12968] = { title = "Yulda's Folly", description = "The witch that started it all, Yulda the Stormspeaker came to our very village.  She dared to insult our noble traditions and spouted the Lich King's venomous promises of power.\n\nShe ought to have left with a sword through her, but her magic was strong and she managed to escape.\n\nSeek her in Valkyrion inside the largest dwelling and show her that we are not to be trifled with.", objectives = "" }
WordHunterWoW_QuestEN[12969] = { title = "Is That Your Goblin?", description = "I trust that's the green little one you've been looking for.  If I were you I'd step in before that Hyldnir splits him in half.\n\nYou've arrived in the middle of the Hyldsmeet, so all challenges must be accepted by participants.  There's nothing to stop you from taking your green friend's place.", objectives = "" }
WordHunterWoW_QuestEN[12970] = { title = "The Hyldsmeet", description = "Whether you've noticed or not, by defeating your first Hyldnir in hand-to-hand combat, you've entered the Hyldsmeet -- the great competition of Hyldnir against Hyldnir to determine who will rule by Thorim's side.\n\nThe Hyldsmeet is the reason why I was imprisoned, for I sought to partake in the competition but was far too old and frail to be a match for the Hyldnir.\n\nIf you're willing to listen, I've a proposal for you.", objectives = "" }
WordHunterWoW_QuestEN[12971] = { title = "Taking on All Challengers", description = "Let's get you started.  The good news is that by defeating Agnetta, you've earned yourself a spot in the next round of matches.\n\nThe bad news is that all your opponents will also have defeated someone in the first round.  Do not expect pushovers.", objectives = "" }
WordHunterWoW_QuestEN[12972] = { title = "You'll Need a Bear", description = "You've succeeded in the first rounds of the Hyldsmeet.  To advance further, you're going to need a warbear of your own.\n\nUnfortunately, the Hyldnir don't give them out to just anyone.  You'll have to emerge victorious from true battle, not just gladiatorial combat.\n\nThe Hyldnir of Brunnhildar are currently involved in a feud against the Sons of Hodir, Thorim's former allies.  Speak to Brijana just outside the village and see how you can help them and prove yourself in the process.", objectives = "" }
WordHunterWoW_QuestEN[12973] = { title = "The Brothers Bronzebeard", description = "That does it! We finally have the keystone... It's beautiful! I've been around the world more than once, but this thing's got me all jittery with excitement again. I suppose now's not the time to stop and admire though, we need to get the heck out of here.\n\nHop on my flying machine and help keep us covered from those iron dwarves on the way out!", objectives = "" }
WordHunterWoW_QuestEN[12974] = { title = "The Champion's Call!", description = "Pfft, what happens down here ain't fightin'. It's a couple of guys dancin' around a flag.\n\nYou lookin' for some real action, buddy? 'Cause if you are I got the hottest ticket in town.\n\nEver heard of Gurgthock and Wodin? Goblin and troll who ran the Ring of Blood back in Outland? Well they're here in Northrend and they've started up a whole new fight club over in Zul'Drak. If you're interested go to Zul'Drak, east of Crystalsong. They're at the big arena in the center. Tell 'em Shifty sent ya!", objectives = "" }
WordHunterWoW_QuestEN[12975] = { title = "In Memoriam", description = "Surely Thorim has told you of the tragedy that divides us.\n\nIt was in Thunderfall, northeast of here, that these events unfolded. The frozen fossils there are a reminder of that dark day, as are the spirits that haunt that place.\n\nIf my people are to forgive Thorim, something must take the place of those images. A memorial must be constructed to bring our hearts peace.\n\nGo there, {race}. Collect the fragments of Hodir's Horn that was shattered that day.", objectives = "" }
WordHunterWoW_QuestEN[12976] = { title = "A Monument to the Fallen", description = "Bring these fragments to Njormeld. He will use the pieces of that sacred relic in the construction of a mighty monument.\n\nMay it soothe the pains and heal the scars my people have borne these many years.\n\nMay its presence help to bring about a new age that sees us once again in glorious battle at Thorim's side.\n\nGo now, {class}. Njormeld awaits you.", objectives = "" }
WordHunterWoW_QuestEN[12977] = { title = "Hodir's Call", description = "You have done a great service to the giants of Dun Niffelem. Without your aid, this monument would not exist.\n\nAs you silently ponder its significance, feelings begin to flood your heart. The feelings fill your mind with thoughts and images... as well as a sense of urgency.\n\nThe sensations fade and leave you with a knowledge of what you must do. The restless spirits at Thunderfall must be put to rest.\n\nAs you set off, you find that your hands have been filled with an ethereal horn.", objectives = "" }
WordHunterWoW_QuestEN[12978] = { title = "Facing the Storm", description = "Like Bouldercrag, I once served the keepers as a craftsman in Ulduar, but with Loken's betrayal, I turned my hammer toward our new foes.\n\nWhen we could spare the men, I led raids on Nidavelir to relieve the pressure on our defenders, but our lines are near collapse.\n\nYou've proven yourself a capable combatant and a staunch ally. Perhaps you'd be willing to take up our banner and take the fight to Nidavelir, the iron dwarf stronghold to the southwest, across the Snowdrift Plains.", objectives = "" }
WordHunterWoW_QuestEN[12979] = { title = "Armor of Darkness", description = "This armor plate is thick and oversized compared to the rest of the golem's defenses. A quick examination of the golem's corpse reveals that this heavier plate seems to have been bolted on as an afterthought or a crude upgrade.\n\nWhy would the iron dwarves have added this redundant and mismatched armor to their war golems?\n\nPerhaps Bruor Ironbane would know if he had the chance to examine several of these plates from stormforged war golems.", objectives = "" }
WordHunterWoW_QuestEN[12980] = { title = "The Armor's Secrets", description = "The presence of that armor plate is disorienting, but we need to find out all we can from it. It could be part of one of Valduran's schemes.\n\nHe's dedicated an extraordinary amount of effort to mining, refining, smithing, and testing this metal.\n\nTo the east, along the northern mountain face, is a building called Mimir's Workshop. It hasn't been used in quite some time, but if we're lucky, some of its attendants are still functional. Take your armor plate there and learn what you can from it.", objectives = "" }
WordHunterWoW_QuestEN[12981] = { title = "Hot and Cold", description = "As you stare at the anvil you relive your recent accomplishments, particularly those which brought this artifact to rest here.\n\nIt suddenly occurs to you that more remains to be done. To the east, smoldering scraps clutter the landscape--shrapnel from the battle fought there.\n\nIf they could be cooled and gathered somehow, the frost giants would have an abundant supply of metal and the region would be cleared of these remnants of war.", objectives = "" }
WordHunterWoW_QuestEN[12982] = { title = "Ebon Blade Prisoners", description = "Now that I'm back, I'm certain that the baron will want me to recover my men. I can see that we're barely hanging on here. The Lich King's forces are about to break through and we won't be able to hold without my captured death knights.\n\nCan you assist me once more, {name}?\n\nGo back to Jotunheim and let them out of those cages. Break the damn locks, I don't care what you have to do. The vrykul likely have the keys.\n\nJust get my men free!", objectives = "" }
WordHunterWoW_QuestEN[12983] = { title = "The Last of Her Kind", description = "For as long as I can remember, we've obtained our best bears from the Hibernal Cave to the east.\n\nThose times might finally be gone.  The cave has been overrun by ravenous jormungar and the wild bears are all but extinct.\n\nIf you were to find a surviving matriarch, however, I would guarantee you that she would fight better than any of these bears born in captivity.\n\nTake this harness to the Hibernal Cave and rescue a surviving matriarch.  Good luck finding one.", objectives = "" }
WordHunterWoW_QuestEN[12984] = { title = "Valduran the Stormborn", description = "We have no choice, {name}. What you learned in Mimir's Workshop means that we must act before Valduran can complete and unleash his new weapon.\n\nEven now, the refuge's defenders fight to buy us time to deal with Valduran the Stormborn.\n\nYou must go to Nidavelir, across the Snowdrift Plains to the southwest, and then find and face Valduran. But you will not be alone. Bring this war horn with you and sound it as you prepare to face the leader of our enemies. Bruor and I will aid you in this battle.", objectives = "" }
WordHunterWoW_QuestEN[12985] = { title = "Forging a Head", description = "Greetings, {race}.\n\nI have a task that King Jokkum felt you would be suited for, assuming you still strive to gain favor with our people.\n\nI have developed plans for another artifact, one that will grant Hodir's blessing of protection to our stronghold. I have nearly all that I require for its construction. All that remains to collect are the very eyes of our fallen enemies.\n\nTake this tool, and gather the eyes from the iron giant corpses that litter our fields.", objectives = "" }
WordHunterWoW_QuestEN[12986] = { title = "Fate of the Titans", description = "Norgannon's Core is not at this location. I am not sure why you seek it, {race}, and I am equally unsure if you truly know the purpose of that which you seek.\n\nI would like you to aid me before I consider extending my assistance.  I have recently encountered knowledge of the watcher, Thorim. His seat of power is contested, and his fate remains to be seen. This troubles me, for I do not know of the other watchers. Utilize this databank to examine their temples to the northeast and return the knowledge to me.", objectives = "" }
WordHunterWoW_QuestEN[12987] = { title = "Placing Hodir's Helm", description = "The helm is forged.\n\nYour efforts have not gone unnoticed, small one. Though there remains much to do, we sons of Hodir are grateful for your accomplishments.\n\nIn return, I offer you the opportunity to present Hodir's helm to our king and our brethren.\n\nFly to the sparkling tip of the small ice spike in front of me and read to our people from this tablet.\n\nEnjoy the privilege, {class}. Never before has an outsider been given such an honor!", objectives = "" }
WordHunterWoW_QuestEN[12988] = { title = "Destroy the Forges!", description = "In my folly, I'd thought Valduran's project at Narvir's Cradle, a large construction area to the south, no more than a grotesque monument to \"Keeper\" Loken's cruelty.\n\nNow we know the truth, that it was meant to be used as a weapon against us and our allies. We must not allow this iron colossus to reach completion, {name}, for it will mean the end of the refuge.\n\nGo to Narvir's Cradle, find the lightning forges the stormforged artisans use, and sabotage them.", objectives = "" }
WordHunterWoW_QuestEN[12989] = { title = "The Slithering Darkness", description = "The vile jormungar have taken over most of the Hibernal Cavern.  They are despicable beings... children of Loken, Thorim's scumsucker of a brother.\n\nAs Thorim's servants we owe it to ourselves to kill these scum where we find them.  You'll find the cavern just east of here, outside the village.", objectives = "" }
WordHunterWoW_QuestEN[12991] = { title = "Hit Them Where it Hurts", description = "Bouldercrag's got a good plan to stymie the efforts of the iron dwarves at Narvir's Cradle, and I've got an idea of my own. Work on the iron colossus will come to a halt without any artisans.\n\nNarvir's Cradle is on the south side of the hill sheltering Bouldercrag's Refuge. Go there and slay any stormforged artificers in your path. They may be no different from what we once were, but they build a weapon that threatens us all.", objectives = "" }
WordHunterWoW_QuestEN[12992] = { title = "Crush Dem Vrykuls!", description = "Dem vrykuls at the Jotunheim needs to be crushed!\n\n{name} crush dems good!", objectives = "" }
WordHunterWoW_QuestEN[12993] = { title = "A Colossal Threat", description = "You've done an excellent job of delaying the work on the iron colossus, but I fear we've only made the stormforged more determined to complete the weapon.\n\nEven now, they're bringing in new laborers and the overseers push them to the limit. We may not be able to keep them from bringing the colossus online, after all. Return to Narvir's Cradle, to the south and find the documents detailing the colossus' offensive and defensive abilities. They should be near the tents and forges on the bottom level.", objectives = "" }
WordHunterWoW_QuestEN[12994] = { title = "Spy Hunter", description = "The rapport you've developed with the inhabitants of Dun Niffelem has yielded some unexpected discoveries.\n\nFor example, you somehow find yourself able to understand the denmother's guttural growls and sharp quips--at least you think you do.\n\nIt would seem that she senses danger outside the stronghold and wants you to do something about it.\n\nWith her forepaw, she removes the chain from around her neck and lets it drop at your feet. As you pick it up you notice an aged fang attached to it...", objectives = "" }
WordHunterWoW_QuestEN[12995] = { title = "Leave Our Mark", description = "We must attack the vrykul of Jotunheim on many levels. Brute force, of course, is good, but I prefer a more cerebral approach.\n\nI want you to demoralize them.\n\nMy men here have forged a number of banners for you. I would like for you to take and plant them near the corpses of fallen vrykul.\n\nLet the banners serve as a constant reminder to them that they face a more immediate threat than the wrath of the Lich King.", objectives = "" }
WordHunterWoW_QuestEN[12996] = { title = "The Warm-Up", description = "You've been very fortunate, sister.  This is a matriarch the likes of which hasn't been seen in years.\n\nA good bear won't do you much good without the skill to ride it.\n\nI'm going to have you practice some moves on Kirgaraak.  He's the largest yeti we've ever managed to capture so be careful.  Don't be afraid to walk away if he gives you a beating... there's a reason why we keep him chained.", objectives = "" }
WordHunterWoW_QuestEN[12997] = { title = "Into the Pit", description = "Besting a tethered opponent is one thing.  Fighting other bear riders on equal footing is another.\n\nHead into the Pit of the Fang and use what you've learned to defeat your opponents.  Good luck, sister.\n\nGlory awaits, should you succeed.", objectives = "" }
WordHunterWoW_QuestEN[12998] = { title = "The Heart of the Storm", description = "According to the documents you captured at Narvir's Cradle, the iron colossus is complete except for one key component -- the Heart of the Storm.\n\nWithout it, the iron colossus' weapons would be much weaker than the design predicts. If we can deny Overseer Narvir the heart, we could defeat the colossus!\n\nNotes on the documents you found say that the heart is in Uldis, a titan facility far to the south. Its entrance is on the south side of a tall mountain overlooking the Bor's Breath River.", objectives = "" }
WordHunterWoW_QuestEN[12999] = { title = "The Bone Witch", description = "You remember Lady Nightswood, don't you? She certainly remembers you. She's the forlorn and very angry banshee that you 'saved' when you also broke Vile and myself out from under the Lich King's dominion.\n\nThe lady has gone into Jotunheim and possessed their bone witch. She intends to wreak havoc upon the vrykul from within.\n\nShe has asked that you seek her out. You'll find her in the cave on the south side of Njorndar Village to the southwest within Jotunheim.", objectives = "" }
WordHunterWoW_QuestEN[13000] = { title = "Emergency Measures", description = "The cold in these mountains is brutal.  We have a day or two before we burn up all the wood from the wreckage.\n\nWe spotted worgs inside a cave directly east of here.  I need you to find the cave and obtain some furs.  It might not sound like much, but it might be the difference between freezing to death and living another day.\n\nWorgs don't hunt alone, so I'm giving you a flare.  It should buy you some time if you find yourself outnumbered.", objectives = "" }
WordHunterWoW_QuestEN[13001] = { title = "Forging Hodir's Spear", description = "The time has come, little {class}. The stars have foretold of this day.\n\nI have received a vision from mighty Hodir himself, revealing the secret to the creation of a great artifact.\n\nWe must obey! Were we to fail in receiving this gift, doom would surely follow.\n\nI call upon you to assist me in this sacred undertaking.\n\nGo across the valley, deep into the Hibernal Cavern and gather everfrost shards from the icy crater there, then collect hides from the mammoths outside the cavern.", objectives = "" }
WordHunterWoW_QuestEN[13003] = { title = "How To Slay Your Dragon", description = "Hodir's Spear is an icon of great prowess in battle.\n\nIts mere presence instills a deep hunger for glory in all who enter Dun Niffelem. In fact, simply being near it has compelled you to test your own abilities.\n\nScanning the horizon, your vision locks on a wild wyrm as it flies nearby.\n\nIt is decided. Of you and he, only one shall see the next sunrise....", objectives = "" }
WordHunterWoW_QuestEN[13005] = { title = "The Earthen Oath", description = "For years I neglected my duties, giving into defeat and self-pity.\n\nNot the brave earthen, however.  Their oath to protect these grounds with their lives has gone unbroken.\n\nEven now, they fight the corruption of iron with selflessness, waiting for the moment in which the tides turn.\n\nThat moment has arrived.  We must rally what remains of the earthen defenders and lead them into a glorious victory.  Sound the Horn of the Peaks to call them to your side and take back the Terrace of the Makers.", objectives = "" }
WordHunterWoW_QuestEN[13006] = { title = "A Viscous Cleaning", description = "As you draw near the helm, you notice that the frigid environment is already taking its toll on the artifact's surface. What is now just a thin layer of ice will surely grow to envelop it entirely.\n\nNot about to let your hard efforts go to waste, you resolve to scour the region in search of a solution.\n\nJust as you set off, the eyes of the helm flash and an image of the nearby Hibernal Cavern enters your mind.", objectives = "" }
WordHunterWoW_QuestEN[13007] = { title = "The Iron Colossus", description = "We have failed to prevent the completion of the iron colossus, {name}, which means we have no choice but to face it in battle.\n\nBruor has devised a plan to exploit the colossus' only weakness.\n\nNo matter how tough the colossus' armor is, it is still vulnerable to a jormungar's acid. Take control of one using the orbs along the northern edge of the Snowdrift Plains, then use it to fight the Iron Colossus on the Snowdrift Plains. If you need help controlling the creature, speak to one of the nearby handlers.", objectives = "" }
WordHunterWoW_QuestEN[13008] = { title = "Scourge Tactics", description = "We had the element of surprise on our side! We blew a hole in the side of the mountain and charged into Scourgeholme. Scourge opposition was fierce and it wasn't long until we were overwhelmed. We fell back to the valley and began raining artillery down on the Scourge that followed. This held them back for awhile until... Those monsters began using crusaders as living shields. We had to stop shelling for fear of killing our own soldiers.\n\nFree our crusaders trapped on the field outside the base, {class}!", objectives = "" }
WordHunterWoW_QuestEN[13009] = { title = "A New Beginning", description = "It remains uncertain whether or not our people can ever rekindle the affection we once held for Thorim.\n\nMay this armor, if nothing else, remind him of the days when we stood together in honor, invincible.", objectives = "" }
WordHunterWoW_QuestEN[13010] = { title = "Krolmir, Hammer of Storms", description = "One task remains before I can reclaim my home at the Terrace of the Makers.\n\nKrolmir must be found.\n\nOn that fateful day, I threw it to the earth with all the power and rage I possessed. A mighty explosion followed.\n\nI've thought it lost for these many years, but now I must be certain.\n\nReturn to King Jokkum and discover what, if anything, he knows of my hammer's fate.", objectives = "" }
WordHunterWoW_QuestEN[13011] = { title = "Culling Jorcuttar", description = "The jormungar are a nuisance best dealt with quickly. If given any quarter, they breed like hares and spread like fire.\n\nThey have appeared southwest of here, in the Hibernal Cavern. If their spawnmother is not slain soon, they will gain a foothold in our region.\n\nShe cannot refuse food. Take this knife and get the flank of a bear corpse from their cave. Place it near her crater and kill her as she feeds.", objectives = "" }
WordHunterWoW_QuestEN[13012] = { title = "Sardis the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13013] = { title = "Beldak the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13014] = { title = "Morthie the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13015] = { title = "Fargal the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13016] = { title = "Northal the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13017] = { title = "Jarten the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13018] = { title = "Sandrene the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13019] = { title = "Thoim the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13020] = { title = "Stonebeard the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13021] = { title = "Igasho the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13022] = { title = "Nurgen the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13023] = { title = "Kilias the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13024] = { title = "Wanikaya the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13025] = { title = "Lunaro the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13026] = { title = "Bluewolf the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13027] = { title = "Tauros the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13028] = { title = "Graymane the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13029] = { title = "Pamuya the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13030] = { title = "Whurain the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13031] = { title = "Skywarden the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13032] = { title = "Muraco the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13033] = { title = "Arp the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13034] = { title = "The Witness and the Hero", description = "When I began my travels in Northrend, I visited the Borean Tundra and met the taunka for the first time. There, Wind Tamer Barah told me the tale of Stormhoof and his battle against the North Wind, their people's ancient enemy.\n\nI set out for the Storm Peaks to learn more of this hero, but strangely, the people of Tunka'lo seem to know nothing of him.\n\nPerhaps the camp's own records will give us greater insight. Find and read the history scrolls kept throughout the camp, then tell me what you learned.", objectives = "" }
WordHunterWoW_QuestEN[13035] = { title = "Loken's Lackeys", description = "The attack on the Terrace of the Makers was not a half-hearted move on my brother's behalf.  He sent a legion of iron dwarves and some of his most powerful lieutenants.\n\nUse the Horn of the Peaks to call the earthen to your side and defeat Loken's servants.\n\nYou'll find the giant, Eisenfaust, inside the Hall of the Shaper to the north.  You'll find the others deeper inside the Terrace of the Makers, beyond the stairs to the northwest.", objectives = "" }
WordHunterWoW_QuestEN[13036] = { title = "Honor Above All Else", description = "Long has been the path to our salvation, young {class}. We have fought across continents, worlds even, to reach this point. Now we face our greatest challenge: the destruction of the Lich King and his Scourge.\n\nAlas, we fight this battle divided. The Horde and Alliance are in the throes of war and will lend us no support. We must remain unyielding in our cause! For what choice have we to do otherwise?\n\nDo you join the cause? Lend us your strength, {class}! My commander, Entari, awaits you at his post.", objectives = "" }
WordHunterWoW_QuestEN[13037] = { title = "Memories of Stormhoof", description = "When the bronze dragonflight gifted me with immortality and set me on the path of the witness, Nozdormu entrusted me with the Lorehammer.\n\nThe hammer's reaction to your findings means that time has gone awry here and it is our duty to restore the true timeline.\n\nWe must find it. To the northwest is Frostfloe Deep, ancient burial cave of the warriors of Tunka'lo. Seek out the spirit of Chieftain Swiftspear, Stormhoof's brother. Ask him what he remembers of his brother's battle against the North Wind.", objectives = "" }
WordHunterWoW_QuestEN[13038] = { title = "Distortions in Time", description = "This, the tomb of Tunka'lo's warriors, is supposed to be a serene place, free from the terror of the elements.\n\nFrostfloe Deep has been invaded by a strange force, one that disturbs the spirits of the fallen and blurs my memories of my own life.\n\nIt's as though our deeds and memories are being erased from history.\n\nIn life, this totem was a symbol of my authority. It is the last true link I have to this world. Take it, use it to restore calm to the tomb, and then return it to Camp Tunka'lo.", objectives = "" }
WordHunterWoW_QuestEN[13039] = { title = "Defending The Vanguard", description = "We can't keep this pace up, lad. Once the breach was blown, the floodgates opened up. The Scourge have been pourin' through ever since with no end in sight!\n\nWe need every able bodied man and woman to help keep the tide of evil at bay. Get out there and do yer share, friend. Kill as many of those monsters as ye can!", objectives = "" }
WordHunterWoW_QuestEN[13040] = { title = "Curing The Incurable", description = "The number of injured soldiers rises with each passing day. They are being stricken by some type of toxin that we have never before seen. Whatever it is that these Nerubians hold within their venom glands is lethal and incurable! So far we've only been able to slow down the poison flowing through the victim's bodies. We must devise a cure!\n\nVenture northwest to the valley outside of the Vanguard and slay the Forgotten Depths Nerubians. Recover their venom glands and bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[13041] = { title = "Finish the Shipment", description = "I'm glad you showed up!   A shipment of Glowing Ivory Figurines needs to go out to Undermine right now, and I am still short a Chalcedony to complete an eye for the last one.\n\nBring me one and a Dalaran Jeweler's token will be yours.", objectives = "" }
WordHunterWoW_QuestEN[13042] = { title = "Deep in the Bowels of The Underhalls", description = "Deep in the bowels of The Underhalls to the northeast, a mad scientist known as Dr. Terrible is up to something befitting his name.\n\nThe doctor has been given dispensation by the Lich King to perform experiments upon the vargul -- the vrykul who fall in battle and are found unworthy, and then turned into Scourge.\n\nWe must put an end to his work, but my auguries have been unable to find him. He does, however, have an assistant.\n\nBeat the information out of his apprentice, and then dispose of the body.", objectives = "" }
WordHunterWoW_QuestEN[13043] = { title = "The Sum is Greater than the Parts", description = "Opening the tome, you notice all manner of disgusting illustrations concerning the construction of what the doctor refers to as \"the ultimate weapon\"!\n\nClearly the prototype, Nergeld, is the massive flesh giant standing still at the end of the nearby Hall of Horrors.\n\nIf an army of those things were to be constructed, then it would mean doom. The only way to ensure that doesn't happen is to slay Dr. Terrible!\n\nPerhaps if you were to take control of the construct, the doctor would reveal himself?", objectives = "" }
WordHunterWoW_QuestEN[13044] = { title = "If There Are Survivors...", description = "Across the Valley of Echoes, west of here, and through the Breach, is the first Scourge encampment in Icecrown known as Scourgeholme. We fought a good fight at Scourgeholme and killed many Scourge, but in the end we were forced to retreat. Many soldiers were left behind - their fate unknown.\n\nIf there are survivors, we must attempt a rescue. Directly down this southeastern path is Penumbrius, ally of the bronze dragonflight and caretaker of the proto-brood. Seek him out and ask for his assistance.", objectives = "" }
WordHunterWoW_QuestEN[13045] = { title = "Into The Wild Green Yonder", description = "We will do all that we can to assist you, {name}. The proto-brood have volunteered to fly you across the Breach and into Scourgeholme. Rescue any captured Argent Crusaders that you find. Return them immediately to the Vanguard Infirmary, located at the center of this base.\n\nChoose one of the Argent Skytalons in the pen behind me and go!\n\nScourgeholme is located northwest, across the Valley of Echoes, through the great Breach.", objectives = "" }
WordHunterWoW_QuestEN[13046] = { title = "Feeding Arngrim", description = "Arngrim's hunger was legendary.\n\nEven in death, his expression is one of famished yearning. You find that just looking at him is making your stomach growl.\n\nIt is said that throughout his life he was never truly sated, and that there was absolutely nothing he wouldn't eat. You wonder to yourself if there might be a way to feed the old king.\n\nNo sooner does the thought enter your mind than one of the massive frozen teeth falls from Arngrim's head, bounces off of his beard and lands in your hand.", objectives = "" }
WordHunterWoW_QuestEN[13047] = { title = "The Reckoning", description = "Loken killed my wife, turned my followers and me against each other.  He took away everything I had, but today... that changes.\n\nToday we reclaim our sacred grounds.  Today... Loken dies.\n\nMeet me on the bridge near the Temple of Wisdom, just southwest of Ulduar.  I will finish this one way or the other.\n\nI need you there as a witness.  You will not aid me -- this is personal.\n\nAfter it's done, send word to Jokkum, King of the Frost Giants.  He's a good friend and will know what to do.", objectives = "" }
WordHunterWoW_QuestEN[13048] = { title = "Where Time Went Wrong", description = "The Lorehammer can help us correct the damage to the timeline, but only if we can discover where the history was originally corrupted.\n\nFrom Chieftain Swiftspear and your findings at Frostfloe Deep, we know that the change happened around the time of Stormhoof's death.\n\nNow, you must go to the Howling Hollow, north of the camp, and inspect the gravesites the North Wind's minions have already destroyed. The Lorehammer will react to artifacts from Stormhoof's era and attune itself to the proper time.", objectives = "" }
WordHunterWoW_QuestEN[13049] = { title = "The Hero's Arms", description = "Not all of the camp's records have yet been corrupted. My staff has helped me to find those records which reflect the true timeline.\n\nThey agree that Stormhoof was given a burial of honor among the village elders on the bottom level of the Howling Hollow, to the north.\n\nMost of the graves there have already been destroyed, their contents taken as trophies by the North Wind's subjects. Go to the hollow and see if you can recover Stormhoof's spear and armor from the scions of storm who have claimed them.", objectives = "" }
WordHunterWoW_QuestEN[13050] = { title = "Veranus", description = "If I'm to launch an attack against my brother's army, I'm going to need some way to get around.\n\nI released my riding drake back into the wild years ago.  Veranus was magnificent.  The leader of her own brood -- to whom she has now returned.\n\nFinding her will be hard, but perhaps there's a way.  She keeps her old empty nest out of pure pride.  She's a broodmother in name only, for she is beyond the age of breeding.\n\nBring me small eggs from the other nests near Brunnhildar.  I think I've an idea.", objectives = "" }
WordHunterWoW_QuestEN[13051] = { title = "Territorial Trespass", description = "Veranus is proud like no other beast I've known.  She still keeps her old nest and makes sure none of the younger proto-drakes takes it over.\n\nTake the eggs you've collected and place them on her nest.  You'll find it atop a small peak, directly southeast of here.\n\nI should be able to get control of her before she kills you in a fit of rage.  Hopefully.", objectives = "" }
WordHunterWoW_QuestEN[13054] = { title = "The Missing Tracker", description = "I can't in good conscience send you to the worg cave without warning you that the previous person we sent there hasn't returned.\n\nWe're prepared for the worst, but perhaps there's a chance that he's alive.  We'd appreciate it if you helped him return -- Tracker Val'zij is one of the only hunters we have.", objectives = "" }
WordHunterWoW_QuestEN[13055] = { title = "Cave Medicine", description = "It's good to see a friendly face.  Might be the last one I see.\n\nOne of those jormungar stung me with some sort of toxin before I managed to get away.  I can feel my whole body getting numb, mon.\n\nI'm going to need a toxin gland to make an antidote.  I will also need some of the cave mushrooms that grow here... they'll slow the toxin down.\n\nHurry, please.  I don't have much time.  ", objectives = "" }
WordHunterWoW_QuestEN[13056] = { title = "There's Always Time for Revenge", description = "I should manage for now, {name}.  There is one favor I'd like to ask, though.\n\nI would never had fallen to one of these worms, but my wind serpent, Heesha, was killed by the meanest worg I've seen in some time.\n\nDon't worry about me now, I'll feel better when that worg is breathing no more.  You should find him deeper in the cave.", objectives = "" }
WordHunterWoW_QuestEN[13057] = { title = "The Terrace of the Makers", description = "It is time, {name}.  I am prepared to face Loken now.\n\nLet us make our way to the Terrace of the Makers and face my brother's forces.  The fool will regret ever crossing me.", objectives = "" }
WordHunterWoW_QuestEN[13058] = { title = "Changing the Wind's Course", description = "At last, we have all that we need to right the wrongs of the North Wind and its followers. You have attuned the Lorehammer to Stormhoof's time and his persona.\n\nTake the hammer again, head to the Temple of Life in the plains to the northwest. Use the hammer to assume the role of Stormhoof. Face the North Wind as Stormhoof, but realize that for the timeline to be restored, Stormhoof must die as the North Wind weakens.\n\nThen, you must find and use the Horn of Elemental Fury to destroy the North Wind.", objectives = "" }
WordHunterWoW_QuestEN[13059] = { title = "Revenge for the Vargul", description = "I've been praying to The Lady of the Sword for one to come and strike down my enemy. Thane Illskar must pay for what he did to me!\n\nI was the champion of Thane Ufrang the Mighty. During my fight for ascendance in Valhalas, Illskar sabotaged me with dark magic, causing me to lose and be reduced to this.\n\nThe thane and his champions can be found below in The Circle of Suffering. Challenge him on my behalf. Defeat him.\n\nMake him know the suffering that I know!", objectives = "" }
WordHunterWoW_QuestEN[13060] = { title = "When All Else Fails", description = "So...  so I don't think we're going to be getting a good foothold in those mountains.\n\nTrust me, I'm not one to give up easily... but between freezing engines, nasty vrykul women, territorial dragon want-to-bes and the half a dozen other nasties settled in the area, this just ain't happening.\n\nDon't let that dissuade you though! Just because we can't get a foothold doesn't mean we won't get you there... one-way trips are pretty simple when you get down to it.\n\n<Ricket nods at some nearby rockets.>", objectives = "" }
WordHunterWoW_QuestEN[13061] = { title = "Prepare for Glory", description = "This is it then.  I'll take care of your bear now, you won't be needing her.  The great Drakkensryd will be your next challenge.\n\nSay goodbye to your friends and leave your affairs in order, for you will return victorious... or you won't return at all.", objectives = "" }
WordHunterWoW_QuestEN[13062] = { title = "Lok'lira's Parting Gift", description = "You've been a great ally, {name}.  Now comes your true test.  You will need skill, courage and a little luck.\n\n<Lok'lira attaches a thin strand of hair to yours.>\n\nYou cannot fail now sister.  Speak to Gretta the Arbiter.  She'll see you on your way.", objectives = "" }
WordHunterWoW_QuestEN[13063] = { title = "Deemed Worthy", description = "You have succeeded where many have failed, sister. Whether it be by strength and courage or mere luck remains to be seen.\n\nGo back to the village and seek out Astrid Bjornrittar. Tell her of your accomplishments. But be warned. She is not easily impressed.", objectives = "" }
WordHunterWoW_QuestEN[13064] = { title = "Sibling Rivalry", description = "Sif? Is it truly you?\n\nNo? A {race}? But for a moment....\n\nEnough of this! The visions of my Sif have tormented me for far too long. It is time for me to avenge her, and to bring honor to her memory.\n\nMy brother must pay!", objectives = "" }
WordHunterWoW_QuestEN[13065] = { title = "Ohanzee the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13066] = { title = "Yurauk the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13067] = { title = "Chogan'gada the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[13068] = { title = "A Tale of Valor", description = "Perhaps you've heard the praises for our missing hero?\n\nCrusader Bridenbrad was in the Broken Front aiding the attack against the Scourge when the undead army came down upon them. The many men of that allied force scattered, but Bridenbrad alone returned and dragged more than a dozen men to safety, one by one through the carnage.\n\n{class}, he has not returned since. He was spotted heading to the far northeast, towards the Silent Vigil. Bring him back to me that I might honor him for his valor.", objectives = "" }
WordHunterWoW_QuestEN[13069] = { title = "Shoot 'Em Up", description = "Jotunheim has aerial defenses, both in terms of proto-drake riders and harpoon guns. They've concentrated these on their northern and western facings where they are most vulnerable.\n\nLet's use their defenses against them!\n\n<The Leaper pierces you with his single eye and cackles maniacally.>\n\nTake control of a harpoon gun on the platforms that overhang the cliffs on either side of Valhalas to the southwest. Take out the proto-drakes and their riders. Shoot 'em up!", objectives = "" }
WordHunterWoW_QuestEN[13070] = { title = "A Cold Front Approaches", description = "The chill of death stirs in the west, threatening to freeze our hearts and souls to this wasteland and bind us to its dark master. We will stand and we will fight!\n\nThe preparations have begun. Report to Siegemaster Fezzik at the front gate for your assignment.", objectives = "" }
WordHunterWoW_QuestEN[13071] = { title = "Vile Like Fire!", description = "Vile like fire! Vile like proto-drakes!\n\n<The abomination claps its hands excitedly.>\n\nLittle {name} go to Jotunheim and steal a pretty proto-drake in Njorndar Village. Make proto-drake make pretty fires on Jotunheim buildings!", objectives = "" }
WordHunterWoW_QuestEN[13072] = { title = "A Hero Remains", description = "I know why you've come... they've sent you to bring me back, but that cannot happen. I carry the plague of undeath, {class}, and I'll not share my fate with those near me. No, I shall stay here.\n\nMy only regret lies in what I may become when death grips me. I do not fear death itself, but I loathe to consider serving the traitor, Arthas.\n\nLeave me... and see to it that no one else comes looking. You would do me a great disservice if you were to expose anyone to the plague that I carry.", objectives = "" }
WordHunterWoW_QuestEN[13073] = { title = "The Keeper's Favor", description = "There are those of this world that tap into power unrestricted by the bounds of our mortal frames - powers of restoration, powers of life, and powers of light.  And Bridenbrad, this is no ordinary man... his valor and devotion shine through. We can only hope that one of these beings will intervene and bring this hero back from a fate worse than death.\n\nGo now and speak to Arch Druid Lilliandra in the Argent Vanguard... request passage to Moonglade and seek the aid of Keeper Remulos.", objectives = "" }
WordHunterWoW_QuestEN[13074] = { title = "Hope Within the Emerald Nightmare", description = "What we need exists only in the emerald dream... acorns that are infused with a powerful restorative magic. Many places in this sacred glade are closely tied with the dream, and my shrine is among them.\n\nI will send you into the dream to recover some of these acorns. Be prepared though {class}, for this method of entering the dream is dangerous, and it is very likely you will be beset by nightmares.\n\nRecover a few acorns quickly, and then depart from my shrine or pinch yourself to return to our world.", objectives = "" }
WordHunterWoW_QuestEN[13075] = { title = "The Boon of Remulos", description = "I shall open a portal to take you back to the druid that brought you here. You and your crusader have my well wishes. I hope that this acorn is able to purify your crusader and save him from the wretched fate of the plague.\n\nFarewell, {race}.", objectives = "" }
WordHunterWoW_QuestEN[13076] = { title = "Time Yet Remains", description = "I feel refreshed... renewed... but the plague still grips me. Not to worry, I am still eternally grateful that you went to such lengths for me, a complete stranger. If nothing else, you've bought me a few more precious hours not plaguing the world as a hideous undead.\n\nThank you, {class}. Please extend my thanks to Tirion as well, and let him know that it has been an honor to serve beside him.", objectives = "" }
WordHunterWoW_QuestEN[13077] = { title = "The Touch of an Aspect", description = "The dragon-queen, Alexstrasza, possesses magics over all life. In the past, she has used great fire to incinerate undead and rebirth fresh new life in their place. Perhaps her powers might be able to save our Bridenbrad as well.\n\nAlexstrasza makes her home at Wyrmrest Temple in Dragonblight - please go to her and humbly request her aid on my behalf.", objectives = "" }
WordHunterWoW_QuestEN[13078] = { title = "Dahlia's Tears", description = "In this dark time, I'll not be the one to abandon a champion of the Light.\n\nWe will need something sacred for this to have a hope of saving your Bridenbrad... a remnant of a devout being that fell victim to this very same plague.\n\nGo now to the sacred soil of the passages outside my Ruby Dragonshrine where the battle is joined. As my Ruby Keepers fly down and set flame to the ground beneath undead feet, you will witness new life grow forth. Among that life are Dahlia's Tears - bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[13079] = { title = "The Boon of Alexstrasza", description = "You must understand, young {race}, that cleansing the body in favor of life anew is something well within my grasp... removing the plague of undeath without affecting the body, however, is beyond the scope of the powers that I control.\n\nIf this Bridenbrad is the beacon of light that you profess him to be, perhaps he will endure such a cleansing and thrive, but I cannot state with confidence that this is the salvation that you seek. Take it and go with all of my blessings.", objectives = "" }
WordHunterWoW_QuestEN[13080] = { title = "Hope Yet Remains", description = "<Bridenbrad raises a hand to you as he catches his breath.>\n\nIt was nearly as painful as it looked, but it was as if I could feel some of the corruption being burnt away from within my body. It seems the plague is not so readily bested though.\n\n{class}, thank you for everything that you have done. Your selfless actions have renewed my hope that there is yet great good left within this world - I can depart without fear that darkness will prevail in my absence.\n\nGo now, go with no regrets.", objectives = "" }
WordHunterWoW_QuestEN[13081] = { title = "The Will of the Naaru", description = "I appreciate everything that you have done for us, {name}. I have one last errand for you... one last gleaming hope for a paladin who deserves any salvation that we can extend.\n\nGo now to Shattrath and speak to the naaru, A'dal. He has long been a beacon of light and powerful ally to devout paladins. Impart Bridenbrad's story and seek any aid that he might have to offer.\n\nI cannot impress how important it is that you move quickly - I fear our crusader does not have much more time in this world.", objectives = "" }
WordHunterWoW_QuestEN[13082] = { title = "The Boon of A'dal", description = "I am pleased that you have come to me, {name}. I know of Crusader Bridenbrad, and of your travels in hope of saving him. Bridenbrad's valor has sparked remarkable selflessness in you, and this is a miracle unto itself.\n\nThe Light will take care of its own. I will extend my blessing to Bridenbrad and he shall not endure the corruption of undeath. I shall return you to Dalaran, and you shall return to him. Know that I remain with you.", objectives = "" }
WordHunterWoW_QuestEN[13083] = { title = "Light Within the Darkness", description = "<Crusader Bridenbrad's tabard rests in the bottom of the chest, shifting slightly as the howling wind finds its way in.>\n\nTirion will desire this last remnant of the great crusader.", objectives = "" }
WordHunterWoW_QuestEN[13084] = { title = "Vandalizing Jotunheim", description = "Let us see if we can further weaken the resolve of the vrykul, {name}.\n\nEach day I wish you to travel to Jotunheim and put their banners to the torch. It may seem a trivial thing, but to see their ancestral home vandalized on a daily basis will demoralize them more than any physical punishment you can inflict.\n\nAt least... it can't hurt.", objectives = "" }
WordHunterWoW_QuestEN[13085] = { title = "Vaelen Has Returned", description = "I just saw that incompetent fool, Vaelen the Flayed, sneak into the vault building.\n\nGo see to it that he rectifies his mistake and returns my death knights to me!", objectives = "" }
WordHunterWoW_QuestEN[13086] = { title = "The Last Line Of Defense", description = "I've triggered the base's defenses, {class}! Atop each of the Vanguard's four towers is a retractable Argent Crusade cannon, blessed by Father Gustav himself. You'll need to fly up to one of those towers and man a cannon. Use it to destroy the Scourge onslaught that the Lich King has deployed.\n\nJust one warning, the Scourge will undoubtedly send their frost wyrms to lay siege to the towers. Shoot them out of the sky! If they destroy the walls and towers of this base, we're done for!", objectives = "" }
WordHunterWoW_QuestEN[13087] = { title = "Northern Cooking", description = "So what are ya doin' if you dinna have any stew for me.   I got me a HUNGER!   At least bring me some chilled meat so I kin cook me own stew!   If ya do, I kin give ya the recipe so you kin make it for yourself.   NOW GO GET ME SOME MEAT!", objectives = "" }
WordHunterWoW_QuestEN[13088] = { title = "Northern Cooking", description = "We got a lot of new recruits here and these lads are hungry!  If you could go out and get me some chilled meat for stew, I could teach you how to make it for yourself.", objectives = "" }
WordHunterWoW_QuestEN[13089] = { title = "Northern Cooking", description = "Nothing like a stew made from the living to warm your bones.   Bring me some of the chilled meat that can be found on the wretched beasts of this place, and I shall teach you to make a warm stew.", objectives = "" }
WordHunterWoW_QuestEN[13090] = { title = "Northern Cooking", description = "The warriors of the Warsong Offensive need food in their bellies to keep their strength up.   If you could bring some chilled meats from the Rhinos or other beasts, I could make them some stew.   I would be willing to teach you the recipe if you were willing.", objectives = "" }
WordHunterWoW_QuestEN[13091] = { title = "The Art of Being a Water Terror", description = "The water lock outside my cave is teeming with elementals that the vrykul magi have yet to tame. I am going to teach you a trick for possessing these creatures for a short time, and you will use them to wreak havoc upon Jotunheim!\n\n<The banshee-infested vrykul draws magic in the air and touches a large finger to your forehead.>\n\nGo now and open the gate to the lock. A water terror will rush out and you will possess it to destroy our enemies!", objectives = "" }
WordHunterWoW_QuestEN[13092] = { title = "Reading the Bones", description = "One of the benefits of possessing this creature is that I have access to all of her powers. As a bone witch and rune reader, she has the power to throw the bones and determine one's fate.\n\n<The Bone Witch smirks.>\n\nLucky for you and I that I have it within my power to influence those readings.\n\nBring me the bones of the vrykul that you kill here in Jotunheim and I will toss them to allow you to determine your own fate.", objectives = "" }
WordHunterWoW_QuestEN[13094] = { title = "Have They No Shame?", description = "Archmage Berinand loaned me his research on the Arcanomicron, some sort of map that Malygos is trying to assemble.\n\nI made the mistake of discussing it with a group of Horde adventurers and now it's gone!\n\nIt must have been them. Please, recover the book.", objectives = "" }
WordHunterWoW_QuestEN[13095] = { title = "Have They No Shame?", description = "Archmage Berinand loaned me his research on the Arcanomicron, some sort of map that Malygos is trying to assemble.\n\nI made the mistake of discussing it with a group of Alliance adventurers and now it's gone!\n\nIt must have been them. Please, recover the book.", objectives = "" }
WordHunterWoW_QuestEN[13100] = { title = "Infused Mushroom Meatloaf", description = "We have an important order that needs to go out!  Orton Bennet in Curiosities & Moore needs a mushroom meatloaf.\n\nGet some infused mushrooms found in the Dalaran sewers, chilled meat, and cook them in this meatloaf pan.  When you're done, deliver the cooked meatloaf to Orton.", objectives = "" }
WordHunterWoW_QuestEN[13101] = { title = "Convention at the Legerdemain", description = "Arille Azuregaze at the Legerdemain Lounge has a convention coming in and needs a feast pronto!\n\nYou need to provide some Northern Stew and a Jug of Wine from the cheese shop \"One More Glass\" in central Dalaran.  The owner of the cheese shop owes me the wine and you should find it somewhere around the shop.\n\nBring the wine and stews to Arille.", objectives = "" }
WordHunterWoW_QuestEN[13102] = { title = "Sewer Stew", description = "Ajay Green the innkeeper in the Dalaran sewers needs a vegetable stew for his customers as they are running low on food down there.\n\nCollect 4 Crystalsong Carrots from the Crystalsong Forest and cook them together with 4 Chilled Meat.\n\n You can get to the Crystalsong Forest from the portal chamber in the eastern corner of Runeweaver Square.\n\nOnce the vegetable stew is ready, bring it to Ajay.", objectives = "" }
WordHunterWoW_QuestEN[13103] = { title = "Cheese for Glowergold", description = "Ranid Glowergold in the Leatherworkers shop in Dalaran has had a sudden craving for wine and cheese.\n\nCollect cheese which is on the shelf at \"One More Glass\" in central Dalaran and half full wine glasses found on tables all over the city.  Pour the wine together into a bottle and serve it with the cheese to Ranid.\n\nWe don't think he will know the difference.", objectives = "" }
WordHunterWoW_QuestEN[13104] = { title = "Once More Unto The Breach, Hero", description = "The Vanguard is secure, ally. We have reclaimed the Valley of Echoes and taken down the web walls blocking entry to the Breach. Now is the time to strike at Scourgeholme and establish our presence inside Icecrown. The battlefront moves on!\n\nI have asked the Ebon Watcher for his assistance with our assault upon Scourgeholme. His intimate knowledge of the Scourge will be invaluable in our effort.\n\nGo now and report to him at the tent outside of the Breach, northwest of here.", objectives = "" }
WordHunterWoW_QuestEN[13105] = { title = "Once More Unto The Breach, Hero", description = "The Vanguard is secure, ally. We have reclaimed the Valley of Echoes and taken down the web walls blocking entry to the Breach. Now is the time to strike at Scourgeholme and establish our presence inside Icecrown. The battlefront moves on!\n\nI have asked the Ebon Watcher for his assistance with our assault upon Scourgeholme. His intimate knowledge of the Scourge will be invaluable in our effort.\n\nGo now and report to him at the tent outside of the Breach, northwest of here.", objectives = "" }
WordHunterWoW_QuestEN[13106] = { title = "Blackwatch", description = "The Scourge has a large facility called the Fleshwerks, dedicated to producing abominations and flesh giants. If we can shut it down, we can deprive the Lich King of a large component of his armies.\n\nI've sent Darkrider Arly to the area. She has a small base, Blackwatch, on a ridge overlooking the Fleshwerks and to the west of Corp'rethar. I'm told the Argent Crusade is sending someone to coordinate their efforts there, but the darkrider will know what to do. Find and assist her.", objectives = "" }
WordHunterWoW_QuestEN[13107] = { title = "Mustard Dogs!", description = "Archmage Pentarus likes to watch the occasional game of battle ball and is preparing to go, but needs food for the trip.\n\nYou need to fill his picnic basket with 4 rhino dogs that you cook and then 4 wild mustard that are found in grassy areas of the city.\n\nBring him his picnic basket so he can be ready to go see the big game.", objectives = "" }
WordHunterWoW_QuestEN[13110] = { title = "The Restless Dead", description = "Not all of our soldiers made it out of Scourgeholme. Many were slain and turned into twisted reflections of their former selves. Such is the way of the Scourge. For those damned souls, there is no eternal peace. We must provide their souls rest.\n\nTravel through the Breach into Scourgeholme and slay the skeletal reanimated crusaders. Sprinkle this holy water on their bones so that their spirits may be freed.", objectives = "" }
WordHunterWoW_QuestEN[13112] = { title = "Infused Mushroom Meatloaf", description = "Orton Bennet in Curiosities & Moore be needin' a mushroom meatloaf.\n\nGet ya some infused mushrooms found in the Dalaran sewers, chilled meat, and cook 'em in the meatloaf pan.  When ye be done, bring that meatloaf to Orton.\n\nIf only de council would let me serve me gnome specialty, I would show dem a real treat!", objectives = "" }
WordHunterWoW_QuestEN[13113] = { title = "Convention at the Legerdemain", description = "Can you believe da horde has outlawed cannibalism...it just ain't right I tell ya!  I guess I should keep me mind on me work when we gots an order to fill.\n\nArille Azuregaze at the Legerdemain Lounge has many a guest a'comin to his place, mon.  You gots to be providin' some Northern Stew and a Jug of Wine from the cheese shop in central Dalaran.\n\nBring the wine and stew to Arille.", objectives = "" }
WordHunterWoW_QuestEN[13114] = { title = "Sewer Stew", description = "We be havin' another order to fill.  Da innkeeper in da Dalaran sewers needs a vegetable stew as his customers dey don't have so much to eat, mon.\n\nHe asked for a vegetable stew as he didn't appreciate da gnome that was in the last stew I sent.  Get 4 Crystalsong Carrots from the Crystalsong Forest and cook them together with 4 Chilled Meat and bring it to Ajay.\n\nYou can be gettin' to da Forest from da portal chamber in da eastern corner of Runeweaver Square. ", objectives = "" }
WordHunterWoW_QuestEN[13115] = { title = "Cheese for Glowergold", description = "Ranid Glowergold in da Leatherworkers shop be havin' a need for wine and cheese.  Why he don't want some tasty gnome is beyond me.\n\nCollect da cheese from da cheese shop in central Dalaran and da half full wine glasses found on tables around da city.  Bring da wine and serve it with the cheese to Ranid.\n\nYou can call da wine a Wine Medley, mon'.", objectives = "" }
WordHunterWoW_QuestEN[13116] = { title = "Mustard Dogs!", description = "Da Archmage Pentarus likes to be watchin' his crazy battle ball game, but he be needin' some food for da game.\n\nYou be needin' to fill his picnic basket with 4 cooked rhino dogs and then 4 wild mustard that are found in da grassy corners of de city.\n\nFill up his basket with the mustard dog goodies, mon'.", objectives = "" }
WordHunterWoW_QuestEN[13117] = { title = "Where Are They Coming From?", description = "The Lich King's tireless minions labor away night and day to assemble scores of abominations and flesh giants down there in the Fleshwerks.\n\nYet, that is not enough. More and more skeletal constructors keep appearing to increase the pace of work.\n\nIf we do not discover where they're coming from and how they're able to work so quickly, we'll be overrun before we can act in force. Search to the southeast and see if you can find the source of these skeletons.", objectives = "" }
WordHunterWoW_QuestEN[13118] = { title = "The Purging Of Scourgeholme", description = "The Scourge have sent their armies at the Argent Crusade and have been repelled. What they do now is called a 'slash and burn.' All prisoners that they hold at Scourgeholme will be executed and raised as servants of the Lich King.\n\nUndoubtedly the Argent Crusade will request that you give their soldiers a proper farewell. I'll ask no such thing of you. To succeed we must kill Scourge indiscriminately.\n\nVenture to Scourgeholme, northwest through the Breach, and lay waste to all that stand in your way.", objectives = "" }
WordHunterWoW_QuestEN[13119] = { title = "Destroying the Altars", description = "So they're summoning in their workers and warriors at those altars?\n\nThey'll need to be the first thing to go. The master summoner should have a staff which allows him to activate the portal. If you kill the master summoner and take the staff, you can use it to overload the summoning portal and destroy its altar.\n\nDo this at all four of the altars and return to me once they've been destroyed.", objectives = "" }
WordHunterWoW_QuestEN[13120] = { title = "Death's Gaze", description = "The Fleshwerks is a vast operation, and it will be difficult to keep an eye on all that transpires there. Fortunately, I have a plan.\n\n<Arly produces an orb from the folds of her cloak and shows it to you.>\n\nThis is a death's gaze orb. With it, we can observe the Scourge's actions and decide how best to strike.\n\nPlace these orbs on the stands at three crucial areas -- the abomination lab and the flesh giant lab to the southwest, along with the area surrounding the green cauldron far to the west.", objectives = "" }
WordHunterWoW_QuestEN[13121] = { title = "Through the Eye", description = "We must use the Lich King's tools against him if we are to decide our next step.\n\nOver the mountain to the southwest lies Kul'galar Keep. Within it reside the oracles of Jotunheim who receive orders from their master and scry upon others through the Eye of the Lich King.\n\nIt is the eye that you must fight your way to. While it cannot be used to pierce the veil within Icecrown Citadel, you should be able to use it to discern something of value so that we will know how best to proceed.", objectives = "" }
WordHunterWoW_QuestEN[13122] = { title = "The Scourgestone", description = "A Scourgestone is an item given to all Scourge upon birth or creation. It provides certain benefits to the holder, but more importantly it allows Scourge leaders visibility into the location and movement of all of their units.\n\nWith enough Scourgestones, I might be able to track the movement of other Scourge units across Icecrown.\n\nAs you slaughter Scourge in Scourgeholme, gather all of the Scourgestones that you find. Return to me when your bags are full.", objectives = "" }
WordHunterWoW_QuestEN[13124] = { title = "The Struggle Persists", description = "Malygos and his underlings grow stronger in power with each passing day. And now, our latest assault team has been captured and is being held in the Oculus.\n\nWe must attempt a rescue! Belgaristrasz and his companions are invaluable to our cause.", objectives = "" }
WordHunterWoW_QuestEN[13125] = { title = "The Air Stands Still", description = "You must defeat the lords of Scourgeholme if this place is to be free of the Scourge's grasp.\n\nSalranax the Flesh Render lords over the temple on the first tier of Scourgeholme. Nearby Salranax you'll find High Priest Yath'amon preaching at the spirit tower on the second tier. Underking Talonox holds court at the Pit of Fiends, up the high road.\n\nThese are formidable opponents and must be approached with caution. Use this war horn should you require aid. The death knights of Acherus will come.", objectives = "" }
WordHunterWoW_QuestEN[13126] = { title = "A Unified Front", description = "From here, it will take our combined efforts to proceed.\n\nAbove us, Varos hides behind an impenetrable shield. To reach him, you must defeat the Centrifuge Constructs that power his shield.\n\nWe can each provide you with drakes from our respective flights to help you reveal him.", objectives = "" }
WordHunterWoW_QuestEN[13127] = { title = "Mage-Lord Urom", description = "Only one obstacle stands between us and our ultimate goal here. His name is Urom.\n\nHe guards the third ring above us. Beware his powerful conjurings, friend.\n\nBring him down. Make him pay for his treacherous allegiance to the enemy!", objectives = "" }
WordHunterWoW_QuestEN[13128] = { title = "A Wing and a Prayer", description = "The time has come to face Eregos.\n\nHe draws strength from the energies he is charged with defending - sipping from the well of the great aspect Malygos.\n\nHowever, defeating the Mage-Lord has allowed us to unlock the full power of our drakes. Use them wisely and Eregos shall surely fall.", objectives = "" }
WordHunterWoW_QuestEN[13129] = { title = "Head Games", description = "<Kurzel rips a long strip of material from her blouse and hands it to you.>\n\nHere, {race}, take this. Dip it in the remains of Novos the Summoner.\n\nWe're going to figure out what makes the Scourge leaders tick.", objectives = "" }
WordHunterWoW_QuestEN[13130] = { title = "The Stone That Started A Revolution", description = "You may look at Scourgeholme now and see a rancid pit of decay, but one day it will be a place of glory and honor. Highlord Fordring has deemed it \"Justice Keep.\"\n\nAlas, even an impregnable fortress like Icecrown Citadel began with but a single stone. So begins our search for the stone to start a revolution.\n\nTravel to Crystalsong, south of here, and seek out the Unbound Thicket in the east. Once there gather crystalline heartwood from the thicket floor and elven masonry from the Ruins of Shandaral.", objectives = "" }
WordHunterWoW_QuestEN[13131] = { title = "Junk in My Trunk", description = "Just look at it! Me trunk never been so empty.\n\nMe mates jumped at the sight o' all that booty, and now look at 'em! Rattlin' bones, they be!\n\nSay, thar be plenty o' loot farther in, an' not the cursed kind I'll wager.\n\nFetch it fer me an' I'll be rewardin' ya handsomely, matey.\n", objectives = "" }
WordHunterWoW_QuestEN[13132] = { title = "Vengeance Be Mine!", description = "Only luck spared me from the same fate as me mates.\n\nIn the scurry I got knocked down - was a wee bit tipsy to begin with. Looked up ta see the first of 'em turn.\n\nThere was a big ol' fella watchin' with a whole mess o' guards. They were chantin' Ymiron... maybe killin' him will free me mates?", objectives = "" }
WordHunterWoW_QuestEN[13133] = { title = "Find the Ancient Hero", description = "Quickly, {name}, head southwest to the Halls of the Ancestors!\n\nWithin you will find slumbering mjordin. Wake them until you find Iskalder. When you do, use this amulet upon him and bring him back to me.\n\nNow go. There is no time to waste!", objectives = "" }
WordHunterWoW_QuestEN[13134] = { title = "Spill Their Blood", description = "The Scourge cannot create their flesh monsters without blood and embalming fluid to preserve the parts and keep them functioning. If we can deny them these materials, their army will fall apart and we can easily destroy their creations.\n\nThroughout the labs where the flesh giants and abominations are cobbled together, you will find vats of embalming fluid and large orbs filled with blood. Destroy these, and bring death to any who would stop you!", objectives = "" }
WordHunterWoW_QuestEN[13135] = { title = "It Could Kill Us All", description = "Southeast of here, at the eastern reaches of Crystalsong Forest, is an area known as the Unbound Thicket. Within that thicket creeps all manner of life. One thing all of the affected creatures of the thicket share in common is their affinity for magical energy. Each of them holds pure, crystallized energy. Enough to kill us all should it ever destabilize!\n\nTravel to the Unbound Thicket and kill its denizens for crystallized energy. We need fuel and they need to die. We call that a \"win-win.\"", objectives = "" }
WordHunterWoW_QuestEN[13136] = { title = "Jagged Shards", description = "You pulled this jagged, dark brittle shard from the body of a ghoul. The metal blade lacks a smooth edge, suggesting it was forged by an unskilled hand, or was broken from a larger piece.\n\nYou recall seeing similar shards embedded in the bodies of all the ghouls you've encountered at the Fleshwerks, leading you to wonder why their creators bothered to include the metal at all. Perhaps Crusader Olakin Sainrith would have some insight if you brought him the shards from several ghouls.", objectives = "" }
WordHunterWoW_QuestEN[13137] = { title = "Not-So-Honorable Combat", description = "Atop the tallest peak to the southwest overlooking Jotunheim is Battlescar Spire. It is a place of reverence for the vrykul, second only to Valhalas in terms of where they prefer to do honorable combat.\n\nWe shall visit not-so-honorable combat upon it.\n\nGather your companions and fly to the spire. When you are ready, light the signal fire and I will appear within the body of Iskalder.\n\nWe will fight, you will win, and Vardmadra is sure to come to witness the battle!", objectives = "" }
WordHunterWoW_QuestEN[13138] = { title = "I'm Smelting... Smelting!", description = "<Olakin turns one of the shards over in an armored fist.>\n\nThese could pierce armor with enough force. We have to find out what they're made of and what the Lich King intends to do with them.\n\nTo the east, nestled next to Icecrown Citadel itself, lies Malykriss. From the few reports we have, it's full of smelting and smithing equipment. Bring these shards there, and smelt them in one of the open furnaces on the bottom level of Malykriss. Once the metal has been reformed, we can identify it.", objectives = "" }
WordHunterWoW_QuestEN[13139] = { title = "Into The Frozen Heart Of Northrend", description = "Silas and Spitzpatrick have signed off on the materials and fuel needed to begin construction of Justice Keep. Thanks to you and the Ebon Blade the Scourge presence within Scourgeholme has been decimated and their lieutenants have been defeated.\n\nI have chosen the site at which we will break ground, but first you must deliver my report to Highlord Tirion Fordring. We will begin our march into Icecrown on his command.\n", objectives = "" }
WordHunterWoW_QuestEN[13140] = { title = "The Runesmiths of Malykriss", description = "Those shards you recovered can only have come from one place, Malykriss. It's the seat of the Lich King's metalworking operations, to the east of Corp'rethar.\n\nWhat's puzzling is that metal isn't needed to stitch together abominations or flesh giants, or to summon skeletal servants. Find the skeletal runesmiths working on the bottom level of Malykriss and capture the plates they're working on. We need to find out why this metal is finding its way to the Fleshwerks.", objectives = "" }
WordHunterWoW_QuestEN[13141] = { title = "The Battle For Crusaders' Pinnacle", description = "<Highlord Fordring holds a banner of the Argent Crusade.>\n\nThis banner is like no other, {name}. It carries with it a powerful blessing, able to sanctify large tracts of blighted land.\n\nYou must take it northwest, through the Breach, to an area the Scourge have mockingly named Crusaders' Pinnacle. Plant the banner atop the skulls of our fallen brethren at Crusaders' Pinnacle and defend it against attack. Once the land is sanctified, return to Father Gustav.\n\nGo now, {name}. Hold no fear in your heart.", objectives = "" }
WordHunterWoW_QuestEN[13142] = { title = "Banshee's Revenge", description = "The time has come, {name}. You and your friends must challenge the lord of Balargarde Fortress, the master of Jotunheim, Overthane Balargarde.\n\nAtop the fortress, which is on the southwestern edge of Jotunheim, you will find a horn. Blow into it. Allow your challenge to resound throughout the steadfast.\n\nBalargarde will have no choice but to face you. And I... excuse me, Vardmadra will be there to adjudicate the challenge.\n\n<The banshee-possessed vrykul lets out a bellowing cackle.>", objectives = "" }
WordHunterWoW_QuestEN[13143] = { title = "New Recruit", description = "First things first. I saw some Lithe Stalkers on the ramparts just east of us. They used to serve us before we broke with Arthas, and they're about as perfect a scout as you can get... with a little prodding from an eye of dominion.\n\nFly up, find one of the stalkers, beat it down a bit, and then use this Sigil of the Ebon Blade to command its obedience. It will recognize the sigil, guaranteed. Lead it back to the top of the rocks northeast of here and it will find its way to me.", objectives = "" }
WordHunterWoW_QuestEN[13144] = { title = "Killing Two Scourge With One Skeleton", description = "The workers in the Fleshwerks abomination lab have already completed a number of their creations. For now, the creatures are chained to the pillars around the edge of the lab, but if we do not act, they will march with the Lich King's armies.\n\nGrasping arms reach out of the bone piles spread throughout the Fleshwerks. These arms belong to skeletons enchanted with the power of fire. Find and free these skeletons, then take them near the completed abominations and watch the show!", objectives = "" }
WordHunterWoW_QuestEN[13145] = { title = "The Vile Hold", description = "We need to know what we're up against.\n\nUse the eye of dominion to assume control of a lithe stalker and scout out the area. There are a few spots in particular I saw when flying in that I want you to get a closer look at: the overlook in the northeast, the work area in the southeast, the large forge near the center, and the ritual area in the southwest.\n\nThe stalker can leap far and won't be hurt by large falls - use that to your advantage to get up and down from those ramparts.", objectives = "" }
WordHunterWoW_QuestEN[13146] = { title = "Generosity Abounds", description = "We need to cause some disruption to bring those death knights away from their leaders. If we lay waste to their minions below, I suspect they'll have to devote more attention to keeping a close eye on operations.\n\nAbominations are easy prey - slow, predictable, and most importantly, stupid. Take advantage of their trust of the stalkers to drag them near some of the Scourge bombs scattered throughout the construction area. You'll be able to light the bombs far before they figure out what's going on.", objectives = "" }
WordHunterWoW_QuestEN[13147] = { title = "Matchmaker", description = "The major difference between vargul and lesser undead minions is that vargul still possess enough of their minds to despise being used for labor. Never will a vargul be pleased to be working aside skeletons or ghouls.\n\nLets take advantage of this inevitable animosity and start some fights between the umbral brutes and the other undead in Malykriss. That should serve to slow production and bring the death knights down to babysit.\n\nShould be simple - throw rocks at the brutes as they near lesser undead.", objectives = "" }
WordHunterWoW_QuestEN[13149] = { title = "Dispelling Illusions", description = "The infinite dragonflight seek to disrupt history by deceiving Prince Arthas.\n\nIf they can convince him that none of the grain here carries the plague, then he'll never have to make the fateful decision to cull Stratholme.\n\nUse this arcane disruptor on any suspicious crates of grain you find.", objectives = "" }
WordHunterWoW_QuestEN[13151] = { title = "A Royal Escort", description = "Arthas will soon face a desperate dilemma, and make a momentous decision.\n\nI must call upon you to accompany the prince in his culling.\n\nArthas must make it through Stratholme alive and you must see to it that he defeats Mal'Ganis!", objectives = "" }
WordHunterWoW_QuestEN[13152] = { title = "A Visit to the Doctor", description = "So they've been embedding these ghouls with broken shards of saronite down in the Sanctum of Reanimation? We must put a stop to this, before these ghouls can be deployed against our troops.\n\nFind the entrance to the Sanctum of Reanimation in the flesh giant lab area of the Fleshwerks. There, the ghoul mastermind, Doctor Sabnok, keeps the most fearsome of his creations, Patches. Free Patches from his chains and help him take his revenge on the doctor. Let his own creation be his undoing.", objectives = "" }
WordHunterWoW_QuestEN[13153] = { title = "Warding the Warriors", description = "{name}, good to see you. While the battle has subsided for now, we must hurry and replenish our stocks. My research indicates that the armor of soldiers recently slain in the Glacial Falls becomes imbued with an incredible amount of energy. The Horde has been seen collecting armor in the area.\n\nHead to the Glacial Falls and slay any of the Horde you find there. Return their imbued armor to me.\n\nIf you cannot find any of the Horde, you might find the armor of an adventurer slain by the elementals.", objectives = "" }
WordHunterWoW_QuestEN[13154] = { title = "Bones and Arrows", description = "Dragons are incredible! Well, their bones at least! I've been equipping our archers with arrowheads made of Dragonbone. Unfortunately, since the massacre at Angrathar, it has become almost impossible to get bone from Dragonblight.\n\nHowever, the Forest of Shadows on the western edge of Wintergrasp has enough bones to tide us over.\n\nHead to the Forest of Shadows and bring back any bone splinters you can find!\n\nThe Horde have been seen collecting bone splinters in the area. Slay them!", objectives = "" }
WordHunterWoW_QuestEN[13155] = { title = "Vereth the Cunning", description = "I've already heard some rumors regarding Malykriss and Arthas's new death knight order, but I assumed it nothing more than filling the void. These numbers suggest he's trying to take it up a notch though.\n\nWe dispatched one of our best to Malykriss not long ago - Vereth the Cunning. You should be able to find him on the Rise of Suffering, just west of Malykriss, and inside the Court of Bones.\n\nTry not to draw too much attention on your way in.", objectives = "" }
WordHunterWoW_QuestEN[13156] = { title = "A Rare Herb", description = "My, it its quite chilly up here! Reminds me of the stormy peaks of Kaarinos on Argus. However, with all of this snow and ice, our soldiers can easily catch cold.\n\nHead to the Steppe of Life in southwestern Wintergrasp, and bring me back 10 of the Horde herb pouches you find. I will grind them into a medicine to help protect against the cold.\n\nThe Horde have been seen collecting them from the plant life in the area. Do not hesitate to slay them and retrieve the herbs!", objectives = "" }
WordHunterWoW_QuestEN[13157] = { title = "The Crusaders' Pinnacle", description = "Stand proud in knowing that it was you who helped establish the Argent Crusade inside the walls of Icecrown, {name}. The Crusaders' Pinnacle now stands in direct defiance of the Lich King and his twisted minions.\n\nHighlord Fordring and the crusaders who survived await your arrival at Crusaders' Pinnacle. Travel once more through the Breach and seek out the highlord!", objectives = "" }
WordHunterWoW_QuestEN[13160] = { title = "Stunning View", description = "Gargoyles make effective scouts and can be deadly if left to rain attacks from the air, but they have a very obvious weakness. Most of them have to go through long periods resting as stone to maintain the energy they need to carry their heavy bodies through the air.\n\nAs I peered through the eye you were using, I noticed dozens of iceskin sentries resting on the eastern and southern walls inside. Use the stalker to leap up to their ledges and devastate them while they sleep.", objectives = "" }
WordHunterWoW_QuestEN[13161] = { title = "The Rider of the Unholy", description = "It's time that we start cutting off the heads of the beast.\n\nI served beside Rokir for quite some time. He knows the unholy arts better than most any other death knight I've met and he's equally as ruthless.\n\nRokir's strengths are most apparent when you are fighting him on his own ground. Sadly, we don't have much option in those regards, but stay on your feet to avoid his undead minions and you should come out victorious.\n\nBe nimble, {class}, and do not take him lightly.", objectives = "" }
WordHunterWoW_QuestEN[13162] = { title = "The Rider of Frost", description = "Sapph... Sapph's a death knight like no other. She'll shower you with sweet words and you'll swear that she has no evil within her heart, and then she'll run you through without even breaking her smile.\n\nI have no fear that you'll be able to best Sapph, but do not grow overconfident. Her strength lies in lulling her victims into a false ease, shortly before shattering them with a fierce barrage of frost attacks.\n\nDo not let your guard down, and do not underestimate her.", objectives = "" }
WordHunterWoW_QuestEN[13163] = { title = "The Rider of Blood", description = "Baelok is one of the few vrykul that I've ever seen rise through the ranks, and that was mostly accomplished through sheer brutality. If your competition ends up dead, there's far less to compete against.\n\nWhen you join battle with him, spread out from your companions and keep your distance as much as you reasonably can. He will not hesitate to steal your life force for himself, so you will need to hinder his ability to do so as much as possible.\n\nYou have my confidence. See to it that he dies.", objectives = "" }
WordHunterWoW_QuestEN[13164] = { title = "The Fate of Bloodbane", description = "With the riders of the Host of Suffering dead, now is the time to put an end to their true leader: Orbaz Bloodbane.\n\nMograine caught up with me while you were off and told me that he found where Orbaz is hiding. Under Icecrown Citadel itself, there is an immense pit - you will find Orbaz just outside its lip.\n\nSome of the Ebon Blade's strongest agents have already been dispatched - gather aid and join the fight. It is time for Bloodbane to die.", objectives = "" }
WordHunterWoW_QuestEN[13165] = { title = "Taking Back Acherus", description = "The haze has been lifted. I can see as clearly now as the day that I plunged the Ashbringer into my own heart to free my father's cursed soul: my last memory as a free man.\n\nWe must take back Acherus from the Scourge if our order is to survive in this new world. I have taught you how to call forth a death gate. The death gate will return you to Acherus when you call upon it, {name}. Use it now and meet me at Acherus. The first battle of the Knights of the Ebon Blade is underway! Death to the Scourge!", objectives = "" }
WordHunterWoW_QuestEN[13166] = { title = "The Battle For The Ebon Hold", description = "The Hall of Command has been secured, but the Lich King has left us a little present in the Heart of Acherus. The stitched terror, Patchwerk, and a horde of abominations have taken over the second floor.\n\nUse the teleporter to get to the second floor and destroy the Scourge forces that remain. Do not engage Patchwerk alone! You must fight the monstrosity with other death knights of Acherus!\n\nGo, {name}. You have my strength to carry you!", objectives = "" }
WordHunterWoW_QuestEN[13168] = { title = "Parting Gifts", description = "Look what we have here... eyes of dominion. The Cult normally goes to great lengths to keep these things safe, but I suppose their options for retreat are few when we're slaughtering them in their own home.\n\nThe eyes allow a being of any relative power to control an undead minion's actions precisely. As you can imagine, this can be extremely useful when it comes to your typical clumsy ghoul or skeleton.\n\nCare to try your hand at it? Use one of the eyes to control a captured shade.", objectives = "" }
WordHunterWoW_QuestEN[13169] = { title = "An Undead's Best Friend", description = "As is usual practice, the undead at the saronite quarry to the southwest starve plaguehounds to keep them extra aggressive. Use the shade to get up close and feed some of those hounds and I promise you they'll be content to leave you alone, if not side with the hand that fed them.\n\nDon't get too close to those things until you've fed them though. Their noses don't fall victim to your shade's elusiveness.", objectives = "" }
WordHunterWoW_QuestEN[13170] = { title = "Honor is for the Weak", description = "Ghouls are fragile things when it comes down to it, and the lookouts at the saronite quarry down the path to the southwest are no exception. Using one of the shades, I have no doubt that you can sneak up and put down their lookouts without making a sound.\n\nClear out as many lookouts as you can reach in a reasonable amount of time... we'll want their ranks thinned for our assault to come.", objectives = "" }
WordHunterWoW_QuestEN[13171] = { title = "From Whence They Came", description = "My main concern is the saronite quarry down the path to the southwest. They are pulling up immense amounts of ore from that quarry and I'd like to know what they're building with it. To that end, we'll start by weakening their defenses.\n\nI noticed a series of crystals scattered throughout the base and I assume they are defensive structures of some sort, not unlike ziggurats. Use the eidolon watcher to destroy any of those crystals that you find.", objectives = "" }
WordHunterWoW_QuestEN[13172] = { title = "Seeds of Chaos", description = "Effective tool, is it not? Excellent job weakening their defenses, {class}. Now we can push the main assault.\n\nThe plan here is straight-foward - we're looking to destroy anything moving, and get in there and steal some information amidst the confusion.\n\nLet me know when you're ready and I'll set you up with a skeletal gryphon.", objectives = "" }
WordHunterWoW_QuestEN[13174] = { title = "Amidst the Confusion", description = "Shutting down their operation is just half of the plan. The other important goal here is to find out where all that saronite is being sent. We know of a few places it's been ending up, but the amount they're pulling out suggests to me that there's a bigger project in the works.\n\nOnce you're inside the quarry, get your hands on any of their documents that you can find. If you're assaulting the place with one of the gryphons, you can drop down from it as soon as the wetwork is done.", objectives = "" }
WordHunterWoW_QuestEN[13177] = { title = "No Mercy for the Merciless", description = "Welcome to the Wintergrasp Fortress, {name}. Your mission is simple. Defeat ten of the Horde's finest. Now, go! Bring victory to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[13178] = { title = "Slay them all!", description = "Welcome to the Wintergrasp Fortress, {name}. Warlord Garrosh demands one thing: Slay them all!\n\nReturn to me when ten of the strongest members of the Alliance are dead.", objectives = "" }
WordHunterWoW_QuestEN[13179] = { title = "No Mercy for the Merciless", description = "Welcome to Wintergrasp, {name}. Your mission is simple. Defeat ten of the Horde's finest. Now, go! Bring victory to the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[13180] = { title = "Slay them all!", description = "Welcome to Wintergrasp, {name}. Warlord Garrosh demands one thing: Slay them all!\n\nReturn to me when ten of the strongest members of the Alliance are dead.", objectives = "" }
WordHunterWoW_QuestEN[13181] = { title = "Victory in Wintergrasp", description = "Commander Zanneth might be satisfied with a pile of Horde corpses at his feet, but controlling Wintergrasp is of the utmost importance to the Valiance Expedition. Make sure it remains in our control.\n\nHowever, don't think we'll just let you stand around while your allies do your dirty work for you. If you're not at least a second level recruit by the end of the battle, don't come back.", objectives = "" }
WordHunterWoW_QuestEN[13183] = { title = "Victory in Wintergrasp", description = "While Dardosh might be content with slaying our foes, it is of the utmost importance that we control Wintergrasp Fortress. Do whatever it takes to ensure Wintergrasp is ours.\n\nHowever, don't think we'll just let you stand around while your allies do your dirty work for you. If you're not at least a second level recruit by the end of the battle, don't come back.", objectives = "" }
WordHunterWoW_QuestEN[13185] = { title = "Stop the Siege", description = "I hears dem! The Alliance come soon. Destroy three Alliance siege devices and come back to Murp.", objectives = "" }
WordHunterWoW_QuestEN[13186] = { title = "Stop the Siege", description = "It is only a matter of time before this castle is besieged by the forces of the Horde. Destroy three of their siege devices and return to me.", objectives = "" }
WordHunterWoW_QuestEN[13187] = { title = "The Faceless Ones", description = "In my peoples' struggle against the forces of the undead, they dug deeper as they lost ground.\n\nThey inadvertently exposed minions of the Old Gods known only as the Faceless.\n\nIn the end, we could not fight a war on two fronts.\n\nWith your aid, perhaps the Faceless will finally fall.", objectives = "" }
WordHunterWoW_QuestEN[13188] = { title = "Where Kings Walk", description = "You are now, and forever will be, a Knight of the Ebon Blade, {name}, but know this: you were once a hero of the Alliance.\n\n<Darion stares at you.>\n\nThis order must establish allies for itself if it is to survive. You must represent the Knights of the Ebon Blade to the Alliance.\n\nOn the platform, southeast of me, is a portal to Stormwind City. Take this letter, given to me on your behalf by Lord Fordring, and deliver it to King Anduin Wrynn. Use the portal.", objectives = "" }
WordHunterWoW_QuestEN[13189] = { title = "Saurfang's Blessing", description = "You are now, and forever will be, a Knight of the Ebon Blade, {name}, but know this: you were once a hero of the Horde.\n\n<Darion stares at you.>\n\nThis order must establish allies for itself if it is to survive. You must represent the Knights of the Ebon Blade to the Horde.\n\nOn the platform, southeast of me, is a portal to Orgrimmar. Take this letter, given to me on your behalf by Lord Fordring, and deliver it to High Overlord Saurfang. Use the portal.", objectives = "" }
WordHunterWoW_QuestEN[13191] = { title = "Fueling the Demolishers", description = "Lok'tar, {name}! While the battle may be over, we must prepare for the Alliance's next assault! Travel to the Cauldron of Flames in south eastern Wintergrasp and retrieve ten eternal embers.\n\nThe embers are mixed in with coal to fuel the Demolishers and Siege Engines. \n\nWe've heard reports of Alliance pigs collecting the embers all day. Slay them and take their embers! If they have already abandoned the area, then be prepared to fight the fire elementals there until you find some!", objectives = "" }
WordHunterWoW_QuestEN[13192] = { title = "Warding the Walls", description = "Hey 'mon. This place be givin' me dah heebie jeebies, don't cha know?\n\nWay too many spirits haunting dis place. I want ta be placing hoodoo wards up, but I be needin' some souls, mon. Not any soul though, only da soul of a strong warrior could do da job.\n\nThe Glacial Falls in east Wintergrasp be havin' dem special properties to extract da soul. Slay the Alliance there, mebbe they be havin' the stuff we need.\n\nBring back da armor of the slain. If there be no Alliance maybe da elementals got 'em, mon.", objectives = "" }
WordHunterWoW_QuestEN[13193] = { title = "Bones and Arrows", description = "Why would they set me to the task of arming our archers? I was a poet, not a ranger! Well, no use complaining. {name}, I am in need of dragon bone for our arrowheads.\n\nTravel to the Forest of Shadows on the western side of Wintergrasp. Ever since the last skirmish, the Alliance have been scavenging dragon bones in the area. Slay them and take the bones.\n\nIf that fails, you might be lucky and get one from the spirits in the area. I hear they love to impale their living victims on the bones as they die.", objectives = "" }
WordHunterWoW_QuestEN[13194] = { title = "Healing with Roses", description = "Between the battles, one might almost believe that there was hope for peace in this land. Sadly, that is not to be our fate.\n\nTravel to the Steppe of Life in southwestern Wintergrasp. I have need of the roses that grow there for salve to treat the wounded.\n\nSadly, the rose has become scarce due to the Alliance harvesting it too rapidly. Slay them on the Steppe of Life and retrieve their herb pouches from the bodies.\n\nIf that fails, perhaps a lasher or two might have one.", objectives = "" }
WordHunterWoW_QuestEN[13195] = { title = "A Rare Herb", description = "My, it is quite chilly up here! Reminds me of the stormy peaks of Kaarinos on Argus. However, with all of this snow and ice, our soldiers can easily catch cold.\n\nHead to the Steppe of Life in southwestern Wintergrasp, and bring me back 10 Horde Herb Pouches. I will grind the herbs into a medicine to protect against the cold.\n\nThe Horde have been seen collecting them from the plant life in the area. Do not hesitate to slay them and retrieve the herbs!\n\nYou may also find one on a lasher in the area.", objectives = "" }
WordHunterWoW_QuestEN[13196] = { title = "Bones and Arrows", description = "Dragons are incredible! Well, their bones at least! I've been equipping our archers with arrowheads made of Dragonbone. Unfortunately, since the massacre at Angrathar, it has become almost impossible to get bone from Dragonblight.\n\nHowever, the Forest of Shadows on the western edge of Wintergrasp has enough bones to tide us over.\n\nHead to the Forest of Shadows and bring back any bone splinters you can find!\n\nThe Horde have been seen collecting bone splinters in the area. Slay them!", objectives = "" }
WordHunterWoW_QuestEN[13197] = { title = "Fueling the Demolishers", description = "{name}! About time you showed up. While we may have lost the last battle, we should prepare for the next! Travel to the Cauldron of Flames in southeastern Wintergrasp and retrieve several eternal embers.\n\nThe embers are mixed in with coal to fuel the Demolisher and Siege Engines. \n\nOh, and if you happen to see some of the Horde in the Cauldron, don't hesitate to slay them and take their embers. We must prevent them from holding the keep!", objectives = "" }
WordHunterWoW_QuestEN[13198] = { title = "Warding the Warriors", description = "{name}, good to see you. We must prepare for our next assault on the fortress. My research indicates that the armor of soldiers recently slain in the Glacial Falls becomes imbued with an incredible amount of energy. The Horde has been collecting armor in the area.\n\nHead to the Glacial Falls and slay any of the Horde you find there. Return their imbued armor to me.\n\nIf you cannot find any of the Horde, you might find the armor of an adventurer slain by the elementals.", objectives = "" }
WordHunterWoW_QuestEN[13199] = { title = "Bones and Arrows", description = "Why would they set me to the task of arming our archers? I was a poet, not a ranger! Well, no use complaining. {name}, I am in need of dragon bone for our arrowheads.\n\nTravel to the Forest of Shadows on the western side of Wintergrasp. Ever since the last skirmish, the Alliance have been scavenging dragon bones in the area. Slay them and take the bones.\n\nIf that fails, you might be lucky and get one from the spirits in the area. I hear they love to impale their living victims on the bones as they die.", objectives = "" }
WordHunterWoW_QuestEN[13200] = { title = "Fueling the Demolishers", description = "Lok'tar, {name}! While the battle may have subsided, we must prepare to retake the fortress! Travel to the Cauldron of Flames in south eastern Wintergrasp and retrieve ten eternal embers.\n\nThe embers are mixed in with coal to fuel the Demolishers and Siege Engines. \n\nWe've heard reports of Alliance pigs collecting the embers all day. Slay them and take their embers! If they have already abandoned the area, then be prepared to fight the fire elementals there until you find some!", objectives = "" }
WordHunterWoW_QuestEN[13201] = { title = "Healing with Roses", description = "So many of our braves were lost during the battle, but even more shall die if left untreated. \n\nTravel to the Steppe of Life in southwestern Wintergrasp. I have need of the roses that grow there for salve to treat the wounded.\n\nSadly, the rose has become scarce due to the Alliance harvesting it too rapidly. Slay them on the Steppe of Life and retrieve their herb pouches from the bodies.\n\nIf that fails, perhaps a lasher or two might be in bloom.", objectives = "" }
WordHunterWoW_QuestEN[13202] = { title = "Jinxing the Walls", description = "Hey 'mon. See dem Alliance sitting comfy in their keep?\n\nI think they be a bit too comfy, ya? I want ta be jinxing the place, but I be needin' some souls, mon. Not any soul though, only da soul of a strong warrior could do da job.\n\nThe Glacial Falls in east Wintergrasp be havin' dem special properties to extract da soul. Slay the Alliance there, they be havin' the stuff we need.\n\nBring back da armor of the slain. If there be no Alliance maybe da elementals got 'em, mon.", objectives = "" }
WordHunterWoW_QuestEN[13203] = { title = "A Winter Veil Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[13206] = { title = "Disarmament", description = "We must discover the secret to these savages' weapons!\n\nIf you'd have seen how easily they cut through my companions, you'd understand my sense of urgency.\n\nScour the place. Gather all of their arms that you can carry.", objectives = "" }
WordHunterWoW_QuestEN[13207] = { title = "Halls of Stone", description = "Well now, I'm surprised to see other adventurers in a place such as this.\n\nIf my research on these halls is accurate, there be monumental discoveries to be made here!\n\nAssumin' I can count on ya to watch my back, you're welcome to tag along.", objectives = "" }
WordHunterWoW_QuestEN[13211] = { title = "By Fire Be Purged", description = "The Scourge uses our own fallen against us, by raising them as ghouls or skeletons, or by dismembering their corpses and using the parts to make abominations. This must stop!\n\nThe dead are heroes who fell in defense of all the living, and they cannot be confined to so grisly a fate. Moreover, we cannot afford to face them again on the field, used as weapons against us. Take this torch with you to the Fleshwerks, and burn any of the corpses you find in the Sanctum of Reanimation or the abomination lab.", objectives = "" }
WordHunterWoW_QuestEN[13212] = { title = "He's Gone to Pieces", description = "With the abduction of Crusader Olakin, the Argent Crusade's forces will have no commander in the final assault on the Fleshwerks. While one crusader is the same as any other to me, the argents won't see it that way.\n\nI hate to see us waste time chasing after this, but I have no choice. Our gallant crusader has likely been dismembered by now, and his remains used to construct abominations. Go down into the Fleshwerks, kill the corpulent horrors fighting our forces, and recover Olakin's body parts.", objectives = "" }
WordHunterWoW_QuestEN[13213] = { title = "Battle at Valhalas", description = "I see and hear many things, {name}, and something very important has happened since your defeat of Overthane Balargarde: you are wanted for battle in Valhalas!\n\nYou will find the battle pit to the north. Go now with your friends and speak with Geirrvif the val'kyr. The challengers that she will offer you within Valhalas are sure to require their help.\n\nGood luck.", objectives = "" }
WordHunterWoW_QuestEN[13214] = { title = "Battle at Valhalas: Fallen Heroes", description = "If you believe yourself ready to begin then I have just the match for you to cut your teeth on.\n\nAnother group of outsiders thought themselves prepared for the rigors of Valhalas. They had much hubris, but in the end they fell like all of the others.\n\nIf you think yourselves so different -- if you think that you have the skill and experience to fight here amongst such storied warriors -- then please accept the challenge.", objectives = "" }
WordHunterWoW_QuestEN[13215] = { title = "Battle at Valhalas: Khit'rix the Dark Master", description = "A variety of beings travel the world to prove themselves within Valhalas. Some even come from under the world.\n\nKhit'rix the Dark Master is one such.\n\nHailing from deep within the ground where insanity reigns, Khit'rix has asked for someone exotic to face in the ring. You will do.\n\nDare you face this Nerubian nightmare, {race}?", objectives = "" }
WordHunterWoW_QuestEN[13216] = { title = "Battle at Valhalas: The Return of Sigrid Iceborn", description = "An old foe of yours has returned: Sigrid Iceborn. Perhaps you remember besting her in a duel upon the Savage Ledge?\n\nNo matter, she certainly remembers you. She's insisting upon a chance to prove herself once more.\n\nPersonally, I think it's more a chance for revenge, but that too can be useful in this place.\n\nI leave it up to you, {name}. Will you face Sigrid Iceborn once more?", objectives = "" }
WordHunterWoW_QuestEN[13217] = { title = "Battle at Valhalas: Carnage!", description = "You've been successful up to this point, {name}, but what you must face to continue to battle within Valhalas is a gigantic horror beyond imagining.\n\nI must warn you to turn away now. Carnage is a mountain of flesh constructed by the Lich King's most fiendish minds.\n\nI do not see how you and your friends will defeat it. However, the choice is yours.", objectives = "" }
WordHunterWoW_QuestEN[13218] = { title = "Battle at Valhalas: Thane Deathblow", description = "Your skills have not gone unnoticed by the vrykul of Jotunheim, {name}. Thane Banahogg has taken a personal interest in you and has insisted that he be your next match.\n\nIf you thought Carnage was bad, then you might want to go home now. Thane Banahogg's nickname is The Deathblow. I think you can guess how he earned it.\n\nDo you accept the thane's challenge?", objectives = "" }
WordHunterWoW_QuestEN[13219] = { title = "Battle at Valhalas: Final Challenge", description = "I'm afraid that your success is going to be your undoing, {name}.\n\n<If the val'kyr could turn more white, she would.>\n\nWord of your success in Valhalas has reached deep into Icecrown Citadel, stirring one whom you have no desire to meet.\n\nPrince Sandoval himself is on his way at this very moment. Gjonner warned you that you should run and I cannot disagree.\n\nWhat will you do? He's on his way. Will you face the blood prince in final battle?", objectives = "" }
WordHunterWoW_QuestEN[13220] = { title = "Putting Olakin Back Together Again", description = "We can't afford to waste any time putting Olakin back together. Fortunately, the Scourge has provided a perfect place for you to stitch him back together.\n\nNear the Fleshwerks' flesh giant lab is the Sanctum of Reanimation. Search the area for a spool of thread and the doctor's cleaver. Then, take Olakin's remains to the large slab in the middle of the sanctum and get to work.", objectives = "" }
WordHunterWoW_QuestEN[13221] = { title = "I'm Not Dead Yet!", description = "The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their 'work' here if I cannot escape.\n\nI cannot make it on my own, my child, but with your help, I may yet live to fight the Scourge again.\n\nWill you help me make my escape before the Scourge's butchers come to finish me off?", objectives = "" }
WordHunterWoW_QuestEN[13222] = { title = "Defend the Siege", description = "Front and center, {name}! We're beginning our assault on Wintergrasp Fortress. Those Horde animals think they can hide cowardly behind their walls? Well, I think not! We'll show them the power of Gnomish technology and smash their walls to bits!\n\nHowever, even the most powerful siege device is helpless without a crew. Pilot or protect one of our siege vehicles as it destroys three of the Horde structures.", objectives = "" }
WordHunterWoW_QuestEN[13223] = { title = "Defend the Siege", description = "Dem Alliance won't be long to hold that keep. Murp would smash walls, but Murp has to stay in camp. Murp wish he could smash Alliance who want to hurt Horde demolishers.\n\nYou, {name}! You go in Murp's place. Protect 3 siege vehicles while they smash Alliance buildings. Alliance not expect you to defend demolisher. Show Alliance how smart Murp is! ", objectives = "" }
WordHunterWoW_QuestEN[13224] = { title = "Orgrim's Hammer", description = "The Argent Crusade pulled my ravaged body from the Broken Front. What a glorious battle, {race}. My axe sang as it cut down Alliance filth and Scourge alike.\n\nMy time is over. It will be a good death. Carry a message for me, soldier.\n\nOur base flies out of reach of Scourge - overhead between Mord'rethar and Aldur'thar. It is called \"Orgrim's Hammer.\"\n\n<Hork futilely attempts to salute.>\n\nFly high and avoid the Alliance juggernaut, Skybreaker. Tell Korm... tell him I died... fighting... For the Horde.", objectives = "" }
WordHunterWoW_QuestEN[13225] = { title = "The Skybreaker", description = "We were neck deep in Scourge and Horde. The screams of the dying covered that field. It was torturous... unrelenting!\n\nAt some point my body gave out. I fell, only to be awoken by the Argent Crusade. They pulled me out of the Broken Front and brought me here. I'm not going to make it. Grant a dying soldier one last wish, {race}? Our base, the Skybreaker, flies high above Icecrown. It is there that you'll find my commanding officer, High Captain Bartlett. Tell him that I died a soldier of the Alliance.", objectives = "" }
WordHunterWoW_QuestEN[13226] = { title = "Judgment Day Comes!", description = "We cannot defeat the Lich King on our own. Divided we shall all fall!\n\nI implore you to answer the call, brother. The Argent Crusade accepts all who would volunteer to aid in the war effort. Highlord Tirion Fordring himself awaits you at the Argent Vanguard! Get upon your mount and fly to the southeastern reaches of Icecrown. It is there that you will find Lord Fordring and the soldiers of the Argent Crusade.\n\nGo now, {class}, for judgment day comes!", objectives = "" }
WordHunterWoW_QuestEN[13227] = { title = "Judgment Day Comes!", description = "We cannot defeat the Lich King on our own. Divided we shall all fall!\n\nI implore you answer the call, brother. The Argent Crusade accepts all that would volunteer to aid in the war effort. Highlord Tirion Fordring himself awaits you at the Argent Vanguard! Get upon your mount and fly to the southeastern reaches of Icecrown. It is there that you will find Lord Fordring and the soldiers of the Argent Crusade.\n\nGo now, {class}, for judgment day comes!", objectives = "" }
WordHunterWoW_QuestEN[13228] = { title = "The Broken Front", description = "What battle?! Those troops were on a recon mission!\n\nAnd what's this talk of Alliance - you're sure he said Alliance?\n\nListen to me, {name}! I need to know what's going on and I need to know NOW!\n\nGet yourself down there and get me some answers! Scour the battlefield and look for survivors - clues - anything!", objectives = "" }
WordHunterWoW_QuestEN[13229] = { title = "I'm Not Dead Yet!", description = "The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their 'work' here if I cannot escape.\n\nI cannot make it on my own, {class}, but with your help, I may yet live to fight the Scourge again.\n\nWill you help me make my escape before the Scourge's butchers come to finish me off?", objectives = "" }
WordHunterWoW_QuestEN[13230] = { title = "Avenge Me!", description = "I hear them, brother....\n\nThe moans of the wounded Alliance... they taunt me...\n\nFinish what we have begun here, {class}. Show no mercy... let none of them survive.\n\nFor... the Horde...", objectives = "" }
WordHunterWoW_QuestEN[13231] = { title = "The Broken Front", description = "What?! Noooo!\n\nWe went to such great pains to keep this attack secret. How could the Horde have known? The resources... the men... all lost? Inconceivable!\n\nOur plans here in Icecrown hinged upon our taking that gate before the Horde could. We must recover quickly and prepare to mount another offensive.\n\nVisit the battlefield and search for any survivors. See if there's anything to be learned from this tragedy.\n\nAnd prepare yourself, {name}, for a war - on two fronts...", objectives = "" }
WordHunterWoW_QuestEN[13232] = { title = "Finish Me!", description = "They taunt us - even as they lie dying here...\n\nPlease, brother... Don't allow their mocking to be the last sounds I hear...\n\nFinish me... deliver me from this torment... into... the Light.\n\nSeek out  my companions... offer them the same mercy.\n\nLeave nothing for the Scourge to raise!\n\nI beg you...", objectives = "" }
WordHunterWoW_QuestEN[13233] = { title = "No Mercy!", description = "It is as I told you. They were not merely idle words spoken in a fit of anger.\n\nTime and again, the Horde have demonstrated their disdain for everything we hold dear and holy. They must pay with their lives for their transgressions against the light.\n\nAll of them.\n\nJust imagine a world free of their stain, {name}. Envision the joy our children will know. Think of the reverence your descendants will have for your memory, knowing they owe their happiness to you.\n\nNow go, and make that vision a reality!", objectives = "" }
WordHunterWoW_QuestEN[13234] = { title = "Make Them Pay!", description = "The time has come!\n\nToo long have we suffered the company of the self-righteous Alliance! Too long have we stayed our hand from cleansing our world of the weak and the desperate.\n\nNow, we bring an end to our humiliation! Now, we show them the true meaning of fear! Now, we bring honor to the Horde!\n\nHere, at Icecrown, we break the Alliance!\n\nGo, {class}. Hunt them down. Break them. Take their will to live!", objectives = "" }
WordHunterWoW_QuestEN[13235] = { title = "The Flesh Giant Champion", description = "You've done well in destroying the Fleshwerks and slaughtering the Lich King's servants. Now, all that remains is to defeat the Fleshwerks' greatest accomplishment -- the flesh giant known as Morbidus.\n\nIt will not be an easy fight, but the Shadow Vault has dispatched Margrave Dhakar with some reinforcements. Meet up with him at the highest point at the western end of the Fleshwerks. Tell him when you're ready to begin the attack and he'll order his forces into battle.", objectives = "" }
WordHunterWoW_QuestEN[13236] = { title = "Army of the Damned", description = "You probably think you're quite strong -- fighting these undead and crushing their bones beneath your war machines.\n\nThat is nothing compared to the strength it took to create them.\n\nI saw the prince do it himself.  I can show you how it happened... if you'd like.", objectives = "" }
WordHunterWoW_QuestEN[13237] = { title = "Poke and Prod", description = "While your commander has his focus diluted by his loathing of your Alliance rivals, you can depend on me to direct my attention squarely on the real enemy here - the Lich King and his minions.\n\nIn order to hold any hope of conquering him at the citadel, your people must take and hold each gate.\n\nFor now, let us focus on the first. Return to the front and prod their defenses. Look for any sign of weakness that we might exploit.\n\nI'll await your report, {class}.", objectives = "" }
WordHunterWoW_QuestEN[13238] = { title = "Good For Something?", description = "Goblins! Hyper little busy-bodies...\n\nListen, {name}. Copperclaw, our resident engineer, is insisting that he's got something useful to show me.\n\nI'm in no mood to endure his squeaky nagging. The last time I acknowledged him, he chirped on for an hour straight. It was all I could do to keep from drop-kicking him into Sindragosa's Fall!\n\nYou go in my place and humor him. Let me know if indeed he's on to anything.", objectives = "" }
WordHunterWoW_QuestEN[13239] = { title = "Volatility", description = "Where to begin... well, you must know that as chief engineer of this vessel I have access to all of the intelligence reports - yes, yes, it's true, and I've recently taken a particular interest in the frostwyrms you reported seeing to the south, and I do believe I've developed a plan that just might work against them... now it'll take a little legwork on your part, but essentially, you build a dummy out of armor and coat it with a splash of this solution, then run for cover!\n\n...You still here, {race}?", objectives = "" }
WordHunterWoW_QuestEN[13258] = { title = "Opportunity", description = "We recently came upon schematics that indicate a weakness in Icecrown Citadel.  An opening in its defenses, both figuratively and literally.\n\nThe captured diagrams show an orifice leading several hundred feet into the ground.  We're unsure of its purpose, but our scouting has revealed it to be of high importance to the Scourge.\n\nSpeak to Sergeant Kregga below Icecrown Citadel, she's leading the attack on the site.", objectives = "" }
WordHunterWoW_QuestEN[13259] = { title = "Establishing Superiority", description = "We've one shot at dealing some damage to this place -- let's make sure we get it right.\n\nWe've acquired potent, Scourge-made, saronite bombs.  But we must secure this area before we can set them off.\n\nWe're going to need to get the Scourge defenses under control quickly, before reinforcements arrive.\n\nHelp my men out and come back when you're ready for some fireworks.", objectives = "" }
WordHunterWoW_QuestEN[13260] = { title = "Takes One to Know One", description = "While we should never miss an opportunity to strike out against the Alliance, we mustn't forget about the Scourge.\n\nWe won't have the numbers here to make a proper assault in the glacier for weeks, but that won't keep us from learning all we can know about their defenses.\n\nI have asked our resident death knight to advise you in this effort. After all, who better knows this enemy than they?\n\nAllow me to introduce Koltira Deathweaver.\n", objectives = "" }
WordHunterWoW_QuestEN[13261] = { title = "Volatility", description = "Wahooo! It works! Not that I had any doubts in my supernatural ingenuity, only that I wasn't quite sure what kind of explosion to expect - let's just say I'm glad to see that you didn't get your eyebrows singed off. So now I just need to show ol' Korm how ya thaw out one 'a them wyrms. He'll hafta promote me to... to... to whatever comes after Chief Engineer! Here, you take another batch of the stuff and head back out to the front and I'll go get Korm...\n\nWell? Move out!", objectives = "" }
WordHunterWoW_QuestEN[13262] = { title = "Blow it Up!", description = "This is probably as under-control as this situation is going to get.  Let's do this, {name}.\n\nI need someone to light the fuse on those bombs and it looks like you're the one to do it.", objectives = "" }
WordHunterWoW_QuestEN[13263] = { title = "A Short Fuse", description = "As you light the fuse, you notice that it is consumed by fire far quicker than you would expect.\n\nThe bombs are about to go off and your best chance at surviving is to lean towards the pit and hope the fall doesn't kill you.", objectives = "" }
WordHunterWoW_QuestEN[13264] = { title = "That's Abominable!", description = "Abominations...\n\nThey can be a very capable enemy. I've seen them turn the tide of battle more than once. What few realize, is that they can also be very capable friends.\n\nThey are not deep thinkers. If you know the secrets of their creation, you can issue them basic orders that they will not question.\n\nFortunately for you, I know these secrets.\n\nThis kit will reanimate the remains of the abominations you defeat. Take it, and learn to use them against the Scourge on the death gate.", objectives = "" }
WordHunterWoW_QuestEN[13265] = { title = "Cloth Scavenging", description = "The cut of your clothes suggests to me that you are a Tailor yourself and could easily learn the skill that I have to teach.\n\nMany of the northern humanoids wear clothes that can quickly be converted into cloth if you know the knack of doing it.\n\nFor a small fee I can teach you the art of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", objectives = "" }
WordHunterWoW_QuestEN[13268] = { title = "Cloth Scavenging", description = "You look like someone who knows their way around a needle and thread so maybe I can help you.\n\nThe northern humanoids wear clothes that can quickly be converted into cloth if you know how.\n\nFor a few gold I am willing to teach you the art of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", objectives = "" }
WordHunterWoW_QuestEN[13269] = { title = "Cloth Scavenging", description = "The humanoids of the northern lands wear garments that can be converted into cloth if you know how.\n\nFor a few gold I am willing to teach you the art of Cloth Scavenging that will give you additional frostweave cloth from the humanoids of Northrend that you slay.", objectives = "" }
WordHunterWoW_QuestEN[13270] = { title = "Cloth Scavenging", description = "You be looking like da type who be knowin' how to sew some threads and so I got somethin' for ya.\n\nDa humanoids of da north be wearin' tings dat can be changed into cloth if you be knowin' da trick of it.\n\nIf you been willin' to part with some cash I can teach you da skill of Cloth Scavenging that be givin' ya extra frostweave cloth from the humanoids of Northrend.", objectives = "" }
WordHunterWoW_QuestEN[13271] = { title = "A Voice in the Dark", description = "The object is not a crystal at all, but some form of organ, encased in ice.\n\nAs you touch it, your hand reels in horrible pain.  You feel as if your hand has been cut, yet there is no visible wound.\n\nAs you collect your thoughts, you hear a young boy's voice nearby.\n\n\"You really shouldn't have done that.\"", objectives = "" }
WordHunterWoW_QuestEN[13272] = { title = "Cloth Scavenging", description = "As a Tailor I think you are ready to learn what I have to teach.\n\nMany of the northern humanoids wear clothes that can quickly be converted into cloth if you have the proper skill.\n\nFor a couple of gold coins I can teach you the skill of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", objectives = "" }
WordHunterWoW_QuestEN[13273] = { title = "Going After the Core", description = "With Norgannon's Shell in hand, only half of the archive key remains to be found. Luckily, I've had the Explorers' League hard at work chasing down leads about the whereabouts of Norgannon's Core.\n\nFar to the southeast of the Inventor's Library, on the slopes to the north of Dun Niffelem, is a camp bearing my name. The Explorers' League representatives seeking the second half of the key are based there. Bring me the maps and the notes they've made and we should be able to track down the other key half.", objectives = "" }
WordHunterWoW_QuestEN[13274] = { title = "The Core's Keeper", description = "Prospector Soren's notes say that Norgannon's Core is in the keeping of a sentinel named Athan, one of Mimir's creations.\n\nSoren says the vault where Athan resides is called \"Loken's Bargain\" these days.\n\nLoken, eh? The earthen have mentioned him.\n\nThe vault is said to be southwest of the ruined Explorers' League camp, with a round entrance on a mountainside overlooking the Valley of Ancient Winters.\n\nFind this Athan and get the core from him, but I wouldn't be surprised if you were in for a fight.", objectives = "" }
WordHunterWoW_QuestEN[13275] = { title = "Time to Hide", description = "You shouldn't have touched it.  But now that you did, he's going to come looking for you.\n\nAnd he'll find you.  Unless you hide yourself from him.\n\nBring me blood from the faceless ones if you want to live!", objectives = "" }
WordHunterWoW_QuestEN[13276] = { title = "That's Abominable!", description = "You know what to do, {class}.\n\nTake this kit and use the guts from their abominations to create one of your own, then command it to attack the enemy forces at the gate.\n\nYou would do well to refine this tactic for when we make our assault on the gate.", objectives = "" }
WordHunterWoW_QuestEN[13277] = { title = "Against the Giants", description = "While it's going to be crucial to defeat the Scourge on the ground, we mustn't neglect the gate itself.\n\nThe flesh giants on the ramparts are capable of hurling massive boulders and chunks of ice, inflicting devastating damage to enemy infantry below.\n\nMuster a force and defeat these giants. We need to know just what we're up against in terms of their strength.\n\nOh... and bring me their spines. If memory serves, there's a little trick I can share with you.", objectives = "" }
WordHunterWoW_QuestEN[13278] = { title = "Coprous the Defiled", description = "Reports of a powerful zombie at the death gate have reached my ears, {class}.\n\nWe cannot allow a potential threat such as this to go unchallenged. Any information you are able to glean from engaging it will be better than what we know now.\n\nGo to the western chamber of the gate and find this creature. Fight him, and find a weakness we might exploit.", objectives = "" }
WordHunterWoW_QuestEN[13279] = { title = "Basic Chemistry", description = "<Koltira takes the pustulant spines and drains their fluid into a flask.>\n\nA little-known quality of the flesh giants...\n\nTheir spinal fluid interacts with the plague in a very interesting way, turning it into a corrosive acid.\n\nPoured from the towering ramparts, acid may not be a welcome sight to the troops below, but at least the victims won't rise up and add to the enemy's numbers.\n\nPour the contents of this flask into one of the plague cauldrons in the western chamber of the death gate.", objectives = "" }
WordHunterWoW_QuestEN[13280] = { title = "King of the Mountain", description = "You've just got to get my jumpbot to the tippy top of the mountain to the northwest here at Ymirheim pronto, {name}!\n\nThat dastardly, no-good Blast Thunderbomb is working on his own bot, and I'm afraid he almost has it completed. We're in a race to see who's gonna be king of the mountain!\n\nOnce you jump up there, plant our battle standard in the pile of bones and show everyone that the Alliance, and my engineering skills, are the best!", objectives = "" }
WordHunterWoW_QuestEN[13281] = { title = "Neutralizing the Plague", description = "You no longer need my assistance in neutralizing the enemy's plague cauldrons, {race}.\n\nHunt down the flesh giants at the death gate and use the fluid from their spines to render batches of the plague ineffective.\n\nYou are striking at the heart of the enemy's strategy. This is an important mission - vital to our cause, and should be carried out whenever time permits.\n\nRemember, the giants and the plague cauldrons can be found on Mord'rethar.", objectives = "" }
WordHunterWoW_QuestEN[13282] = { title = "Return to the Surface", description = "You should leave now.  You'll find a portal behind me.  It'll take you to the surface.\n\nWe'll meet again.  He'll be looking for you.\n\nIt's only a matter of time until he finds you.", objectives = "" }
WordHunterWoW_QuestEN[13283] = { title = "King of the Mountain", description = "Yo, {name}, I need you to get my jumpbot to the top of this mountain to the southeast, like yesterday!\n\nThat girly, self-righteous Frazzle Geargrinder thinks that her jumpbot's better than mine. Hah! We're in a race to see who's gonna be king of the mountain!\n\nOnce you jump up there, plant our battle standard in the pile of bones and show everyone that the Horde, and my mad engineering skills, are the best!", objectives = "" }
WordHunterWoW_QuestEN[13284] = { title = "Assault by Ground", description = "Greetings {class}.\n\nOur troops have been attempting to storm Ymirheim for some time, but these vrykul are far more vicious than any we've faced before. They've been ambushing us repeatedly as we try to make it up the pass, and we've lost a lot of men.\n\nIf you want to lend yourself to the battle and help get my squad to the gates of Ymirheim safely, we will gladly reward you for your efforts. Once at the gates, we'll dig in and wait for reinforcements to catch up to us.", objectives = "" }
WordHunterWoW_QuestEN[13285] = { title = "Forging the Keystone", description = "Aha! Here it is: the Temple of Invention, the seat of Keeper Mimir himself! Of course, that's where one would go to join the two parts of the key.\n\nAccording to the prospector's notes, the Temple of Invention is one of the highest points on the western side of the Terrace of the Makers. That means it should be roughly east of your Grom'arsh Crash Site.\n\nI'll meet you at the temple and we'll combine the parts together.", objectives = "" }
WordHunterWoW_QuestEN[13286] = { title = "...All the Help We Can Get.", description = "Desperate times, {class}...\n\nAs uncomfortable as it makes me, I'm prepared to accept assistance from anyone - including our resident death knight.\n\nGo to Thassarian and see if he can help us develop tactics against the Scourge that will ensure victory once we are able to mount another offensive.\n\nWe have come so far... we must not fail here!", objectives = "" }
WordHunterWoW_QuestEN[13287] = { title = "Poke and Prod", description = "As someone of your experience must surely know, there's no better way to familiarize one's self with their enemy than by confronting them in combat.\n\nWhile you no doubt lust for the glory of taking Icecrown Citadel, that cannot happen without taking each of the Lich King's gates first. For now, you must focus your efforts on the first of these...\n\nReturn to the Broken Front. Engage the enemy in battle. Search for a weakness we might exploit and return to me with a detailed report.", objectives = "" }
WordHunterWoW_QuestEN[13288] = { title = "That's Abominable!", description = "Abominations...\n\nThey can be a very capable enemy. I've seen them turn the tide of battle more than once. What few realize, is that they can also be very capable friends.\n\nThey are not deep thinkers. If you know the secrets of their creation, you can issue them basic orders that they will not question.\n\nFortunately for you, I know these secrets.\n\nThis kit will reanimate the remains of the abominations you defeat. Take it, and learn to use them against the Scourge on the death gate.", objectives = "" }
WordHunterWoW_QuestEN[13289] = { title = "That's Abominable!", description = "You know what to do, {class}.\n\nTake this kit and use the guts from their abominations to create one of your own, then command it to attack the enemy forces at the gate.\n\nYou would do well to refine this tactic for when we make another assault on the gate.", objectives = "" }
WordHunterWoW_QuestEN[13290] = { title = "Your Attention, Please", description = "Chief Engineer Boltwrench has proven invaluable in his service aboard the Stormbreaker. Were it not for his ingenuity, we'd be sprinkled across half of the glacier several times over by now.\n\nThe thing is, he feels he must share his every miniscule invention or discovery - most of which I don't even understand.\n\nMy focus must be squarely on our enemies right now. I cannot afford any distractions.\n\nPlease visit him in my stead, {name}. And if you can, assist him. You'll find him belowdecks.", objectives = "" }
WordHunterWoW_QuestEN[13291] = { title = "Borrowed Technology", description = "I get it, I get it. Cappy's too busy to see this for himself. His loss!\n\nSee, I've managed to 'acquire' a certain shipment of solution from the enemy. And as much as I hate tinkerin' with inferior goblin technology, I'm inclined to make an exception here.\n\nTake this sample. I'll need you to run a few field tests, just to prove its usefulness, while I try to do a little reverse engineering to duplicate the creation process.\n\nGo to the front and gather the materials to make a decoy, then use the oil.", objectives = "" }
WordHunterWoW_QuestEN[13292] = { title = "The Solution Solution", description = "Oh, yes, yes. Back again, are we? Never enough practice, I suppose.\n\nHere we are, the solution to that pesky frostwyrm problem.\n\nMake them scarce, {race}. The more you take out now, the less we face when we are again ready to attempt our march on the citadel.\n\nBest of luck, now. And do bring back whatever you don't use.", objectives = "" }
WordHunterWoW_QuestEN[13293] = { title = "Get to Ymirheim!", description = "You need to get down to Ymirheim, that big frost vrykul town in the middle of Icecrown.\n\nOur boy, Blast Thunderbomb, is down there on the west side of town representing the Warsong Offensive in a competition against the Alliance. It's his jumpbot versus theirs in a king of the mountain contest!\n\nDon't let us down, {name}. Goblin engineering pride is on the line! Besides, all the boys here in the hold are counting on you.\n\nThat and we've got money riding on it that you can kick those cowards in the pants!", objectives = "" }
WordHunterWoW_QuestEN[13294] = { title = "Against the Giants", description = "While it's going to be crucial to defeat the Scourge on the ground, we mustn't neglect the gate itself.\n\nThe flesh giants on the ramparts are capable of hurling massive boulders and chunks of ice, inflicting devastating damage to enemy infantry below.\n\nMuster a force and defeat these giants. We need to know just what we're up against in terms of their strength.\n\nOh... and bring me their spines. If memory serves, there's a little trick I can share with you.", objectives = "" }
WordHunterWoW_QuestEN[13295] = { title = "Basic Chemistry", description = "<Thassarian takes the pustulant spines and drains their fluid into a flask.>\n\nA little-known quality of the flesh giants...\n\nTheir spinal fluid interacts with the plague in a very interesting way, turning it into a corrosive acid.\n\nPoured from the towering ramparts, acid may not be a welcome sight to the troops below, but at least the victims won't rise up and add to the enemy's numbers.\n\nPour the contents of this flask into one of the plague cauldrons in the western chamber of the death gate.", objectives = "" }
WordHunterWoW_QuestEN[13296] = { title = "Get to Ymirheim!", description = "I need you down in Ymirheim, that big frost vrykul town in the middle of Icecrown.\n\nFrazzle Geargrinder is down there on the south side of town representing the Valiance Expedition in a competition against the Horde scum. It's her jumpbot versus theirs in a king of the mountain contest!\n\nDon't let us down, {name}. Gnomish engineering pride is on the line! Besides, all the boys here in the hold are counting on you.\n\nThat and we've got money riding on it that you can kick those idiots in the pants!", objectives = "" }
WordHunterWoW_QuestEN[13297] = { title = "Neutralizing the Plague", description = "You no longer need my assistance in neutralizing the enemy's plague cauldrons, {race}.\n\nHunt down the flesh giants at the death gate and use the fluid from their spines to render batches of the plague ineffective.\n\nYou are striking at the heart of the enemy's strategy. This is an important mission - vital to our cause, and should be carried out whenever time permits.\n\nRemember, the giants and the plague cauldrons can be found on Mord'rethar.", objectives = "" }
WordHunterWoW_QuestEN[13298] = { title = "Coprous the Defiled", description = "Reports of a powerful zombie at the death gate have reached my ears, {class}.\n\nWe cannot allow a potential threat such as this to go unchallenged. Any information you are able to glean from engaging it will be better than what we know now.\n\nGo to the western chamber of the gate and find this creature. Fight him, and find a weakness we might exploit.", objectives = "" }
WordHunterWoW_QuestEN[13300] = { title = "Slaves to Saronite", description = "Our people are being captured and put to work as slaves in the saronite mines of Ymirheim, the vrykul stronghold in the middle of Icecrown. The Lich King has them mining that unholy ore day and night.\n\nI made a promise to Highlord Fordring that we would get those wretches out of there alive, and that's exactly what we will do.\n\nUnfortunately, I've been ordered to stay on this gunship and serve as an ambassador to the Valiance Expedition. Will you please rescue them in my stead, {name}?", objectives = "" }
WordHunterWoW_QuestEN[13301] = { title = "Assault by Ground", description = "Greetings {class}.\n\nOur troops have been attempting to storm Ymirheim for some time, but these vrykul are far more vicious than any we've faced before. They've been ambushing us repeatedly as we try to make it up the pass, and we've lost a lot of men.\n\nIf you want to lend yourself to the battle and help get my squad to the gates of Ymirheim safely, we will gladly reward you for your efforts. Once at the gates, we'll dig in and wait for reinforcements to catch up to us.", objectives = "" }
WordHunterWoW_QuestEN[13302] = { title = "Slaves to Saronite", description = "Our people are being captured and put to work as slaves in the saronite mines of Ymirheim, the vrykul stronghold in the middle of Icecrown. The Lich King has them mining that unholy ore day and night.\n\nI made a promise to Highlord Fordring that we would get those wretches out of there alive, and that's exactly what we will do.\n\nUnfortunately, I've been ordered to stay on this gunship and serve as an ambassador to the Warsong Offensive. Will you please rescue them in my stead, {name}?", objectives = "" }
WordHunterWoW_QuestEN[13304] = { title = "Field Repairs", description = "The Scourge is still reeling from our attack, {name}.  Now is the time to capitalize on our momentum.\n\nThe strategically important valley below us is wide open.  We've located a disassembled demolisher vehicle in what we believe is working condition in the southeastern corner of the Valley of Lost Hope area.\n\nIf you can get the remaining parts from the Scourge scavengers, you should be able to get it running again.  A single working demolisher can wreak havoc on the enemy's ground units.", objectives = "" }
WordHunterWoW_QuestEN[13305] = { title = "Do Your Worst", description = "You're going to use this machine against the Scourge?  You're not going to win against them like that.\n\nYou can destroy hundreds... even thousands of them.  But you won't win.  Not out here.\n\nWhen you're done playing with your machine, meet me to the north.  There is an old army encampment.  What I will show you will teach you a little bit about who you're up against.", objectives = "" }
WordHunterWoW_QuestEN[13306] = { title = "Raise the Barricades", description = "When our forces begin to move beyond Aldur'thar, they will be vulnerable to attack from the Ironwall Rampart and the broad glacier below.\n\nWe have neither the time nor the materials to build fortifications, but we can put up some barricades to shield our men from fire and break up Scourge charges.\n\nTake this barricade kit to the Valley of Fallen Heroes, on the west side of Aldur'thar. Locate the markers I've placed there and use this kit to construct your barricades there.", objectives = "" }
WordHunterWoW_QuestEN[13307] = { title = "Bloodspattered Banners", description = "In the Valley of Fallen Heroes and Icecrown Glacier, to the west of Aldur'thar, the Scourge seeks to use the fallen against us. Scourge lieutenants have woken the valley's dead and imbued them with fearsome strength and fervor. The banners carried by the Scourge leaders in the glacier area are the source of these powers. Kill the banner-bearers, and you will weaken the converted heroes they lead.\n\nIt falls to you to rid us of this obstacle, and thin the resistance before the main body can advance.", objectives = "" }
WordHunterWoW_QuestEN[13308] = { title = "Mind Tricks", description = "<The creature speaks directly into your mind, its thoughts painful and strange.>\n\n{race}-thing, I am in need of your assistance. Like your enslaved friends, I am a victim of the Lich King's ymirjar and their avarice. When I rose from below to investigate the noises coming from this cavern they captured and chained me.\n\nWill you please help me? The foreman of these mines holds the key to my chains. Kill him!\n\n<You can feel a pushing against your mind as if the creature is trying to coerce you.>", objectives = "" }
WordHunterWoW_QuestEN[13309] = { title = "Assault by Air", description = "I've got some boys suited and ready for their drops inside of Ymirheim. I could use you to see them there safely.\n\nInside the walls, the vrykul have set up some kind of automated spear guns that have been tearing up our transports. We had our engineers install a Suppression Turret to shut down those spear guns - just fire a round near any gun and the smoke should block its sight and clog its gears.\n\nHop on the turret and see to it that all my boys make it to their drops in one piece.", objectives = "" }
WordHunterWoW_QuestEN[13310] = { title = "Assault by Air", description = "Alright scrub, I've got something to keep you from being a complete waste.\n\nA unit of highly trained infiltrators is ready to be dropped inside of Ymirheim. The vrykul inside have automated spear guns that have been ripping our transports to shreds, so we had the engineers on Orgrim's Hammer whip us up a suppression turret.\n\nYou're the gunner. Launch rounds at their spear guns to obscure their vision and clog their gears. See to it that my men all make their drops and the transport stays in one piece.", objectives = "" }
WordHunterWoW_QuestEN[13312] = { title = "The Ironwall Rampart", description = "The Ironwall Rampart overlooks the Valley of Fallen Heroes, west of Aldur'thar. The rampart dominates the fields below on all sides. We will not be able to advance if the rampart cannot be taken, but it is held by Grimkor the Wicked and his Cult of the Damned disciples.\n\nIf you can weaken Grimkor, our forces know what to expect as we advance. Take this rune of distortion. Unleashing its power near Grimkor's orb at the end of the rampart should be enough to get the necromancer's attention.", objectives = "" }
WordHunterWoW_QuestEN[13313] = { title = "Blinding the Eyes in the Sky", description = "The Alliance has somehow managed to field a squadron of recon vehicles over the Valley of Fallen Heroes and Icecrown Glacier, the broad areas west of Aldur'thar.\n\nThey cannot be permitted to take the lead in this fight. Chief Engineer Copperclaw has supplied me with the perfect weapon to deal with this threat -- he calls his new missile the SGM-3. I have his assurances that it will take out the Alliance flying machines in a single hit. Go and use this weapon to give us the upper hand.", objectives = "" }
WordHunterWoW_QuestEN[13314] = { title = "Get the Message", description = "The Horde is up to something and I don't like it. After the stunt they pulled on the Broken Front, they're capable of anything, and it's up to us to stop it.\n\nThere's been a flurry of activity in the skies over the Icecrown Glacier, to the west of Aldur'thar and the Ironwall Rampart. Horde scouts and messengers streak in and out on dragonhawks, carrying reports and orders. Take this dart gun and use it to kill the Orgrim's Hammer Scouts. It'll probably work best if you're flying, too.", objectives = "" }
WordHunterWoW_QuestEN[13315] = { title = "Sneak Preview", description = "Progress is being made. We have a promising array of tactics that should gain us control of the death gate. There will doubtlessly be many casualties, but in the end,  we should be able to prevail - barring any interference from those Horde you insist on contending with...\n\nAt any rate, our next focus will be the gate of desolation. Fly down and become familiar with it and with the enemies posted there.\n\nWhen you return, I will have your missions prepared.", objectives = "" }
WordHunterWoW_QuestEN[13316] = { title = "The Guardians of Corp'rethar", description = "Corp'rethar, called the Horror Gate. It is the last barrier between us and the Icecrown Citadel. It waits to the south of the Ironwall Rampart, beyond the glacier and the Conflagration. By the time our troops reach it, they will be exhausted and worse.\n\nWe must weaken its defenses, or our army's strength will break upon its walls.\n\nIts battlements are manned by some of the Lich King's fiercest and most zealous servants. Do all you can to destroy these guardians and hope it is enough.", objectives = "" }
WordHunterWoW_QuestEN[13318] = { title = "Drag and Drop", description = "The Cult of the Damned hold the gate of desolation, eh? No surprise there.\n\nTime to have a little fun. At the southern end of the gate, you mentioned there were new cultists being trained. They're almost certain to be holding a special item given to all initiates - an Orb of Illusion.\n\nThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.\n\nKill the fools until you find one, {class}, then use it on a subjugator.", objectives = "" }
WordHunterWoW_QuestEN[13319] = { title = "Chain of Command", description = "Based on your report, and my knowledge of the Cult, they have an overseer managing the operation of each encampment on the gate.\n\nWhile taking their leaders down will only be a temporary setback, it will at least slow them down and keep them off-balance. And that, {race}, is a worthy enough goal for now.\n\nSeek out these overseers and return to me when they have been dispatched.", objectives = "" }
WordHunterWoW_QuestEN[13320] = { title = "Cannot Reproduce", description = "I smell their cauldrons from here, but that's not plague they're cooking.\n\nPledges to the cult are forced to drink a concoction that steals their will and enslaves them forever to the Lich King.\n\nSome say the potion contains the twisted soul of a being who was tormented before being mercilessly slaughtered, but I've never been able to reproduce it...\n\nFill this flask with a sample from each of the three cauldrons in the northwest region of the gate and bring it to Chief Engineer Boltwrench.", objectives = "" }
WordHunterWoW_QuestEN[13321] = { title = "Retest Now", description = "This should do the trick!\n\nThose twisted hooligans are looking for souls to put in their crazy-juice? Then I say we help 'em out a bit!\n\nTake a swig of this - don't worry, I've diluted it plenty... I'm almost positive that its only effect will be to detect any cultist's essence once you've defeated them.\n\nWhen you've collected a bunch of them, throw the writhing mass of twisted souls into any of their cauldrons.\n\nLet's see how they like a taste of their own medicine!", objectives = "" }
WordHunterWoW_QuestEN[13322] = { title = "Retest Now", description = "Those twisted cultists are looking for souls to put in their crazy-juice? Then let's help 'em out a bit!\n\nTake a swig of this - don't worry, I've diluted it plenty... I'm almost positive that its only effect will be to detect any cultist's essence.\n\nOnce you've collected a bunch of 'em, throw the writhing mass of twisted souls in one of their cauldrons.\n\nLet's see how they like a taste of their own medicine!", objectives = "" }
WordHunterWoW_QuestEN[13323] = { title = "Drag and Drop", description = "Looks like those initiates are increasing in number again. You know what to do...\n\nAt the southern portion of the gate, the new cultists are being trained. They're certain to be holding a special item given to all initiates - an Orb of Illusion.\n\nThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.\n\nSlay the fools until you find some, then use them on the subjugators there.", objectives = "" }
WordHunterWoW_QuestEN[13328] = { title = "Shatter the Shards", description = "Atop the battlements of Corp'rethar, the Lich King's minions have erected three crystals, the shards of horror, despair, and suffering. Should our men reach the walls of Corp'rethar, he will unleash these weapons on our army.\n\nIn full effect, the crystals will afflict the minds of our men with paralyzing pain and fear. Then, the Scourge will be able to slaughter them at will.\n\nFind these shards, destroy them, and bring me their broken remains. We cannot allow the Lich King to deploy these weapons!", objectives = "" }
WordHunterWoW_QuestEN[13329] = { title = "Before the Gate of Horror", description = "The Conflagration, the ground before Corp'rethar, south of the Ironwall Rampart, is where the Lich King's elite soldiers have formed up to defend the citadel.\n\nLed by a contingent of death knights, a legion of skeletal reavers bars the way. I fear that even when these reavers fall, the Scourge will simply reconstitute them and send them back at us.\n\nI've come up with a plan to stop this, but I have no way of knowing if it will work. Take this solution and use it to dissolve the remains of the reavers.", objectives = "" }
WordHunterWoW_QuestEN[13330] = { title = "Blood of the Chosen", description = "Those vrykul that have gained the favor of the Lich King call themselves the Ymirjar. They inhabit a city in the center of Icecrown. We have a lot of preparations to make before we assault Icecrown Citadel, and the one that stands before us now is routing these so-called \"Chosen\" of the Lich King.\n\nGo to their city, Ymirheim, and slaughter them in their home. Let there be no questions as to who the stronger combatants are here.", objectives = "" }
WordHunterWoW_QuestEN[13331] = { title = "Keeping the Alliance Blind", description = "The Alliance is tenacious, I'll give them that, but it'll take more than that to stop us. Take this SGM-3 with you and shoot down the Skybreaker's recon fighters once again.\n\nI doubt the message will get through their thick skulls, but there are enough missiles to keep trying to get our point across. Go and find their fighters flying above the Valley of Fallen Heroes, west of Aldur'thar, and don't come back until you've made wreckage of them.", objectives = "" }
WordHunterWoW_QuestEN[13332] = { title = "Raise the Barricades", description = "When our forces begin to move beyond Aldur'thar, they will be vulnerable to attack from the Ironwall Rampart and the broad glacier below.\n\nWe have neither the time nor the materials to build fortifications, but we can put up some barricades to shield our men from fire and break up Scourge charges.\n\nTake this barricade kit to the Valley of Fallen Heroes, on the west side of Aldur'thar. Locate the markers I've placed there and use this kit to construct your barricades there.", objectives = "" }
WordHunterWoW_QuestEN[13333] = { title = "Capture More Dispatches", description = "Despite our efforts, the Horde continues to send scouts to the area of the Icecrown Glacier, to the west of the Ironwall Rampart and Aldur'thar.\n\nWe can't afford to let the Horde gain the upper hand with this scouting operation. Take the dart gun with you again and show the Orgrim's Hammer scouts no mercy! Bring the captured dispatches to me.\n\nThe Horde's wasted efforts will be our gain.", objectives = "" }
WordHunterWoW_QuestEN[13334] = { title = "Bloodspattered Banners", description = "In the Valley of Fallen Heroes and Icecrown Glacier, to the west of Aldur'thar, the Scourge seeks to use the fallen against us. Scourge lieutenants have woken the valley's dead and imbued them with fearsome strength and fervor. The banners carried by the Scourge leaders in the glacier area are the source of these powers. Kill the banner-bearers, and you will weaken the converted heroes they lead.\n\nIt falls to you to rid us of this obstacle, and test the resistance before the main body can advance.", objectives = "" }
