WordHunterWoW_QuestEN[13338] = { title = "The Guardians of Corp'rethar", description = "Corp'rethar, called the Horror Gate. It is the last barrier between us and the Icecrown Citadel. It waits to the south of the Ironwall Rampart, beyond the glacier and the Conflagration. By the time our troops reach it, they will be exhausted and worse.\n\nWe must weaken its defenses, or our army's strength will break upon its walls.\n\nIts battlements are manned by some of the Lich King's fiercest and most zealous servants. Do all you can to destroy these guardians and hope it is enough.", objectives = "" }
WordHunterWoW_QuestEN[13339] = { title = "Shatter the Shards", description = "Atop the battlements of Corp'rethar, the Lich King's minions have erected three crystals, the shards of horror, despair, and suffering. Should our men reach the walls of Corp'rethar, he will unleash these weapons on our army.\n\nIn full effect, the crystals will afflict the minds of our men with paralyzing pain and fear. Then, the Scourge will be able to slaughter them at will.\n\nFind these shards, destroy them, and bring me their broken remains. We cannot allow the Lich King to deploy these weapons!", objectives = "" }
WordHunterWoW_QuestEN[13340] = { title = "Joining the Assault", description = "We need more men to join the main assault on Ymirheim.\n\nAny warrior with half a brain can tell you that vrykul are fierce fighters and should not be taken lightly. That goes two-fold for the Ymirjar. They have shown us no restraint in proving why the Lich King deemed them worthy.\n\nGround Commander Xutjja is overseeing the assault. The city itself is located in the center of Icecrown - Xutjja's troops are positioned near the edge of the glacier, north of the city.", objectives = "" }
WordHunterWoW_QuestEN[13341] = { title = "Joining the Assault", description = "We need more men to join the main assault on Ymirheim.\n\nAny warrior with half a brain can tell you that vrykul are fierce fighters and should not be taken lightly. That goes two-fold for the Ymirjar. They have shown no restraint in proving to us why the Lich King deemed them worthy.\n\nGround Commander Koup is overseeing the assault. The city itself is located in the center of Icecrown - Koup's troops are positioned near the edge of the glacier, east of the city.", objectives = "" }
WordHunterWoW_QuestEN[13342] = { title = "Not a Bug", description = "Alright, friend, time to plant a bug.\n\nRelax, it's not a bug exactly, but it'll serve our purposes.\n\nIn the northern portion of Aldur'thar the cult's void summoners enslave demonic minions. Use this rod to siphon the dark matter from the corpses of these enslaved minions, and then use their summoning crystal to bring our little spy into being.\n\nUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.", objectives = "" }
WordHunterWoW_QuestEN[13343] = { title = "Mystery of the Infinite, Redux", description = "There you are! Or, were we just talking?\n\n<Chromie muses over the temporal possibilities.>\n\nAnyway, the Infinites are after you! Well, not you per-se. Rather, they're after the past version of you that defended the Hourglass of Eternity. You remember, right?\n\nThat was you back then, except it's you now too. Wait, that's not important. What is important is that you head back to the Bronze Dragonshrine and defend yourself and the hourglass from their attacks before you get erased from history!", objectives = "" }
WordHunterWoW_QuestEN[13344] = { title = "Not a Bug", description = "The cultists have discovered the last messenger you summoned, {race}.\n\nWhile it was quite informative, it's important that we continue to monitor their every move.\n\nUse this rod to siphon the dark matter from the corpses of enslaved minions at Aldur'thar. Then use their summoning crystal to bring another dark messenger into being.\n\nUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.", objectives = "" }
WordHunterWoW_QuestEN[13345] = { title = "Need More Info", description = "The Cult of the Damned are notorious for concocting grandiose plans that in the end, rarely succeed. But something feels different this time....\n\nPerhaps it's the proximity to the Lich King that has their fervor heightened. Whatever it is, they appear to be more confident than ever. We must know what feeds this bravado and then find a way to strip them of it!\n\nI believe the key lies with their researchers. Find out what they're up to and report back to me with the details.", objectives = "" }
WordHunterWoW_QuestEN[13346] = { title = "No Rest For The Wicked", description = "These fools have actually stumbled upon something that could pose a serious threat to our plans!\n\nThe leader of this particular sect, Alumeth, has ritualistically sacrificed himself and now his underlings are channeling power to his soul.\n\nIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.\n\nCombine his heart, skull, scepter and robes from around their chamber and use his remains on the crystal there.\n\nHurry, {race}! Destroy him before he becomes any more powerful!", objectives = "" }
WordHunterWoW_QuestEN[13348] = { title = "Futility", description = "Do you see now?  Sending your men against the prince's armies just swells their numbers.\n\nI don't expect you to understand... you'll probably just end up like the others.  You'd best return to whoever sent you.  They might be worried.", objectives = "" }
WordHunterWoW_QuestEN[13349] = { title = "Cradle of the Frostbrood", description = "We need to keep our momentum going.  Let's not give the Scourge forces any respite.\n\nSindragosa's Fall lies east just beyond the Valley of Lost Hope.  The Cult of the Damned operate there, under close supervision of the Lich King's undead vrykul lackeys.\n\nIt is a place of great power, possibly a blue dragonflight graveyard.  The feared frostbrood are raised there from the bones of blue dragons.\n\nAn attack there would have great impact on the enemy's access to frost wyrms.  Are you up to it, {name}?", objectives = "" }
WordHunterWoW_QuestEN[13350] = { title = "No Rest For The Wicked", description = "It's Alumeth... He's growing in power again. I can sense it. Again his underlings are channeling power to his soul.\n\nIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.\n\nReturn to his chamber in the north portion of Aldur'thar. Combine his heart, skull, scepter and robes, then use his remains on the crystal there.\n\nHurry, {race}! Destroy him before he becomes any more powerful!", objectives = "" }
WordHunterWoW_QuestEN[13351] = { title = "Sneak Preview", description = "Progress is being made. We have a promising array of tactics that should gain us control of the death gate. There will doubtlessly be many casualties, but in the end,  we should be able to prevail - barring any interference from the Alliance.\n\nOur next focus will be Aldur'thar, the gate of desolation. Fly down and become familiar with it and with the enemies posted there.\n\nWhen you return, I will have your missions prepared.", objectives = "" }
