WordHunterWoW_QuestEN[13358] = { title = "Not a Bug", description = "Alright, friend, time to plant a bug.\n\nRelax, it's not a bug exactly, but it'll serve our purposes.\n\nIn the northern portion of Aldur'thar, the cult's void summoners enslave demonic minions. Use this rod to siphon the dark matter from the corpses of these enslaved minions, and then use the cultists' summoning crystal to bring our little spy into being.\n\nUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.", objectives = "" }
WordHunterWoW_QuestEN[13359] = { title = "Where Dragons Fell", description = "A whole brood of blue dragons fell here.  And now, one by one, they're being raised by his servants.\n\nHe raised the biggest of them all himself.  Bring me some bone dust from the whelps and I'll show you exactly how he did it.", objectives = "" }
WordHunterWoW_QuestEN[13360] = { title = "Time for Answers", description = "You have a lot of questions, {name}.  You're the only one who can see me because you touched something that once belonged to him... don't you remember?\n\nYou don't know what it is?  Well I can't just tell you... that would make him really mad.  He's not just a prince anymore... he's the king!\n\nMeet me at the Court of Bones, north of Icecrown Citadel and you can see for yourself.", objectives = "" }
WordHunterWoW_QuestEN[13361] = { title = "The Hunter and the Prince", description = "Before the prince became a king, he fought many battles... but only one where he came close to dying.\n\nIt was fought right here.  After you let me show you what happened, you'll understand everything.\n\nFind a bloodstained stone and pick it up from the floor.  You'll see what happened.", objectives = "" }
WordHunterWoW_QuestEN[13362] = { title = "Knowledge is a Terrible Burden", description = "Now you know what you're up against, {name}.  An opponent who no longer knows pain... remorse... or humanity.  An opponent who will do anything to get what he wants.\n\nThe heart was his weakness and now he knows you've found it.\n\nIf you're going to go back for it, you'd best bring help.  He will not leave it unguarded again.", objectives = "" }
WordHunterWoW_QuestEN[13363] = { title = "Argent Aid", description = "There were rumors about the events you speak of among the death knights.  I always expected the story to be more... symbolic.\n\nWe must warn others, but we must be discreet.  As soon as the Lich King knows we're making our move, he'll move the location of the heart -- we'll never get a chance like this again.\n\nThe Horde and the Alliance have been infiltrated by the Cult of the Damned before.  The Ebon Blade operates too close to the Scourge.\n\nWe have to speak to Tirion Fordring and his Argent Crusade.", objectives = "" }
WordHunterWoW_QuestEN[13364] = { title = "Tirion's Gambit", description = "Just this morning, my scouts informed me of a Cult of the Damned procession leaving from Icecrown Citadel to the Cathedral of Darkness, bearing an artifact.\n\nAnd now I learn that it might be Arthas's own heart... a thing containing the last bit of his remaining humanity.\n\nThis is a sign of the Light.  As long as such an artifact exists, there is a chance that Arthas Menethil can become a man again!\n\nMeet me at the cathedral's entrance.  Be sure to bring a cultist's hood -- we're going incognito.", objectives = "" }
WordHunterWoW_QuestEN[13365] = { title = "Not a Bug", description = "The cultists have discovered the last messenger you summoned, {race}.\n\nWhile it was quite informative, it's important that we continue to monitor the cult's every move.\n\nUse this rod to siphon the dark matter from the corpses of enslaved minions at Aldur'thar. Then use their summoning crystal to bring another dark messenger into being.\n\nUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.", objectives = "" }
WordHunterWoW_QuestEN[13366] = { title = "Need More Info", description = "The Cult of the Damned are notorious for concocting grandiose plans that in the end, rarely succeed. But something feels different this time....\n\nPerhaps it's the proximity to the Lich King that has their fervor heightened. Whatever it is, they appear to be more confident than ever. We must know what feeds this bravado and then find a way to strip them of it!\n\nI believe the key lies with their researchers. Find out what they're up to and report back to me with the details.", objectives = "" }
WordHunterWoW_QuestEN[13367] = { title = "No Rest For The Wicked", description = "These fools have actually stumbled upon something that could pose a serious threat to our plans!\n\nThe leader of this particular sect, Alumeth, has ritualistically sacrificed himself and now his underlings are channeling power to his soul.\n\nIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.\n\nCombine his heart, skull, scepter and robes from around their chamber and use his remains on the crystal there.\n\nHurry, {race}! Destroy him before he becomes any more powerful!", objectives = "" }
